Object.assign(window.TEM8_DICTIONARY, {"morale":{"media":{"uk":"media/uk/morale__gb_1.mp3","us":"media/us/morale__us_1.mp3"},"oxford":{"phon":"məˈrɑːl","pos":"noun","senses":[{"en":"the amount of confidence and enthusiasm, etc. that a person or a group has at a particular time","cn":"士气","ex":{"en":"to boost/raise/improve morale","cn":"提高士气"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"士气;精神面貌","en":"Morale is the amount of confidence and cheerfulness that a group of people have.","ex":{"en":"Many pilots are suffering from low morale","cn":"很多飞行员目前士气低落。"}}]},"examples":[{"en":"Morale amongst the players is very high at the moment.","cn":"此刻各选手士气高昂。"},{"en":"Staff are suffering from low morale.","cn":"员工士气低落。"}]},"mobility":{"media":{"uk":"media/uk/mobility__gb_1.mp3","us":"media/us/mobility__us_1.mp3"},"oxford":{"phon":"məʊˈbɪləti","pos":"noun","senses":[{"en":"the ability to move easily from one place, social class or job to another","cn":"（住处、社会阶层、职业方面的）流动能力","ex":{"en":"social/geographical/career mobility","cn":"社会地位／区域／职业流动性"}},{"en":"the ability to move or travel around easily","cn":"移动的能力；易于行走的能力","ex":{"en":"An electric wheelchair has given her greater mobility.","cn":"电动轮椅让她行动起来方便多了。"}}]},"examples":[{"en":"An electric wheelchair has given her greater mobility.","cn":"电动轮椅让她行动起来方便多了。"},{"en":"social/geographical/career mobility","cn":"社会地位/区域/职业流动性"}]},"monster":{"media":{"uk":"media/uk/monster__gb_1.mp3","us":"media/us/monster__us_1.mp3"},"oxford":{"phon":"ˈmɒnstə(r)","pos":"noun","senses":[{"en":"(in stories) an imaginary creature that is very large, ugly and frightening","cn":"（传说中的）怪物，怪兽","lab":"figurative","ex":{"en":"a monster with three heads","cn":"三头怪兽"}},{"en":"an animal or a thing that is very large or ugly","cn":"庞然大物；庞大的丑怪物；丑恶的东西","ex":{"en":"Their dog's an absolute monster!","cn":"他们的狗是一头庞然大物！"}},{"en":"a person who is very cruel and evil","cn":"恶棍；恶魔","ex":{"en":"The man is a monster; he terrifies me.","cn":"那男人是个恶棍，我见到他就害怕。"}},{"en":"a child who behaves badly","cn":"小恶魔；小坏蛋","lab":"humorous"},{"en":"unusually large","cn":"巨大的；庞大的","ex":{"en":"monster mushrooms","cn":"巨大的蘑菇"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"怪物;妖物","en":"A monster is a large imaginary creature that looks very ugly and frightening."},{"pos":"N-COUNT 可数名词","cn":"庞然大物;棘手的大事情","en":"A monster is something which is extremely large, especially something which is difficult to manage or which is unpleasant.","ex":{"en":"...the monster which is now the London marathon.","cn":"目前棘手的大事，即伦敦马拉松赛"}},{"pos":"ADJ 形容词","cn":"巨大的;庞大的","en":"Monster means extremely and surprisingly large.","ex":{"en":"...a monster weapon","cn":"巨型武器"}},{"pos":"N-COUNT 可数名词","cn":"残忍的人;吓人的人;恶人","en":"If you describe someone as a monster, you mean that they are cruel, frightening, or evil."}]},"examples":[{"en":"Their dog's an absolute monster!","cn":"他们那条狗好大哟！"},{"en":"monster mushrooms","cn":"巨大的蘑菇"}]},"monk":{"media":{"uk":"media/uk/monk__gb_1.mp3","us":"media/us/monk__us_1.mp3"},"oxford":{"phon":"mʌŋk","pos":"noun","senses":[{"en":"a member of a religious group of men who often live apart from other people in a monastery and who do not marry or have personal possessions","cn":"僧侣；修道士","ex":{"en":"Benedictine/Buddhist monks","cn":"本笃会修士；佛教僧侣"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"僧侣;修道士","en":"A monk is a member of a male religious community that is usually separated from the outside world.","ex":{"en":"...saffron-robed Buddhist monks.","cn":"身着藏红色僧袍的佛教僧侣"}}]},"examples":[{"en":"Benedictine/Buddhist monks","cn":"本笃会修士；佛教僧侣"}]},"motorcyclist":{"media":{"uk":"media/uk/motorcyclist__gb_1.mp3","us":"media/us/motorcyclist__us_1.mp3","img":["media/ldoce/img/motorbike.jpg"]},"oxford":{"phon":"ˈməʊtəsaɪklɪst","pos":"noun","senses":[{"en":"a person riding a motorcycle","cn":"骑摩托车的人","ex":{"en":"a police motorcyclist","cn":"驾驶摩托车的警察"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摩托车手;骑摩托车的人","en":"A motorcyclist is a person who rides a motorcycle."}]},"examples":[{"en":"leather-clad motorcyclists","cn":"穿着皮衣的摩托车手"},{"en":"a police motorcyclist","cn":"驾驶摩托车的警察"}]},"monotonous":{"media":{"uk":"media/uk/monotonous__gb_1.mp3","us":"media/us/monotonous__us_1.mp3"},"oxford":{"phon":"məˈnɒtənəs","pos":"adjective","senses":[{"en":"never changing and therefore boring","cn":"单调乏味的","ex":{"en":"a monotonous voice/diet/routine","cn":"单调乏味的声音／饮食／日常事务"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单调乏味的;毫无变化的","en":"Something that is monotonous is very boring because it has a regular, repeated pattern which never changes.","ex":{"en":"It's monotonous work, like most factory jobs","cn":"与工厂大部分工作一样，这份工作也很单调乏味。"}}]},"examples":[{"en":"New secretaries came and went with monotonous regularity.","cn":"秘书不停地更换，令人厌烦。"},{"en":"a monotonous voice/diet/routine","cn":"单调乏味的声音/饮食/日常事务"}]},"mobile":{"media":{"uk":"media/uk/mobile__gb_1.mp3","us":"media/us/mobile__us_1.mp3"},"oxford":{"phon":"ˈməʊbaɪl","pos":"adjective","senses":[{"en":"connected with mobile phones, tablets, etc.","cn":"手机的；移动设备的","g":"[usually before noun]","ex":{"en":"What's your mobile number?","cn":"你的手机号码是多少？"}},{"en":"that is not fixed in one place and can be moved easily and quickly","cn":"非固定的；可移动的","g":"[usually before noun]","ex":{"en":"mobile equipment","cn":"可移动装备"}},{"en":"able to move or travel around easily","cn":"行动方便；腿脚灵便","g":"[not usually before noun]","ex":{"en":"a kitchen especially designed for people who are less mobile","cn":"专为行动不便的人设计的厨房"}},{"en":"able to change your social class, your job or the place where you live easily","cn":"易于变换社会阶层（或工作、住处）的；流动的","ex":{"en":"a highly mobile workforce (= people who can move easily from place to place)","cn":"具有很强流动性的劳动力"}},{"en":"changing shape or expression easily and often","cn":"多变的；易变的","ex":{"en":"His mobile features registered amusement.","cn":"他表情丰富的脸上流露出愉悦的神情。"}},{"en":"a mobile phone","cn":"手机；移动电话","g":"[countable]","lab":"British English","ex":{"en":"Call me on my mobile.","cn":"打手机给我。"},"pos":"noun"},{"en":"the internet when it is accessed on mobile phones","cn":"移动网络；手机网络","g":"[uncountable]","lab":"British English","ex":{"en":"the rise/importance/growth of mobile","cn":"移动网络的兴起／重要性／增长"},"pos":"noun"},{"en":"a decoration made from wire, etc. that is hung from the ceiling and that has small objects hanging from it which move when the air around them moves","cn":"风铃；（可随风摆动的）悬挂饰物","ex":{"en":"A colourful mobile moved gently above the baby's cot.","cn":"一个彩色挂件在婴儿床上方轻轻摆动。"},"pos":"noun"},{"en":"a city on the coast of the US state of Alabama","cn":"莫比尔（美国亚拉巴马州沿海城市）","pos":""}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"活动的;可轻松移动的","en":"You use mobile to describe something large that can be moved easily from place to place.","ex":{"en":"...special mobile units where men can have their fingerprints taken and donate a specimen of blood.","cn":"人们可以取指纹和捐献血样的特设流动点"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"走动方便的；行动自如的；出行方便的","en":"If you are mobile, you can move or travel easily from place to place, for example because you are not physically disabled or because you have your own transport.","ex":{"en":"I'm still very mobile.","cn":"我仍然行动自如。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(社会)流动性的;(在职业、住所或社会阶层间)自由流动的","en":"In a mobile society, people move easily from one job, home, or social class to another.","ex":{"en":"We're a very mobile society, and people move after they get divorced.","cn":"我们的社会具有很大的流动性，离婚以后人们就会搬家离开。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(面部表情)易变的，多变的","en":"If someone has a mobile face, the expression on their face changes quickly as their feelings change.","ex":{"en":"Robyn had the more mobile, more expressive face.","cn":"罗宾有一张更加善变、表情更加丰富的脸。"}},{"pos":"N-COUNT 可数名词","cn":"(悬挂在天花板上的)风动小饰物","en":"A mobile is a decoration which you hang from a ceiling. It usually consists of several small objects which move as the air around them moves."},{"pos":"N-COUNT 可数名词","cn":"同 mobile phone","en":"A mobile is the same as a mobile phone ."}]},"examples":[{"en":"a kitchen especially designed for the elderly or people who are less mobile","cn":"专门为上了年纪或行动不便的人设计的厨房"},{"en":"You really need to be mobile (= have a car) if you live in the country.","cn":"如果你住在乡村，你确实要有一辆汽车。"}]},"mounting":{"media":{"uk":"media/uk/mounting__gb_1.mp3","us":"media/us/mounting__us_1.mp3"},"oxford":{"phon":"ˈmaʊntɪŋ","pos":"adjective","senses":[{"en":"increasing, often in a manner that causes or expresses worry","cn":"上升的，增长的（常令人担忧）","ex":{"en":"mounting excitement/concern/tension","cn":"越来越兴奋／关注／紧张"}},{"en":"something that an object stands on or is attached to for support","cn":"托架；支撑架","ex":{"en":"The engine came loose from its mountings.","cn":"发动机从托架上松开了。"},"pos":"noun"}]},"examples":[{"en":"There is mounting evidence of serious effects on people's health.","cn":"有越来越多的证据表明对人的健康有严重影响。"},{"en":"The engine came loose from its mountings.","cn":"发动机从托架上松开了。"}]},"move":{"media":{"uk":"media/uk/move__gb_1.mp3","us":"media/us/move__us_1.mp3"},"oxford":{"phon":"muːv","pos":"verb","senses":[{"en":"to change position or make somebody/something change position in a way that can be seen, heard or felt","cn":"（使）改变位置，移动","g":"[intransitive, transitive]","sc":"change position","ex":{"en":"Don't move—stay perfectly still.","cn":"别动，一点都别动。"}},{"en":"to change the place where you live, have your work, etc.","cn":"搬家；搬迁","g":"[intransitive, transitive]","lab":"British English","sc":"change house/job","ex":{"en":"We don't like it here so we've decided to move.","cn":"我们不喜欢这地方，所以决定搬走。"}},{"en":"to make somebody change from one job, class, etc. to another","cn":"使变换；调动","g":"[transitive]","sc":"change house/job","ex":{"en":"I'm being moved to the New York office.","cn":"我要调到纽约办事处去。"}},{"en":"to change the position of a piece","cn":"走棋；移动棋子","g":"[intransitive, transitive]","sc":"in board games","ex":{"en":"It's your turn to move.","cn":"该你走棋了。"}},{"en":"to leave, begin something, etc. quickly","cn":"立刻动身；马上行动","g":"[intransitive]","lab":"informal","sc":"leave/begin","ex":{"en":"Let's move—it's time we went shopping.","cn":"我们走吧，该去买东西了。"}},{"en":"to change; to change something","cn":"变化；改变；转变","g":"[intransitive, transitive]","sc":"change ideas/time","ex":{"en":"The government has not moved on this issue.","cn":"政府在这个问题上立场没有转变。"}},{"en":"to make progress in the way or direction mentioned","cn":"前进；进步；进展","g":"[intransitive]","sc":"make progress","ex":{"en":"Time is moving on.","cn":"时代在进步。"}},{"en":"to take action; to do something","cn":"采取行动；做（事）","g":"[intransitive]","sc":"take action","ex":{"en":"The police moved quickly to dispel the rumours.","cn":"警察迅速采取行动来消除谣言。"}},{"en":"to cause somebody to have strong feelings, especially of sympathy or of being sad","cn":"使感动（尤指因为同情或悲伤）；打动","g":"[transitive]","sc":"cause strong feelings","ex":{"en":"We were deeply moved by her plight.","cn":"她的困境深深地打动了我们。"}},{"en":"to cause somebody to do something","cn":"促使，迫使（某人做某事）；使去做","g":"[transitive]","lab":"formal","sc":"make somebody do something","ex":{"en":"She felt moved to address the crowd.","cn":"她不由得想给大家讲一番话。"}},{"en":"to sell goods; to be sold","cn":"销售；卖出","g":"[transitive, intransitive]","sc":"sell","ex":{"en":"How quickly can we move this stock?","cn":"这批货我们能多快脱手？"}},{"en":"to suggest something formally so that it can be discussed and decided","cn":"（正式地）提出，提议","g":"[transitive]","lab":"formal","sc":"suggest formally","ex":{"en":"The Opposition moved an amendment to the Bill.","cn":"反对党对法案提出修正案。"}},{"en":"a change of place or position","cn":"移动；活动","g":"[usually singular]","sc":"change of position","ex":{"en":"Don't make a move!","cn":"别动！"},"pos":"noun"},{"en":"an act of changing the place where you live or work","cn":"搬家；搬迁；调动","sc":"change of house/job","ex":{"en":"What's the date of your move?","cn":"你什么时候搬家？"},"pos":"noun"},{"en":"an act of changing the position of a piece in chess or other games that are played on a board","cn":"走棋；（棋子的）移动","sc":"in games/sports","ex":{"en":"The game was over in only six moves.","cn":"这盘棋只走了六步就结束了。"},"pos":"noun"},{"en":"an action in a sport or game","cn":"（运动、游戏或比赛中的）动作","sc":"in games/sports","ex":{"en":"In probably the best move of the game, Moseley scored the important try.","cn":"在可能是本场比赛最精彩的一次进攻中，莫斯利完成了关键的达阵得分。"},"pos":"noun"},{"en":"an action that you do or need to do to achieve something","cn":"行动","sc":"action","ex":{"en":"Getting a job in marketing was a good career move.","cn":"找份市场营销的工作是一个不错的职业选择。"},"pos":"noun"},{"en":"a change in ideas, attitudes or behaviour","cn":"改变；转变；动摇","sc":"change of ideas/behaviour","ex":{"en":"There has been a move away from nuclear energy.","cn":"人们对于原子能的看法已经转变。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）移动;（使）活动","en":"When you move something or when it moves, its position changes and it does not remain still.","ex":{"en":"She moved the sheaf of papers into position","cn":"她把那捆报纸挪到合适的地方。"}},{"pos":"VERB 动词","cn":"改变姿势;移动位置","en":"When you move, you change your position or go to a different place.","ex":{"en":"She waited for him to get up, but he didn't move","cn":"她等他起床，但他没动弹。"}},{"pos":"VERB 动词","cn":"采取行动;开始行动","en":"If you move, you act or you begin to do something.","ex":{"en":"Industrialists must move fast to take advantage of new opportunities in Eastern Europe.","cn":"实业家们必须尽快采取行动，抓住东欧的新机遇。"}},{"pos":"N-COUNT 可数名词","cn":"步骤;措施","en":"A move is an action that you take in order to achieve something.","ex":{"en":"The one point cut in interest rates was a wise move","cn":"将利率降低一个点是明智的举措。"}},{"pos":"VERB 动词","cn":"搬家;迁移","en":"If a person or company moves, they leave the building where they have been living or working, and they go to live or work in a different place, taking their possessions with them.","ex":{"en":"My family home is in York-shire and they don't want to move","cn":"我家人住在约克郡，他们不打算搬家。"}},{"pos":"VERB 动词","cn":"调动;派遣","en":"If people in authority move someone, they make that person go from one place or job to another one.","ex":{"en":"His superiors moved him to another parish","cn":"上级把他派往另一个教区。"}},{"pos":"VERB 动词","cn":"变换职业;改变兴趣","en":"If you move from one job or interest to another, you change to it.","ex":{"en":"He moved from being an extramural tutor to being a lecturer in social history","cn":"他原先是一名校外辅导老师，后调入学校讲授社会史。"}},{"pos":"VERB 动词","cn":"改变(谈话内容);转到（新的话题）","en":"If you move to a new topic in a conversation, you start talking about something different.","ex":{"en":"Let's move to another subject, Dan.","cn":"丹，我们换个话题吧。"}},{"pos":"VERB 动词","cn":"改变（…的日期）","en":"If you move an event or the date of an event, you change the time at which it happens.","ex":{"en":"The club has moved its meeting to Saturday, January 22nd","cn":"俱乐部把会议日期改到1月22号，星期六。"}},{"pos":"VERB 动词","cn":"变得；转而","en":"If you move towards a particular state, activity, or opinion, you start to be in that state, do that activity, or have that opinion.","ex":{"en":"The Labour Party has moved to the right and become like your Democrat Party","cn":"工党已右倾化了，变得像你们民主党。"}},{"pos":"VERB 动词","cn":"发展;前进;进展","en":"If a situation or process is moving, it is developing or progressing, rather than staying still.","ex":{"en":"Events are moving fast","cn":"事件进展迅速。"}},{"pos":"VERB 动词","cn":"动摇;改变…的主意","en":"If you say that you will not be moved, you mean that you have come to a decision and nothing will change your mind.","ex":{"en":"Everyone thought I was mad to go back, but I wouldn't be moved.","cn":"大家都认为我回去是很不明智的，但我不会动摇。"}},{"pos":"VERB 动词","cn":"促使;驱使","en":"If something moves you to do something, it influences you and causes you to do it.","ex":{"en":"It was punk that first moved him to join a band seriously","cn":"最初是朋克摇滚乐促使他正式加入了乐队。"}},{"pos":"VERB 动词","cn":"感动;打动","en":"If something moves you, it has an effect on your emotions and causes you to feel sadness or sympathy for another person.","ex":{"en":"These stories surprised and moved me","cn":"这些故事让我吃惊，也让我感动。"}},{"pos":"VERB 动词","cn":"活跃，出入，涉足(于某团体、领域或圈子)","en":"If you say that someone moves in a particular society, circle, or world, you mean that they know people in a particular social class or group and spend most of their time with them.","ex":{"en":"She moves in high-society circles in London","cn":"她时常出入伦敦的上流社会。"}},{"pos":"VERB 动词","cn":"(在会议上)提出(动议)","en":"At a meeting, if you move a motion, you formally suggest it so that everyone present can vote on it.","ex":{"en":"Labour quickly moved a closure motion to end the debate","cn":"工党很快提出终止辩论的动议。"}},{"pos":"N-COUNT 可数名词","cn":"一步(棋);一着(棋)","en":"A move is an act of putting a chess piece or other counter in a different position on a board when it is your turn to do so in a game.","ex":{"en":"With no idea of what to do for my next move, my hand hovered over the board.","cn":"我举着棋子，不知下一步该怎么走。"}},{"pos":"PHRASE 短语","cn":"鲁莽之举;不明智之举","en":"If you say that one false move will cause a disaster, you mean that you or someone else must not make any mistakes because the situation is so difficult or dangerous.","ex":{"en":"He knew one false move would end in death.","cn":"他明白稍有差池就会被置于死地。"}},{"pos":"PHRASE 短语","cn":"快点;抓紧点","en":"If you tell someone to get a move on, you are telling them to hurry."},{"pos":"PHRASE 短语","cn":"离开;出发","en":"If you make a move, you prepare or begin to leave one place and go somewhere else.","ex":{"en":"He glanced at his wristwatch. 'I suppose we'd better make a move.'","cn":"他看一眼手表说：“我想我们最好动身吧。”"}},{"pos":"PHRASE 短语","cn":"采取行动","en":"If you make a move, you take a course of action.","ex":{"en":"The week before the deal was supposed to close, fifteen Japanese banks made a move to pull out","cn":"在预定交易就要结束的前一周，15家日本银行采取行动撤离。"}},{"pos":"PHRASE 短语","cn":"在行进;在迁移","en":"If you are on the move, you are going from one place to another.","ex":{"en":"Jack never wanted to stay in one place for very long, so they were always on the move.","cn":"杰克从不想在一个地方呆太久，所以他们总在奔波辗转。"}},{"pos":"","cn":"","en":"to move the goalposts→see: ; to move heaven and earth→see: ; to move a muscle→see: ;"},{"pos":"","cn":"","en":"相关词组：move about move along move around move away move down move in move into move off move on move out move over move up"}]},"examples":[{"en":"I've been in this job long enough — it's time I moved on.","cn":"这工作我已经干得够久了，我该干点别的了。"},{"en":"There's room for another one if you move up a bit.","cn":"如果你挪开一点，这里还可以容纳多一个人。"}]},"most":{"media":{"uk":"media/uk/most__gb_1.mp3","us":"media/us/most__us_1.mp3"},"oxford":{"phon":"məʊst","pos":"determiner, pronoun","senses":[{"en":"the largest in number or amount","cn":"（数量上）最多，最大","lab":"British English","ex":{"en":"Who do you think will get (the) most votes?","cn":"你认为谁会得到最多的选票？"}},{"en":"more than half of somebody/something; almost all of somebody/something","cn":"大多数；几乎所有","ex":{"en":"I like most vegetables.","cn":"几乎什么蔬菜我都喜欢。"}},{"en":"the furthest","cn":"最远的；最深远的","ex":{"en":"inmost (= the furthest in)","cn":"最深处的"},"pos":"suffix"},{"en":"used to form the superlative of most adjectives and adverbs of two or more syllables","cn":"（与两个或两个以上音节的形容词或副词连用，构成最高级）最","ex":{"en":"the most boring/beautiful part","cn":"最烦人的／最美丽的部分"},"pos":"adverb"},{"en":"to the greatest degree","cn":"（程度上）最大，最多，最高","ex":{"en":"What did you enjoy (the) most?","cn":"你最欣赏的是什么？"},"pos":"adverb"},{"en":"very; extremely; completely","cn":"非常；极其；完全","lab":"formal","ex":{"en":"It was most kind of you to meet me.","cn":"你来接我真是太好了。"},"pos":"adverb"},{"en":"almost","cn":"几乎；差不多","lab":"North American English, informal，，","ex":{"en":"I go to the store most every day.","cn":"我几乎每天都去商店。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"大多数;大部分","en":"You use most to refer to the majority of a group of things or people or the largest part of something.","ex":{"en":"Most of the houses in the capital don't have piped water","cn":"首都的大部分房屋没有自来水。"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"最多的;最大量的","en":"You use the most to mean a larger amount than anyone or anything else, or the largest amount possible.","ex":{"en":"The President himself won the most votes","cn":"总统本人获得最多选票。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"尤其;最为","en":"You use most to indicate that something is true or happens to a greater degree or extent than anything else.","ex":{"en":"What she feared most was becoming like her mother","cn":"她最怕的就是变得像她妈妈那样。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"最;极其","en":"You use most to indicate that someone or something has a greater amount of a particular quality than most other things of its kind.","ex":{"en":"Her children had the best, most elaborate birthday parties in the neighborhood","cn":"她的孩子们的生日聚会在街坊四邻里是最好、最讲究的。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"最大限度地;最频繁地;最多地","en":"If you do something the most, you do it to the greatest extent possible or with the greatest frequency.","ex":{"en":"What question are you asked the most?","cn":"你们被问及最多的问题是什么？"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"(在谈话中用于引起注意)最…，极其…","en":"You use most in conversations when you want to draw someone's attention to something very interesting or important that you are about to say.","ex":{"en":"Most surprisingly, quite a few said they don't intend to vote at all","cn":"最让人吃惊的是，相当多的人说他们根本不打算参加投票。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"十分;非常","en":"You use most to emphasize an adjective or adverb.","ex":{"en":"I'll be most pleased to speak to them","cn":"能跟他们谈谈我会十分高兴。"}},{"pos":"PHRASE 短语","cn":"至多;最多","en":"You use at most or at the most to say that a number or amount is the maximum that is possible and that the actual number or amount may be smaller.","ex":{"en":"Poach the pears in apple juice for perhaps ten minutes at most.","cn":"把梨放入苹果汁中，最多煮10分钟左右。"}},{"pos":"PHRASE 短语","cn":"尽量利用;充分利用","en":"If you make the most of something, you get the maximum use or advantage from it.","ex":{"en":"Happiness is the ability to make the most of what you have","cn":"幸福就是有能力充分享受你拥有的一切。"}},{"pos":"","cn":"","en":"for the most part→see: ;"}]},"examples":[{"en":"As most of you know, I've decided to resign.","cn":"你们大多数人都知道，我已经决定辞职了。"},{"en":"This technique looks easy, but it most certainly is not.","cn":"这项技术看上去简单，但绝不是那么回事。"}]},"mo":{"oxford":{"phon":"məʊ","pos":"noun","senses":[{"en":"a very short period of time","cn":"顷刻；瞬间","ex":{"en":"See you in a mo!","cn":"一会儿见！"}},{"en":"medical officer","cn":"（某机构的）专职医生","lab":"British English"},{"en":"modus operandi","cn":"工作方法"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"瞬间，顷刻（moment的缩写）","en":"A mo is a very short length of time. It is short for moment .","ex":{"en":"Hang on a mo.","cn":"等一下，别挂。"}}]},"media":{"uk":"media/uk/mo__gb_1.mp3","us":"media/us/mo__us_1.mp3"},"examples":[{"en":"See you in a mo!","cn":"一会儿见！"},{"en":"Wait a mo!","cn":"等一会儿！"}]},"modesty":{"media":{"uk":"media/uk/modesty__gb_1.mp3","us":"media/us/modesty__us_1.mp3"},"oxford":{"phon":"ˈmɒdəsti","pos":"noun","senses":[{"en":"the fact of not talking much about your abilities or possessions","cn":"谦虚；谦逊","ex":{"en":"He accepted the award with characteristic modesty.","cn":"他以他一贯的谦逊态度接受了奖项。"}},{"en":"the action of behaving or dressing so that you do not show your body or attract sexual attention","cn":"庄重；朴素；贤淑","ex":{"en":"I wore a towel to preserve my modesty.","cn":"为了不失体面，我围了一条大毛巾。"}},{"en":"the state of being not very large, expensive, important, etc.","cn":"不突出；有限","ex":{"en":"They tried to disguise the modesty of their achievements.","cn":"他们不想让人知道自己取得的那一点成绩。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"谦虚;谦逊;谦恭","en":"Someone who shows modesty does not talk much about their abilities or achievements.","ex":{"en":"His modesty does him credit, for the food he produces speaks for itself","cn":"他的谦逊值得赞扬，因为他做的食物品质之高显而易见。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(地方)小;(数量等)少，有限","en":"You can refer to the modesty of something such as a place or amount when it is fairly small.","ex":{"en":"The modesty of the town itself comes as something of a surprise.","cn":"这座城市本身就小得让人惊讶。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指女性的）端庄，庄重","en":"If someone, especially a woman, shows modesty, they are cautious about the way they dress and behave because they are aware that other people may view them in a sexual way.","ex":{"en":"There were shrieks of embarrassment as the girls struggled to protect their modesty.","cn":"竭力保持着端庄形象的女孩们发出了尴尬的尖叫。"}}]},"examples":[{"en":"They tried to disguise the modesty of their achievements.","cn":"他们成就不大，所以力图掩盖这一点。"},{"en":"He accepted the award with characteristic modesty.","cn":"他以他一贯的谦逊态度接受了奖项。"}]},"mouth":{"media":{"uk":"media/uk/mouth__gb_1.mp3","us":"media/us/mouth__us_1.mp3"},"oxford":{"phon":"maʊθ","pos":"noun","senses":[{"en":"the opening in the face used for speaking, eating, etc.; the area inside the head behind this opening","cn":"嘴；口","sc":"part of face","ex":{"en":"She opened her mouth to say something.","cn":"她张开嘴要说什么。"}},{"en":"a person considered only as somebody who needs to be provided with food","cn":"需要供养的人","sc":"person needing food","ex":{"en":"Now there would be another mouth to feed.","cn":"现在又多一个要吃饭的人。"}},{"en":"the place where a river joins the sea","cn":"入海口；河口","sc":"of river","ex":{"en":"A number of industries sprang up around the mouth of the river.","cn":"河口周边涌现出一批工业企业。"}},{"en":"the entrance or opening of something","cn":"入口；开口","sc":"entrance/opening","ex":{"en":"the mouth of a cave/pit","cn":"山洞口；矿井口"}},{"en":"a particular way of speaking","cn":"讲话方式；言谈","sc":"way of speaking","ex":{"en":"He has a foul mouth on him!","cn":"他满嘴脏话！"}},{"en":"having the type or shape of mouth mentioned","cn":"有…嘴的；…口的","sc":"-mouthed","ex":{"en":"a round, wide-mouthed face","cn":"圆脸、宽嘴"}},{"en":"having a particular way of speaking","cn":"言谈…的；口齿…的","sc":"-mouthed","ex":{"en":"a rather crude-mouthed individual","cn":"言谈非常粗鲁的人"}},{"en":"to move your lips as if you were saying something, but without making a sound","cn":"（动嘴唇）不出声地说","ex":{"en":"He mouthed a few obscenities at us and then moved off.","cn":"他不出声地朝我们骂了几句脏话，然后走了。"},"pos":"verb"},{"en":"to say something that you do not really feel, believe or understand","cn":"言不由衷地说","lab":"disapproving","ex":{"en":"They're just mouthing empty slogans.","cn":"他们只是在空喊口号。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"口;嘴","en":"Your mouth is the area of your face where your lips are or the space behind your lips where your teeth and tongue are.","ex":{"en":"She clamped her hand against her mouth","cn":"她用手捂着嘴。"}},{"pos":"N-COUNT 可数名词","cn":"说话方式;言谈","en":"You can say that someone has a particular kind of mouth to indicate that they speak in a particular kind of way or that they say particular kinds of things.","ex":{"en":"I've always had a loud mouth, I refuse to be silenced","cn":"我一贯大声说出自己的想法，不会迫于压力而一言不发。"}},{"pos":"N-COUNT 可数名词","cn":"(洞的)出入口；(瓶)口","en":"The mouth of a cave, hole, or bottle is its entrance or opening.","ex":{"en":"By the mouth of the tunnel he bent to retie his lace.","cn":"到隧道出入口时，他弯腰重新系好鞋带。"}},{"pos":"N-COUNT 可数名词","cn":"河口;入海口","en":"The mouth of a river is the place where it flows into the sea.","ex":{"en":"...the town at the mouth of the River Dart.","cn":"位于达特河入海口的城镇"}},{"pos":"VERB 动词","cn":"不出声地说;用口型默示","en":"If you mouth something, you form words with your lips without making any sound.","ex":{"en":"I mouthed a goodbye and hurried in behind Momma","cn":"我用口型默示告别，然后匆匆跟在妈妈身后走了进去。"}},{"pos":"VERB 动词","cn":"言不由衷地说；信口说；不知所云地说","en":"If you mouth something, you say it, especially without believing it or without understanding it.","ex":{"en":"I mouthed some sympathetic platitudes","cn":"我言不由衷地说了一些表示同情的客套话。"}},{"pos":"PHRASE 短语","cn":"需要赡养的人;要养活的人","en":"If you have a number of mouths to feed, you have the responsibility of earning enough money to feed and look after that number of people.","ex":{"en":"He had to feed his family on the equivalent of four hundred pounds a month and, with five mouths to feed, he found this very hard.","cn":"他要用相当于400英镑的月收入来维持五口之家的生计，感觉很艰难。"}},{"pos":"PHRASE 短语","cn":"开口说话;发言","en":"If you say that someone does not open their mouth, you are emphasizing that they never say anything at all.","ex":{"en":"Sometimes I hardly dare open my mouth","cn":"有时我几乎不敢开口说话。"}},{"pos":"PHRASE 短语","cn":"保持缄默;守口如瓶","en":"If you keep your mouth shut about something, you do not talk about it, especially because it is a secret.","ex":{"en":"You wouldn't be here now if she'd kept her mouth shut.","cn":"如果她守口如瓶的话，你现在就不会在这儿啦。"}},{"pos":"","cn":"","en":"to live hand to mouth→see: ; heart in your mouth→see: ; from the horse's mouth→see: ; to put your money where your mouth is→see: ; shut your mouth→see: ; to be born with a silver spoon in your mouth→see: ; word of mouth→see: ; to put words into someone's mouth→see: ;"}]},"examples":[{"en":"Now she's upset — why couldn't you keep your mouth shut?","cn":"瞧她现在心烦意乱的样子，你就不能闭上嘴？"},{"en":"He mouthed a few obscenities at us and then moved off.","cn":"他不出声地朝我们骂了几句脏话然后离去。"}]},"mother":{"media":{"uk":"media/uk/mother__gb_1.mp3","us":"media/us/mother__us_1.mp3"},"oxford":{"phon":"ˈmʌðə(r)","pos":"noun","senses":[{"en":"a female parent of a child or animal; a person who is acting as a mother to a child","cn":"母亲；妈妈","ex":{"en":"I want to buy a present for my mother and father.","cn":"我想给爸爸妈妈买件礼物。"}},{"en":"the title of a woman who is head of a convent (= a community of nuns)","cn":"（对女修道院院长的尊称）"},{"en":"to care for somebody/something because you are their mother, or as if you were their mother","cn":"给以母亲的关爱；像母亲般地照顾","ex":{"en":"He was a disturbed child who needed mothering.","cn":"他是个心理失常的孩子，需要悉心照顾。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"母亲;妈妈","en":"Your mother is the woman who gave birth to you. You can also call someone your mother if she brings you up as if she was this woman.","ex":{"en":"She sat on the edge of her mother's bed","cn":"她坐在母亲床边。"}},{"pos":"VERB 动词","cn":"(通常指母亲)照看，抚养，养育","en":"If a woman mothers a child, she looks after it and brings it up, usually because she is its mother.","ex":{"en":"Colleen had dreamed of mothering a large family.","cn":"科琳曾梦想抚养一群孩子。"}},{"pos":"VERB 动词","cn":"爱护;溺爱","en":"If you mother someone, you treat them with great care and affection, as if they were a small child.","ex":{"en":"She felt a great need to mother him","cn":"她迫切地感到要细心照料他。"}}]},"examples":[{"en":"He was a disturbed child who needed mothering.","cn":"他是个心理失常的孩子，需要悉心照顾。"},{"en":"I got stuck in the mother of all traffic jams.","cn":"我被困在一次超级严重的大塞车之中。"}]},"motivate":{"media":{"uk":"media/uk/motivate__gb_1.mp3","us":"media/us/motivate__us_1.mp3"},"oxford":{"phon":"ˈməʊtɪveɪt","pos":"verb","senses":[{"en":"to be the reason why somebody does something or behaves in a particular way","cn":"成为…的动机；是…的原因","g":"[often passive]","ex":{"en":"What motivates people to carry out such attacks?","cn":"是什么原因致使人们进行这样的攻击？"}},{"en":"to make somebody want to do something, especially something that involves hard work and effort","cn":"推动…甘愿苦干；激励；激发","ex":{"en":"She's very good at motivating her students.","cn":"她非常擅长激励她的学生。"}},{"en":"to give reasons for something that you have stated","cn":"（就所说的话）给出理由；说明…的原因","lab":"South African English, formal，，","ex":{"en":"Please motivate your answer to question 5.","cn":"请解释你对第 5 题所作的回答。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指情绪)激发，激励，驱使","en":"If you are motivated by something, especially an emotion, it causes you to behave in a particular way.","ex":{"en":"They are motivated by a need to achieve","cn":"对成功的渴望激励着他们。"}},{"pos":"VERB 动词","cn":"使决心做;使决意做","en":"If someone motivates you to do something, they make you feel determined to do it.","ex":{"en":"How do you motivate people to work hard and efficiently?","cn":"你是怎样激励大家奋发高效地工作的？"}}]},"examples":[{"en":"The plan is designed to motivate employees to work more efficiently.","cn":"这个计划旨在促使员工更加卓有成效地工作。"},{"en":"Most people said that pay was their main motivation for working.","cn":"大多数人说赚取报酬是他们工作的主要动机。"}]},"movie":{"media":{"uk":"media/uk/movie__gb_1.mp3","us":"media/us/movie__us_1.mp3"},"oxford":{"phon":"ˈmuːvi","pos":"noun","senses":[{"en":"a series of moving pictures recorded with sound that tells a story, watched at a movie theater or on a television or other device","cn":"电影","g":"[countable]","lab":"British English","ex":{"en":"You'll love this movie.","cn":"你会喜欢这部电影的。"}},{"en":"when you go to the movies, you go to a movie theater to see a movie","cn":"（去电影院）看电影","g":"[plural]","ex":{"en":"Let's go to the movies.","cn":"我们去看电影吧。"}},{"en":"movies as an art or an industry","cn":"电影艺术；电影业","g":"[plural]","ex":{"en":"I've always wanted to work in the movies.","cn":"我一直想从事电影业。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电影;影片","en":"A movie is a film.","ex":{"en":"In the first movie Tony Curtis ever made he played a grocery clerk.","cn":"托尼·柯蒂斯在其首部电影里，扮演了一个食品杂货店店员。"}},{"pos":"N-PLURAL 复数名词","cn":"看电影","en":"You can talk about the movies when you are talking about seeing a movie in a movie theater.","ex":{"en":"He took her to the movies.","cn":"他带她去看电影。"}}]},"examples":[{"en":"Have you seen the latest Miyazaki movie?","cn":"你看过宫崎骏的新电影吗？"},{"en":"I've always wanted to work in the movies.","cn":"我一直想从事电影业。"}]},"modulation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the sound of your voice","cn":""},{"en":"to change a process or activity to make it more controlled, slower, less strong etc","cn":""}]},"examples":[{"en":"These drugs modulate the disease process.","cn":"","src":"ld"}],"media":{"uk":"media/uk/modulation__gb_1.mp3","us":"media/us/modulation__us_1.mp3"},"oxford":{"phon":"ˌmɒdjəˈleɪʃn","pos":"noun","senses":[{"en":"the act of changing the quality of your voice in order to create a particular effect by making it louder, softer, lower, etc.","cn":"调节（嗓音的大小、强弱、高低等）","ex":{"en":"Her vocal modulation was most impressive.","cn":"她的声音调节给人留下了最深刻的印象。"}},{"en":"a change from one musical key (= set of notes) to another","cn":"变调；转调","lab":"music","ex":{"en":"the harmony and modulations of JS Bach","cn":"巴赫的和声与变调。"}},{"en":"the act of changing the rate at which a sound wave or radio signal vibrates (= the frequency) so that it is clearer","cn":"调制（声波或无线电波频率）；调谐","lab":"specialist","ex":{"en":"Radio transmission employs deliberate modulation of a complex audio signal.","cn":"无线电传输采用复杂音频信号的有意调制。"}},{"en":"the act of influencing something by changing or controlling it","cn":"调节，适应","lab":"specialist","ex":{"en":"This effect indicates long-lasting modulation of neural activity.","cn":"这种效应表明神经活动的持久调节。"}}]}},"monotony":{"media":{"uk":"media/uk/monotony__gb_1.mp3","us":"media/us/monotony__us_1.mp3"},"oxford":{"phon":"məˈnɒtəni","pos":"noun","senses":[{"en":"boring lack of variety","cn":"单调乏味；千篇一律","ex":{"en":"She watches television to relieve the monotony of everyday life.","cn":"她天天靠看电视来解闷儿。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"单调乏味;无变化;一成不变","en":"The monotony of something is the fact that it never changes and is boring.","ex":{"en":"A night on the town may help to break the monotony of the week.","cn":"进城住一晚或许有助于消除一周生活的单调。"}}]},"examples":[{"en":"She watches television to relieve the monotony of everyday life.","cn":"她天天靠看电视来解闷儿。"}]},"moustache":{"oxford":{"phon":"ˈmʌstæʃ","pos":"noun","senses":[{"en":"a line of hair that a man allows to grow on his upper lip","cn":"上唇的胡子；髭","lab":"informal","ex":{"en":"He's trying to grow a moustache.","cn":"他在留小胡子。"}},{"en":"a very long moustache","cn":"长髭","g":"[plural]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(较长时称作 moustaches)髭，八字胡，八字须","en":"A man's moustache is the hair that grows on his upper lip. If it is very long, it is sometimes referred to as his moustaches .","ex":{"en":"He was short and bald and had a moustache.","cn":"他个头不高，秃顶，留着八字胡。"}}]},"media":{"uk":"media/uk/moustache__gb_1.mp3","us":"media/us/moustache__us_1.mp3"},"examples":[{"en":"He’s shaved off his moustache.","cn":"他剃去了小胡子。"}]},"modern-day":{"oxford":{"phon":"ˌmɒdn ˈdeɪ","pos":"adjective","senses":[{"en":"of the present time","cn":"现代的；当代的","ex":{"en":"modern-day America","cn":"当代美国"}},{"en":"used to describe a modern form of somebody/something, usually somebody/something bad or unpleasant, that existed in the past","cn":"现代版的，翻新的（通常用于消极事物）","ex":{"en":"It has been called modern-day slavery.","cn":"人们称之为现代版的奴隶制度。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"现代的;当代的","en":"Modern-day is used to refer to the new or modern aspects of a place, an activity, or a society.","ex":{"en":"...modern-day America.","cn":"当代美国"}}]},"media":{"uk":"media/uk/modern_day_1_gb_1.mp3","us":"media/us/modern_day_1_us_1.mp3"},"examples":[{"en":"It has been called modern-day slavery.","cn":"人们称之为现代版的奴隶制度。"},{"en":"modern-day America","cn":"当代美国"}]},"moneys":{"oxford":{"phon":"ˈmʌni","pos":"noun","senses":[{"en":"what you earn by working or selling things, and use to buy things","cn":"钱；薪水；收入"},{"en":"coins or paper notes","cn":"钱币；钞票"}]},"media":{"img":["media/pic/money_comp.jpg","media/thumb/coin.jpg"],"uk":"media/uk/money__gb_1.mp3","us":"media/us/money__us_1.mp3"}},"modal":{"oxford":{"phon":"ˈməʊdl","pos":"adjective","senses":[{"en":"connected with the class of verbs such as can, may or will that are used with other verbs (not modals) to express possibility, permission, intention, etc.","cn":"情态动词的"},{"en":"a verb such as can, may or will that is used with another verb (not a modal) to express possibility, permission, intention, etc.","cn":"情态动词（如 can、may 或 will 等，和实义动词连用表示可能、许可、意图等）","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"情态（助）动词","en":"In grammar, a modal or a modal auxiliary is a word such as 'can' or 'would' which is used with a main verb to express ideas such as possibility, intention, or necessity."}]},"media":{"uk":"media/uk/modal__gb_1.mp3","us":"media/us/modal__us_1.mp3"},"examples":[{"en":"I used to smoke but I gave up two years ago.","cn":"我过去抽烟，但两年前就戒了。"},{"en":"She will try and visit tomorrow.","cn":"她明天将设法去参观。"}]},"modes":{"oxford":{"phon":"məʊd","pos":"noun","senses":[{"en":"a particular way of doing sth; a particular type of sth","cn":"方式；风格；样式"},{"en":"the way in which a piece of equipment is set to perform a particular task （","cn":"设备的）模式，工作状态"}]}},"monastery":{"media":{"uk":"media/uk/monastery__gb_1.mp3","us":"media/us/monastery__us_1.mp3"},"oxford":{"phon":"ˈmɒnəstri","pos":"noun","senses":[{"en":"a building in which monks (= members of a male religious community) live together","cn":"隐修院；修道院；寺院","lab":"North American English","ex":{"en":"He lived in a monastery for most of his life.","cn":"他一生大部份时间都住在隐修院里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"寺院;隐修院","en":"A monastery is a building or collection of buildings in which monks live."}]}},"momentary":{"media":{"uk":"media/uk/momentary__gb_1.mp3","us":"media/us/momentary__us_1.mp3"},"oxford":{"phon":"ˈməʊməntri","pos":"adjective","senses":[{"en":"lasting for a very short time","cn":"短促的；短暂的；片刻的","ex":{"en":"The accident was the result of a momentary lapse of concentration.","cn":"那起事故是因为一时走神造成的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"瞬息的;片刻的;短暂的","en":"Something that is momentary lasts for a very short period of time, for example for a few seconds or less.","ex":{"en":"...a momentary lapse of concentration","cn":"片刻的走神儿"}}]},"examples":[{"en":"momentary confusion","cn":"一时糊涂"},{"en":"a momentary lapse of concentration","cn":"走神儿"}]},"mount":{"media":{"uk":"media/uk/mount__gb_1.mp3","us":"media/us/mount__us_1.mp3"},"oxford":{"phon":"maʊnt","pos":"verb","senses":[{"en":"to organize and begin something","cn":"准备；安排；组织开展","g":"[transitive]","sc":"organize","ex":{"en":"Residents mounted a campaign to fight the plans.","cn":"居民们发起了一场运动对抗这些计划。"}},{"en":"to increase gradually","cn":"逐步增加","g":"[intransitive]","sc":"increase","ex":{"en":"Pressure is mounting on the government to change the law.","cn":"迫使政府修改法律的压力不断增加。"}},{"en":"to get on a bicycle, horse, etc. in order to ride it","cn":"骑上；乘上；跨上","g":"[transitive, intransitive]","lab":"rather formal","sc":"bicycle/horse","ex":{"en":"He mounted his horse and rode away.","cn":"他骑上马走了。"}},{"en":"to go up something, or up on to something that is raised","cn":"登上；爬上；攀登","g":"[transitive]","lab":"formal","sc":"go up something","ex":{"en":"She slowly mounted the steps.","cn":"她慢慢地爬上台阶。"}},{"en":"to fix something into position on something, so that you can use it, look at it or study it","cn":"镶嵌；安置","g":"[transitive]","sc":"camera/picture/jewel, etc.","ex":{"en":"Cameras are mounted around the city.","cn":"在城市各处安装了摄像头。"}},{"en":"to get onto the back of a female animal in order to have sex","cn":"爬上（雌性动物的背）交配","g":"[transitive]","sc":"of male animal"},{"en":"a mountain or a hill","cn":"山；山峰","sc":"mountain","ex":{"en":"Mt Kilimanjaro","cn":"乞力马扎罗山"},"pos":"noun"},{"en":"a horse that you ride on","cn":"坐骑","lab":"formal or literary","sc":"horse","ex":{"en":"She saddled her mount quickly.","cn":"她迅速给坐骑装上马鞍。"},"pos":"noun"},{"en":"something such as a piece of card or glass that you put something on or attach something to, to display it","cn":"衬纸板；载片；裱褙","sc":"for displaying/supporting something","pos":"noun"},{"en":"something that an object stands on or is attached to for support","cn":"托架；支撑架","sc":"for displaying/supporting something","ex":{"en":"an engine/gun mount","cn":"发动机架；炮架"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"组织;发起;开展","en":"If you mount a campaign or event, you organize it and make it take place.","ex":{"en":"The ANC announced it was mounting a major campaign of mass political protests.","cn":"非洲人国民大会宣布他们正在开展一次大规模政治抗议活动。"}},{"pos":"VERB 动词","cn":"增强;加剧","en":"If something mounts, it increases in intensity.","ex":{"en":"For several hours, tension mounted","cn":"有几个小时，紧张局势有所加剧。"}},{"pos":"VERB 动词","cn":"增多;增加","en":"If something mounts, it increases in quantity.","ex":{"en":"The uncollected garbage mounts in city streets","cn":"未收的垃圾在市区街道上越积越多。"}},{"pos":"VERB 动词","cn":"爬上，登上(台阶、梯级)","en":"If you mount the stairs or a platform, you go up the stairs or go up onto the platform.","ex":{"en":"Llewelyn was mounting the stairs up into the keep","cn":"卢埃林登上台阶，走进城堡主楼。"}},{"pos":"VERB 动词","cn":"骑上(马、自行车等)","en":"If you mount a horse or cycle, you climb on to it so that you can ride it.","ex":{"en":"He mounted his horse and rode away","cn":"他骑上马走了。"}},{"pos":"N-COUNT 可数名词","cn":"坐骑;马","en":"A mount is a horse.","ex":{"en":"...the number of owners who care for older mounts.","cn":"愿意照料老马的马主的数量"}},{"pos":"VERB 动词","cn":"安装;安置;裱","en":"If you mount an object on something, you fix it there firmly.","ex":{"en":"Her husband mounts the work on velour paper and makes the frame","cn":"她丈夫把作品装裱在绒纸上，并制作了画框。"}},{"pos":"VERB 动词","cn":"组织，举办(展览或展示)","en":"If you mount an exhibition or display, you organize and present it.","ex":{"en":"The gallery has mounted an exhibition of art by Irish women painters.","cn":"画廊已举办了一场爱尔兰女画家的作品展。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于山的名称中)山","en":"Mount is used as part of the name of a mountain.","ex":{"en":"...Mount Kilimanjaro.","cn":"乞力马扎罗山"}},{"pos":"","cn":"","en":"相关词组：mount up"}]},"examples":[{"en":"Pressure is mounting on the government to change the law.","cn":"迫使政府修改法律的压力不断增加。"},{"en":"Meanwhile, my debts were mounting up.","cn":"同时，我的债务还在不断增加。"}]},"monetary":{"media":{"uk":"media/uk/monetary__gb_1.mp3","us":"media/us/monetary__us_1.mp3"},"oxford":{"phon":"ˈmʌnɪtri","pos":"adjective","senses":[{"en":"connected with money, especially all the money in a country","cn":"货币的，钱的（尤指一国的货币）","ex":{"en":"monetary policy/growth","cn":"货币政策／增长"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指一国）货币的，金融的","en":"Monetary means relating to money, especially the total amount of money in a country.","ex":{"en":"Some countries tighten monetary policy to avoid inflation","cn":"一些国家实行紧缩银根的货币政策，以避免通货膨胀。"}}]},"examples":[{"en":"closer European political, monetary and economic union","cn":"更为密切的欧洲政治、货币及经济联盟"},{"en":"an item of little monetary value","cn":"不怎么值钱的东西"}]},"mosque":{"media":{"uk":"media/uk/mosque__gb_1.mp3","us":"media/us/mosque__us_1.mp3"},"oxford":{"phon":"mɒsk","pos":"noun","senses":[{"en":"a building where Muslims go for prayer","cn":"清真寺","ex":{"en":"I used to pray at the local mosque with my father and grandfather.","cn":"我曾经和父亲和祖父一起在当地的清真寺祈祷。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"清真寺","en":"A mosque is a building where Muslims go to worship."}]}},"morbid":{"media":{"uk":"media/uk/morbid__gb_1.mp3","us":"media/us/morbid__us_1.mp3"},"oxford":{"phon":"ˈmɔːbɪd","pos":"adjective","senses":[{"en":"having or expressing a strong interest in sad or unpleasant things, especially disease or death","cn":"病态的；不正常的","ex":{"en":"He had a morbid fascination with blood.","cn":"他对血有着一种病态的喜好。"}},{"en":"connected with disease","cn":"病的；与疾病相关的","lab":"medical"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"病态的;不正常的；心理不健康的","en":"If you describe a person or their interest in something as morbid, you mean that they are very interested in unpleasant things, especially death, and you think this is strange.","ex":{"en":"Some people have a morbid fascination with crime.","cn":"一些人对犯罪有一种病态的痴迷。"}}]},"examples":[{"en":"‘He might even die.’ ‘Don't be so morbid.’ “","cn":"他甚至会死的。” “别胡思乱想。”"},{"en":"He had a morbid fascination with blood.","cn":"他对血有着一种病态的喜好。"}]},"motionless":{"media":{"uk":"media/uk/motionless__gb_1.mp3","us":"media/us/motionless__us_1.mp3"},"oxford":{"phon":"ˈməʊʃnləs","pos":"adjective","senses":[{"en":"not moving; still","cn":"静止的；一动不动的","ex":{"en":"She stood absolutely motionless.","cn":"她纹丝不动地站在那里。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不动的;静止的","en":"Someone or something that is motionless is not moving at all.","ex":{"en":"He has this ability of being able to remain as motionless as a statue, for hours on end","cn":"他有本事连续几个小时一动不动，像雕塑一样。"}}]},"examples":[{"en":"She stood absolutely motionless.","cn":"她纹丝不动地站在那里。"}]},"motivated":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very keen to do something or achieve something, especially because you find it interesting or exciting","cn":"积极的﹐主动的"},{"en":"done for political, economic etc reasons","cn":"受政治/经济/财政等方面原因驱使的"}]},"examples":[{"en":"The students are all highly motivated .","cn":"学生们都有很高的积极性。","src":"ld"},{"en":"The key to a successful modern economy is a well-educated and motivated workforce.","cn":"成功的现代经济关键是要有受过良好教育﹑积极主动的劳动力。","src":"ld"}],"media":{"uk":"media/uk/motivated__gb_1.mp3","us":"media/us/motivated__us_1.mp3"},"oxford":{"phon":"ˈməʊtɪveɪtɪd","pos":"adjective","senses":[{"en":"done or happening for a particular reason","cn":"有动机的：由于特定原因而完成或正在发生","ex":{"en":"a racially motivated attack","cn":"种族问题引发的攻击"}},{"en":"wanting to do something, especially something that involves hard work and effort","cn":"想做某事，尤指需要努力工作的事情","ex":{"en":"a highly motivated student","cn":"学习积极性很高的学生"}}]}},"moon":{"media":{"uk":"media/uk/moon__gb_1.mp3","us":"media/us/moon__us_1.mp3"},"oxford":{"phon":"muːn","pos":"noun","senses":[{"en":"the round object that moves around the earth once every 27½ days and shines at night by light reflected from the sun","cn":"月球","g":"[singular]","ex":{"en":"the surface of the moon","cn":"月球表面"}},{"en":"the moon as it appears in the sky at a particular time","cn":"月亮；月相","g":"[singular]","ex":{"en":"a crescent moon","cn":"新月"}},{"en":"a natural satellite that moves around a planet other than the earth","cn":"卫星","g":"[countable]","ex":{"en":"How many moons does Jupiter have?","cn":"木星有多少颗卫星？"}},{"en":"to show your bottom to people in a public place as a joke or a way to cause offence","cn":"（在公共场所）向…露臀（搞恶作剧或侮辱他人）","ex":{"en":"The crew dropped their trousers and mooned at the people on the shore.","cn":"船员们脱下裤子，呆呆地看着岸上的人们。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"月亮;月球","en":"The moon is the object that you can often see in the sky at night. It goes round the Earth once every four weeks, and as it does so its appearance changes from a circle to part of a circle.","ex":{"en":"...the first man on the moon","cn":"登上月球的第一人"}},{"pos":"N-COUNT 可数名词","cn":"卫星","en":"A moon is an object similar to a small planet that travels around a planet.","ex":{"en":"...Neptune's large moon.","cn":"海王星的大卫星"}},{"pos":"VERB 动词","cn":"虚度光阴;懒散度日;闲逛","en":"If you are mooning around, you are spending time doing nothing in particular, for example because you feel unhappy or lazy, or are worried about something.","ex":{"en":"Lettie was mooning around all morning, doing nothing","cn":"莱蒂混了一上午，什么也没干。"}},{"pos":"VERB 动词","cn":"对…露出光屁股","en":"If you moon at someone, you turn your back to them and show them your bare bottom."},{"pos":"PHRASE 短语","cn":"千载难逢;百年不遇","en":"If you say that something happens once in a blue moon, you are emphasizing that it does not happen very often at all.","ex":{"en":"Once in a blue moon you get some problems.","cn":"极少会碰到麻烦。"}},{"pos":"PHRASE 短语","cn":"非常高兴;乐翻了天;狂喜","en":"If you say that you are over the moon, you mean that you are very pleased about something."}]},"examples":[{"en":"By the light of the moon I could just make out shapes and outlines.","cn":"月光下，我只能分辨出形状和轮廓。"},{"en":"How many moons does Jupiter have?","cn":"木星有多少颗卫星？"}]},"moment":{"media":{"uk":"media/uk/moment__gb_1.mp3","us":"media/us/moment__us_1.mp3"},"oxford":{"phon":"ˈməʊmənt","pos":"noun","senses":[{"en":"a very short period of time","cn":"片刻；瞬间","ex":{"en":"Could you wait a moment, please?","cn":"请您稍等一下，好吗？"}},{"en":"an exact point in time","cn":"某个时刻；当时","g":"[singular]","ex":{"en":"We're busy at the moment (= now).","cn":"我们这会儿很忙。"}},{"en":"a good time for doing something; an opportunity","cn":"时机；机会","g":"[countable]","ex":{"en":"I'm waiting for the right moment to tell him the bad news.","cn":"我得找个适当的时机告诉他这个坏消息。"}},{"en":"a particular time in somebody's life, or in the course of an event or the development of something","cn":"（人生、事件或事物发展过程中的）一段时光，一段时间","g":"[countable]","ex":{"en":"That was one of the happiest moments of my life.","cn":"那是我一生中最快乐的一段时光。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"片刻;瞬间","en":"You can refer to a very short period of time, for example a few seconds, as a moment or moments .","ex":{"en":"In a moment he was gone","cn":"一转眼他就不见了。"}},{"pos":"N-COUNT 可数名词","cn":"时刻;时候","en":"A particular moment is the point in time at which something happens.","ex":{"en":"At this moment a car stopped at the house","cn":"就在这时，一辆轿车在房前停下了。"}},{"pos":"PHRASE 短语","cn":"随时;马上;即刻","en":"If you say that something will or may happen at any moment or any moment now, you are emphasizing that it is likely to happen very soon.","ex":{"en":"They ran the risk of being shot at any moment","cn":"他们冒着随时会中弹的危险。"}},{"pos":"PHRASE 短语","cn":"此刻;目前;眼下","en":"You use expressions such as at the moment ,at this moment, and at the present moment to indicate that a particular situation exists at the time when you are speaking.","ex":{"en":"At the moment, no one is talking to me","cn":"此刻没人跟我说话。"}},{"pos":"PHRASE 短语","cn":"哪怕一闪念","en":"If you say that you do not believe for a moment or for one moment that something is true, you are emphasizing that you do not believe that it could possibly be true.","ex":{"en":"I don't for a moment think there'll be a divorce.","cn":"我从来没想过将来会离婚。"}},{"pos":"PHRASE 短语","cn":"暂时;目前","en":"You use for the moment to indicate that something is true now, even if it will not be true in the future.","ex":{"en":"For the moment, however, the government is happy to live with it.","cn":"不过目前政府对此还乐于容忍。"}},{"pos":"PHRASE 短语","cn":"有成功(或得意)的时刻；有吸引人的时刻","en":"If you say that someone or something has their moments, you are indicating that there are times when they are successful or interesting, but that this does not happen very often.","ex":{"en":"The film has its moments","cn":"这部电影有其吸引人之处。"}},{"pos":"PHRASE 短语","cn":"最后一刻;最后时刻","en":"If someone does something at the last moment, they do it at the latest time possible.","ex":{"en":"They changed their minds at the last moment and refused to go.","cn":"他们在最后一刻改变主意，决定不去了。"}},{"pos":"PHRASE 短语","cn":"下一刻，一会儿，紧接着（尤指突然发生很大变化）","en":"You use the expression the next moment, or expressions such as 'one moment he was there, the next he was gone', to emphasize that something happens suddenly, especially when it is very different from what was happening before.","ex":{"en":"The next moment there was an almighty crash","cn":"接着发生了剧烈的撞击。"}},{"pos":"PHRASE 短语","cn":"红极一时;盛行一时","en":"You use of the moment to describe someone or something that is or was especially popular at a particular time, especially when you want to suggest that their popularity is unlikely to last long or did not last long.","ex":{"en":"He's the man of the moment, isn't he?","cn":"他现在很红，不是吗？"}},{"pos":"PHRASE 短语","cn":"一…就","en":"If you say that something happens the moment something else happens, you are emphasizing that it happens immediately after the other thing.","ex":{"en":"The moment I closed my eyes, I fell asleep.","cn":"我闭上眼睛就睡着了。"}},{"pos":"","cn":"","en":"spur of the moment→see: ;"}]},"examples":[{"en":"This house is big enough for the moment, but we'll have to move if we have children.","cn":"这房子现在还够大。要是有了孩子，我们还得搬。"},{"en":"The job isn't exciting all the time, but it has its moments.","cn":"这工作并不总是很带劲，但也有让人兴奋的时候。"}]},"mountaineering":{"media":{"uk":"media/uk/mountaineering__gb_1.mp3","us":"media/us/mountaineering__us_1.mp3"},"oxford":{"phon":"ˌmaʊntəˈnɪərɪŋ","pos":"noun","senses":[{"en":"the sport or activity of climbing mountains","cn":"登山运动","ex":{"en":"to go mountaineering","cn":"去爬山"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"登山;登山运动","en":"Mountaineering is the activity of climbing the steep sides of mountains as a hobby or sport."}]},"examples":[{"en":"a mountaineering expedition","cn":"登山探险"},{"en":"to go mountaineering","cn":"去爬山"}]},"mostly":{"media":{"uk":"media/uk/mostly__gb_1.mp3","us":"media/us/mostly__us_1.mp3"},"oxford":{"phon":"ˈməʊstli","pos":"adverb","senses":[{"en":"mainly; generally","cn":"主要地；一般地；通常","ex":{"en":"The sauce is mostly cream.","cn":"这沙司主要是奶油。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"大多;多半;主要地","en":"You use mostly to indicate that a statement is generally true, for example true about the majority of a group of things or people, true most of the time, or true in most respects.","ex":{"en":"I am working with mostly highly motivated people","cn":"和我共事的人大多积极性极高。"}}]},"examples":[{"en":"We're mostly out on Sundays.","cn":"我们星期天一般不在家。"},{"en":"The sauce is mostly cream.","cn":"这沙司主要是奶油。"}]},"mounted":{"media":{"uk":"media/uk/mounted__gb_1.mp3","us":"media/us/mounted__us_1.mp3"},"oxford":{"phon":"ˈmaʊntɪd","pos":"adjective","senses":[{"en":"riding a horse","cn":"骑马的","ex":{"en":"mounted policemen","cn":"骑警"}},{"en":"placed on something or attached to something for display or support","cn":"装裱好的；安装好的","ex":{"en":"a mounted photograph","cn":"裱好的照片"}},{"en":"attached to the thing mentioned for support","cn":"安装在…上的","ex":{"en":"a ceiling-mounted fan","cn":"吊扇"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(警察、战士等)骑马执勤的","en":"Mounted police or soldiers ride horses when they are on duty.","ex":{"en":"A dozen mounted police rode into the square.","cn":"十几名骑警进入了广场。"}}]},"examples":[{"en":"a mounted photograph","cn":"裱好的照片"},{"en":"mounted policemen","cn":"骑警"}]},"monitor":{"media":{"uk":"media/uk/monitor__gb_1.mp3","us":"media/us/monitor__us_1.mp3"},"oxford":{"phon":"ˈmɒnɪtə(r)","pos":"noun","senses":[{"en":"a screen that shows information from a computer; a television screen used to show particular kinds of information","cn":"显示屏；屏幕；显示器","ex":{"en":"The details of today's flights are displayed on the monitor.","cn":"今天航班的详细情况都显示在屏幕上。"}},{"en":"a piece of equipment used to check or record something","cn":"监视器；监控器；监测器","ex":{"en":"He was lying there hooked up to a heart monitor.","cn":"他躺在那儿，连着一台心脏监测器。"}},{"en":"a person whose job is to check that something is done fairly and honestly, especially in a foreign country","cn":"（尤指派往国外的）监督员，核查员","ex":{"en":"UN monitors declared the referendum fair.","cn":"联合国核查员宣布这次全民投票是公正的。"}},{"en":"a student in a school who performs special duties, such as helping the teacher","cn":"班长；级长；班代表","ex":{"en":"He was a star pupil and the class monitor.","cn":"他是最优秀的小学生，也是班长。"}},{"en":"a large tropical lizard (= a type of reptile)","cn":"巨蜥","ex":{"en":"A large monitor lizard, prehistoric in its beauty, stared at us.","cn":"一只巨大的巨蜥，有着史前的美丽，盯着我们。"}},{"en":"to watch and check something over a period of time in order to see how it develops, so that you can make any necessary changes","cn":"监视；监测；跟踪调查","ex":{"en":"Each student's progress is closely monitored.","cn":"每一个学生的学习进展都受到密切的关注。"},"pos":"verb"},{"en":"to use technology to watch somebody/something, especially for reasons of security","cn":"监控；监视","ex":{"en":"A police helicopter will be used to monitor crime hotspots.","cn":"一架警用直升机将被用来监控犯罪热点地区。"},"pos":"verb"},{"en":"to listen to phone calls, foreign radio broadcasts, etc. in order to find out information that might be useful","cn":"监听（电话、外国无线电广播等）","ex":{"en":"a police state where every activity is monitored","cn":"所有活动都被监听的警察国家"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"监控;监视;监督","en":"If you monitor something, you regularly check its development or progress, and sometimes comment on it.","ex":{"en":"Officials had not been allowed to monitor the voting","cn":"以前不允许官员监督投票。"}},{"pos":"VERB 动词","cn":"监听(外国无线电广播等)","en":"If someone monitors radio broadcasts from other countries, they record them or listen carefully to them in order to obtain information.","ex":{"en":"Peter Murray is in London and has been monitoring reports out of Monrovia.","cn":"彼得·默里一直在伦敦监听来自蒙罗维亚的新闻报道。"}},{"pos":"N-COUNT 可数名词","cn":"监测仪器;监控器","en":"A monitor is a machine that is used to check or record things, for example processes or substances inside a person's body.","ex":{"en":"The heart monitor shows low levels of consciousness.","cn":"心脏监测器显示患者神志不清。"}},{"pos":"N-COUNT 可数名词","cn":"显示屏;监视器","en":"A monitor is a screen which is used to display certain kinds of information, for example in airports or television studios.","ex":{"en":"He was watching a game of tennis on a television monitor.","cn":"他在看电视转播的网球赛。"}},{"pos":"N-COUNT 可数名词","cn":"监督员;监控人;核查员","en":"You can refer to a person who checks that something is done correctly, or that it is fair, as a monitor .","ex":{"en":"Government monitors will continue to accompany reporters.","cn":"政府监督员将继续陪同记者。"}}]},"examples":[{"en":"UN monitors declared the referendum fair.","cn":"联合国核查员宣布这次全民投票是公正的。"},{"en":"Each student's progress is closely monitored.","cn":"每一位同学的学习情况都受到密切的关注。"}]},"morally":{"oxford":{"phon":"ˈmɒrəli","pos":"adverb","senses":[{"en":"according to principles of good behaviour and what is considered to be right or wrong","cn":"道义上；道德上","ex":{"en":"to act morally","cn":"循规蹈矩"}}]},"media":{"uk":"media/uk/morally__gb_1.mp3","us":"media/us/morally__us_1.mp3"},"examples":[{"en":"He felt morally responsible for the accident.","cn":"他觉得在道义上应对这次事故负责。"},{"en":"morally right/wrong/justified/unacceptable","cn":"从道义上讲是正确的/错误的/正当的/不可接受的"}]},"model":{"media":{"uk":"media/uk/model__gb_1.mp3","us":"media/us/model__us_1.mp3","img":["media/ldoce/img/model_boat.jpg","media/thumb/model.jpg"]},"oxford":{"phon":"ˈmɒdl","pos":"noun","senses":[{"en":"a copy of something, usually smaller than the original object","cn":"（依照实物按比例制成的）模型","sc":"small copy","ex":{"en":"a working model (= one in which the parts move) of a fire engine","cn":"消防车的活动模型"}},{"en":"something such as a text or a system that can be used as an example for other people to copy","cn":"范文；范例；模板","sc":"example to copy","ex":{"en":"Look at the writing model on page 58.","cn":"请看第 58 页的范文。"}},{"en":"a person or thing that is considered an excellent example of something","cn":"模范；典型","lab":"approving","sc":"example to copy","ex":{"en":"It was a model of clarity.","cn":"这是表达清晰的范例。"}},{"en":"a person whose job is to wear and show new styles of clothes and be photographed wearing them","cn":"模特儿","sc":"fashion","ex":{"en":"She had a successful career as a fashion model.","cn":"她作为一名时装模特有着成功的职业生涯。"}},{"en":"a person who is employed to be painted, drawn, photographed, etc. by an artist or photographer","cn":"模特儿","sc":"for artist","ex":{"en":"The model sits for me for three hours every day.","cn":"模特儿每天要坐 3 个小时让我创作。"}},{"en":"a particular design or type of product","cn":"样式；设计；型","sc":"design","ex":{"en":"The latest models will be on display at the motor show.","cn":"最新的车型将会在这次汽车展上展出。"}},{"en":"a way of running a business, based on a particular way of getting the money you need and identifying and reaching your customers; a type of business model","cn":"商业模式","sc":"in business","ex":{"en":"They may abandon the traditional cooperative model.","cn":"他们可能会放弃传统的合作模式。"}},{"en":"a simple description of a system, used for explaining how something works or calculating what might happen, etc.","cn":"（用于描述系统运作或预测结果等的）模型","sc":"description of system","ex":{"en":"the standard economic model of supply and demand","cn":"标准的供需经济模型"}},{"en":"to create a copy or description of an activity, a situation, etc. so that you can study it before dealing with the real thing","cn":"模拟；复制","g":"[transitive]","sc":"create copy","ex":{"en":"The program can model a typical home page for you.","cn":"这个程序可以使用模板帮你制作一个标准的主页。"},"pos":"verb"},{"en":"to represent something, especially in a diagram","cn":"（尤指用图表）表示，展现","sc":"create copy","ex":{"en":"This finite set of data can be modelled by a growth curve.","cn":"这个有限的数据集可以用增长曲线来展示。"},"pos":"verb"},{"en":"to shape clay, etc. in order to make something","cn":"将（黏土等）做成模型","g":"[transitive]","sc":"clay, etc.","ex":{"en":"a statue modelled in bronze","cn":"青铜像"},"pos":"verb"},{"en":"to wear clothes in order to show them to people who might want to buy them","cn":"（向顾客）穿戴展示","g":"[transitive]","sc":"clothes","ex":{"en":"The wedding gown is being modelled for us by the designer's daughter.","cn":"结婚礼服正由设计者的女儿穿在身上给我们看。"},"pos":"verb"},{"en":"to work as a model for an artist or in the fashion industry","cn":"做模特儿","g":"[intransitive]","sc":"work as model","ex":{"en":"Ralph's been modelling since he was 16.","cn":"拉尔夫从 16 岁起就当模特儿。"},"pos":"verb"},{"en":"to set an example of behaviour that you want other people to copy","cn":"做示范；树立榜样","g":"[transitive]","sc":"set an example","ex":{"en":"Managers must model behaviour that is open and vulnerable.","cn":"管理者必须树立开放坦诚的行为榜样。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模型","en":"A model of an object is a physical representation that shows what it looks like or how it works. The model is often smaller than the object it represents.","ex":{"en":"...an architect's model of a wooden house.","cn":"一幢木屋的建筑模型"}},{"pos":"N-COUNT 可数名词","cn":"模范;榜样","en":"A model is a system that is being used and that people might want to copy in order to achieve similar results.","ex":{"en":"We believe that this is a general model of managerial activity","cn":"我们认为这可以作为管理活动的普遍范例。"}},{"pos":"N-COUNT 可数名词","cn":"(理论描述的)模型","en":"A model of a system or process is a theoretical description that can help you understand how the system or process works, or how it might work.","ex":{"en":"Darwin eventually put forward a model of biological evolution","cn":"达尔文最终提出了生物进化的模型。"}},{"pos":"VERB 动词","cn":"创立(系统或过程）的（理论描述)模型","en":"If someone such as a scientist models a system or process, they make an accurate theoretical description of it in order to understand or explain how it works.","ex":{"en":"...the mathematics needed to model a nonlinear system like an atmosphere.","cn":"创立诸如大气层之类的非线性系统的模型所需的数学知识"}},{"pos":"N-COUNT 可数名词","cn":"（某种特质的）典型，典范","en":"If you say that someone or something is a model of a particular quality, you are showing approval of them because they have that quality to a large degree.","ex":{"en":"A model of good manners, he has conquered any inward fury","cn":"作为一个非常懂礼貌的人，他已经学会了克制内心的任何愤怒情绪。"}},{"pos":"ADJ 形容词","cn":"模范的;榜样的","en":"You use model to express approval of someone when you think that they perform their role or duties extremely well.","ex":{"en":"As a girl she had been a model pupil","cn":"还是个小女孩的时候，她就是一个模范学生。"}},{"pos":"VERB 动词","cn":"按特定模型制造;仿特定样式做出","en":"If one thing is modelled on another, the first thing is made so that it is like the second thing in some way.","ex":{"en":"The quota system was modelled on those operated in America and continental Europe","cn":"该配额制度是仿照美国以及欧洲大陆国家的同类制度制定的。"}},{"pos":"VERB 动词","cn":"使仿效;使模仿","en":"If you model yourself on someone, you copy the way that they do things, because you admire them and want to be like them.","ex":{"en":"There's absolutely nothing wrong in modelling yourself on an older woman","cn":"以年纪较长的女性作为自己仿效的对象绝没有什么不对。"}},{"pos":"N-COUNT 可数名词","cn":"(机器等的)型号","en":"A particular model of a machine is a particular version of it. →see usage note at:","ex":{"en":"To keep the cost down, opt for a basic model","cn":"要想花钱少些，就选择基本的型号。"}},{"pos":"N-COUNT 可数名词","cn":"(绘画或雕塑的)模特儿","en":"An artist's model is a person who stays still in a particular position so that the artist can make a picture or sculpture of them."},{"pos":"VERB 动词","cn":"（为艺术家）当模特儿","en":"If someone models for an artist, they stay still in a particular position so that the artist can make a picture or sculpture of them.","ex":{"en":"Tullio has been modelling for Sandra for eleven years.","cn":"图利奥已为桑德拉做了11年的模特儿。"}},{"pos":"N-COUNT 可数名词","cn":"（时装）模特儿","en":"A fashion model is a person whose job is to display clothes by wearing them.","ex":{"en":"...Paris's top photographic fashion model.","cn":"巴黎顶尖时装摄影模特儿"}},{"pos":"VERB 动词","cn":"当模特儿展示（服装）","en":"If someone models clothes, they display them by wearing them.","ex":{"en":"I wasn't here to model clothes","cn":"我不是到这里来当时装模特儿的。"}},{"pos":"VERB 动词","cn":"(用黏土、木头等)做…的模型;塑造","en":"If you model shapes or figures, you make them out of a substance such as clay or wood.","ex":{"en":"There she began to model in clay","cn":"在那儿她开始用黏土做模型。"}}]},"examples":[{"en":"The architect had produced a scale model of the proposed shopping complex.","cn":"建筑师为计划建设的购物中心做了一个比例模型。"},{"en":"The program can model a typical home page for you.","cn":"这个程序可以使用模板帮你制作一个标准的主页。"}]},"monolingual":{"media":{"uk":"media/uk/monolingual__gb_1.mp3","us":"media/us/monolingual__us_1.mp3"},"oxford":{"phon":"ˌmɒnəˈlɪŋɡwəl","pos":"adjective","senses":[{"en":"speaking or using only one language","cn":"单语的；只用一种语言的","ex":{"en":"a monolingual dictionary","cn":"单语词典"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"单语的;只使用一种语言的","en":"Monolingual means involving, using, or speaking one language.","ex":{"en":"...a largely monolingual country such as Great Britain.","cn":"像英国这样主要使用一种语言的国家"}}]},"examples":[{"en":"a monolingual dictionary","cn":"单语词典"}]},"mountain":{"media":{"img":["media/pic/mountain_comp.jpg","media/thumb/mountain.jpg"],"uk":"media/uk/mountain__gb_1.mp3","us":"media/us/mountain__us_1.mp3"},"oxford":{"phon":"ˈmaʊntən","pos":"noun","senses":[{"en":"a very high hill, often with rocks near the top","cn":"高山；山岳","ex":{"en":"the mountains of Andalusia","cn":"安达卢西亚的群山"}},{"en":"a very large amount or number of something; the very large size of something/somebody","cn":"大量；庞大","lab":"informal","ex":{"en":"a mountain of work","cn":"大量的工作"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山;山岳;高山","en":"A mountain is a very high area of land with steep sides.","ex":{"en":"Ben Nevis, in Scotland, is Britain's highest mountain.","cn":"苏格兰境内的本尼维斯山是英国最高的山。"}},{"pos":"QUANT 数量词","cn":"大量;大堆","en":"If you talk about a mountain of something, or mountains of something, you are emphasizing that there is a large amount of it.","ex":{"en":"They are faced with a mountain of bureaucracy","cn":"他们面对一大堆繁文缛节。"}},{"pos":"PHRASE 短语","cn":"极大的困难;难办的事情；棘手的难题","en":"If you say that someone has a mountain to climb, you mean that it will be difficult for them to achieve what they want to achieve.","ex":{"en":"'We had a mountain to climb after the second goal went in,' said Crosby.","cn":"克罗斯比说：“进第二个球之后，我们面临着严峻的挑战。”"}},{"pos":"","cn":"","en":"to make a mountain out of a molehill→see: ;"}]},"examples":[{"en":"We spent a week walking in the mountains.","cn":"我们在群山中走了一个星期。"},{"en":"We made mountains of sandwiches.","cn":"我们做了一大堆三明治。"}]},"mop":{"media":{"img":["media/pic/cleaning_comp.jpg","media/thumb/mop.jpg"],"uk":"media/uk/mop__gb_1.mp3","us":"media/us/mop__us_1.mp3"},"oxford":{"phon":"mɒp","pos":"noun","senses":[{"en":"a tool for washing floors that has a long handle with soft material or a bunch of thick strings at the end","cn":"拖把；墩布","ex":{"en":"a mop and bucket","cn":"带水桶的拖把"}},{"en":"a kitchen utensil (= a tool) for washing dishes, that has a short handle with soft material at one end","cn":"洗碗刷"},{"en":"a mass of thick, often untidy, hair","cn":"乱蓬蓬的头发","ex":{"en":"a mop of curly red hair","cn":"乱蓬蓬的红色鬈发"}},{"en":"to clean something with a mop","cn":"用拖把擦干净","ex":{"en":"She wiped all the surfaces and mopped the floor.","cn":"她把所有的陈设都擦干净，还拖了地板。"},"pos":"verb"},{"en":"to remove liquid from the surface of something using a cloth","cn":"用布擦掉（表面）的液体","ex":{"en":"He took out a handkerchief to mop his brow (= to remove the sweat).","cn":"他拿出手绢来擦额头上的汗水。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拖把","en":"A mop is a piece of equipment for washing floors. It consists of a sponge or many pieces of string attached to a long handle."},{"pos":"VERB 动词","cn":"用拖把擦(地板)","en":"If you mop a surface such as a floor, you clean it with a mop.","ex":{"en":"There was a woman mopping the stairs.","cn":"一个女人在拖楼梯。"}},{"pos":"VERB 动词","cn":"(用布)擦去，揩干(汗水)","en":"If you mop sweat from your forehead or mop your forehead, you wipe it with a piece of cloth.","ex":{"en":"He mopped perspiration from his forehead","cn":"他擦去了前额的汗水。"}},{"pos":"N-COUNT 可数名词","cn":"乱蓬蓬的头发;蓬乱不洁的头发","en":"If someone has a mop of hair, they have a lot of hair and it looks rather untidy.","ex":{"en":"He was long-limbed and dark-eyed, with a mop of tight, dark curls.","cn":"他四肢修长、眼睛乌黑发亮，留着一头蓬乱浓密的黑色卷发。"}},{"pos":"","cn":"","en":"相关词组：mop up"}]},"examples":[{"en":"Troops combed the area to mop up any remaining resistance.","cn":"部队对这一地区进行了清剿，以扫除一切残余的抵抗势力。"},{"en":"( figurative ) A number of smaller companies were mopped up (= taken over) by the American multinational.","cn":"有若干较小的公司都被那家美国跨国集团兼并了。"}]},"mouse":{"oxford":{"phon":"maʊs","pos":"noun","senses":[{"en":"a small animal that is covered in fur and has a long thin tail. Mice live in fields, in people’s houses or where food is stored.","cn":"老鼠；耗子","lab":"figurative","ex":{"en":"a house mouse","cn":"家鼠"}},{"en":"a small device that is moved by hand across a surface to control the movement of the cursor on a computer screen","cn":"鼠标","lab":"computing","ex":{"en":"Use the mouse to drag the icon to a new position.","cn":"用鼠标将图标拖到一个新的位置。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"老鼠;耗子","en":"A mouse is a small furry animal with a long tail.","ex":{"en":"...a mouse running in a wheel in its cage.","cn":"在笼中转轮上奔跑的老鼠"}},{"pos":"N-COUNT 可数名词","cn":"鼠标","en":"A mouse is a device that is connected to a computer. By moving it over a flat surface and pressing its buttons, you can move the cursor around the screen and do things without using the keyboard."},{"pos":"","cn":"","en":"game of cat and mouse→see: ;"}]},"media":{"uk":"media/uk/mouse__gb_1.mp3","us":"media/us/mouse__us_1.mp3","img":["media/ldoce/img/mice.jpg"]},"examples":[{"en":"Click the left mouse button twice to highlight the program.","cn":"双击鼠标左键来加亮突出这个程序。"},{"en":"The stores were overrun with rats and mice.","cn":"仓库里到处都是大大小小的老鼠。"}]},"motor":{"media":{"uk":"media/uk/motor__gb_1.mp3","us":"media/us/motor__us_1.mp3"},"oxford":{"phon":"ˈməʊtə(r)","pos":"noun","senses":[{"en":"a device that uses electricity, petrol, etc. to produce movement and makes a machine, a vehicle, a boat, etc. work","cn":"发动机；马达","ex":{"en":"An electric motor is used to pump the water.","cn":"电动机用于抽水。"}},{"en":"a source of power, energy or movement","cn":"原动力；驱动力","ex":{"en":"Consumer spending has been the motor of economic growth.","cn":"消费者支出一直是经济增长的动力。"}},{"en":"a car","cn":"汽车","lab":"British English, old-fashioned or humorous，，","ex":{"en":"He uses the motor for local shopping trips.","cn":"他开车在当地购物。"}},{"en":"having an engine; using the power of an engine","cn":"有发动机的；由发动机推动的","ex":{"en":"The street is closed to motor vehicles.","cn":"该街道禁止机动车通行。"},"pos":"adjective"},{"en":"connected with vehicles that have engines","cn":"机动车的；汽车的","lab":"especially British English","ex":{"en":"Europe's motor industry faces international competition.","cn":"欧洲汽车工业面临国际竞争。"},"pos":"adjective"},{"en":"connected with movement of the body that is produced by muscles; connected with the nerves that control movement","cn":"肌肉运动的；运动神经的","lab":"specialist","ex":{"en":"uncoordinated motor activity","cn":"不协调的肌肉运动"},"pos":"adjective"},{"en":"to travel by car, especially for pleasure","cn":"乘车旅行；驾车旅行","ex":{"en":"We motored down to Oxford for the day.","cn":"那天我们开车去牛津。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发动机;引擎","en":"The motor in a machine, vehicle, or boat is the part that uses electricity or fuel to produce movement, so that the machine, vehicle, or boat can work.","ex":{"en":"She got in and started the motor.","cn":"她坐上车，发动了引擎。"}},{"pos":"ADJ 形容词","cn":"机动的;由发动机驱动的","en":"Motor vehicles and boats have a petrol or diesel engine.","ex":{"en":"Theft of motor vehicles is up by 15.9%.","cn":"机动车辆偷盗案上升了15.9%。"}},{"pos":"ADJ 形容词","cn":"汽车的;车辆的","en":"Motor is used to describe activities relating to vehicles such as cars and buses.","ex":{"en":"...the future of the British motor industry","cn":"英国汽车工业的未来"}},{"pos":"N-COUNT 可数名词","cn":"汽车;轿车","en":"Some people refer to a car as a motor ."},{"pos":"VERB 动词","cn":"自驾游览;乘汽车旅行","en":"If you motor somewhere, you travel there in a car, usually for pleasure.","ex":{"en":"I had motored down from Cheshire.","cn":"我从柴郡一路南下开过来。"}},{"pos":"VERB 动词","cn":"使用发动机驾驶帆船","en":"If people in a small sailing boat motor somewhere, they use the boat's motor rather than the power of the wind to get there.","ex":{"en":"Restarting the engine, we motored downriver.","cn":"我们重新启动马达，沿河而下。"}}]},"examples":[{"en":"Both motor and sensory functions are affected.","cn":"运动功能和感觉功能都受到影响。"},{"en":"They're planning a motoring holiday to France this year.","cn":"他们计划今年驾车到法国去度假。"}]},"morsel":{"media":{"uk":"media/uk/morsel__gb_1.mp3","us":"media/us/morsel__us_1.mp3"},"oxford":{"phon":"ˈmɔːsl","pos":"noun","senses":[{"en":"a small amount or a piece of something, especially food","cn":"少量，一块（食物）","ex":{"en":"a tasty morsel of food","cn":"一点儿可口的食物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一点点，一小份(尤指食物)","en":"A morsel is a very small amount of something, especially a very small piece of food.","ex":{"en":"...a delicious little morsel of meat.","cn":"一小块美味可口的肉"}}]},"examples":[{"en":"He ate it all, down to the last morsel.","cn":"他全吃光了，一点不剩。"},{"en":"a tasty morsel of food","cn":"一点可口的食物"}]},"motorcade":{"media":{"uk":"media/uk/motorcade__gb_1.mp3","us":"media/us/motorcade__us_1.mp3"},"oxford":{"phon":"ˈməʊtəkeɪd","pos":"noun","senses":[{"en":"a line of vehicles including one or more that famous or important people are travelling in","cn":"（载着要人的）车队","ex":{"en":"The President's motorcade glided by.","cn":"总统的车队一溜烟开了过去。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（载有重要人物的）车队，汽车行列","en":"A motorcade is a line of slow-moving cars carrying important people, usually as part of a public ceremony.","ex":{"en":"At times the president's motorcade slowed to a crawl.","cn":"有时总统车队放慢速度缓缓而行。"}}]},"examples":[{"en":"The President's motorcade glided by.","cn":"总统的车队一溜风开了过去。"},{"en":"the president’s motorcade","cn":"总统车队"}]},"motorway":{"oxford":{"phon":"ˈməʊtəweɪ","pos":"noun","senses":[{"en":"(in the UK) a wide road, with at least two lanes in each direction, where traffic can travel fast for long distances between large towns. You can only enter and leave motorways at special junctions.","cn":"（英国）高速公路","ex":{"en":"busy/congested motorways","cn":"繁忙的／拥挤的高速公路"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"高速公路","en":"A motorway is a major road that has been specially built for fast travel over long distances. Motorways have several lanes and special places where traffic gets on and leaves.","ex":{"en":"...the M1 motorway.","cn":"M1 高速公路"}}]},"media":{"uk":"media/uk/motorway__gb_1.mp3","us":"media/us/motorway__us_1.mp3"},"examples":[{"en":"Join the motorway at Junction 19.","cn":"在 19 号路口进入高速公路。"},{"en":"A nine-mile stretch of motorway has been closed.","cn":"一段九英里长的高速公路已关闭。"}]},"motion":{"media":{"uk":"media/uk/motion__gb_1.mp3","us":"media/us/motion__us_1.mp3"},"oxford":{"phon":"ˈməʊʃn","pos":"noun","senses":[{"en":"the act or process of moving or the way something moves","cn":"运动；移动；动","g":"[uncountable, singular]","lab":"formal","ex":{"en":"What was Newton's first law of motion?","cn":"牛顿第一运动定律是什么？"}},{"en":"a particular movement made usually with your hand or your head, especially to communicate something","cn":"（为传递信息用手或头做的）动作","g":"[countable]","ex":{"en":"At a single motion of his hand, the room fell silent.","cn":"他手一挥，屋子里便安静了下来。"}},{"en":"a formal proposal that is discussed and voted on at a meeting","cn":"动议；提议","g":"[countable]","ex":{"en":"to table/put forward a motion","cn":"提出一项动议"}},{"en":"an act of emptying the bowels; the waste matter that is emptied from the bowels","cn":"通便；大便","g":"[countable]","lab":"British English, formal，，"},{"en":"to make a movement, usually with your hand or head, to show somebody what you want them to do","cn":"（以头或手）做动作，示意","ex":{"en":"I motioned to the waiter.","cn":"我向侍者打了个手势。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"运动;移动","en":"Motion is the activity or process of continually changing position or moving from one place to another.","ex":{"en":"...the laws governing light, sound, and motion","cn":"有关声、光和运动的定律"}},{"pos":"N-COUNT 可数名词","cn":"行动;手势;动作","en":"A motion is an action, gesture, or movement.","ex":{"en":"Cover each part of the body with long sweeping strokes or circular motions","cn":"对全身每个部位画长弧线轻抚或做圆圈状按摩。"}},{"pos":"N-COUNT 可数名词","cn":"(会议、辩论或审判时提出的)动议，提议，议案","en":"A motion is a formal proposal or statement in a meeting, debate, or trial, which is discussed and then voted on or decided on.","ex":{"en":"The conference is now debating the motion and will vote on it shortly","cn":"大会正在就提议进行辩论，稍后将就此表决。"}},{"pos":"VERB 动词","cn":"打手势;示意","en":"If you motion to someone, you move your hand or head as a way of telling them to do something or telling them where to go.","ex":{"en":"She motioned for the locked front doors to be opened","cn":"她示意把锁着的前门打开。"}},{"pos":"N-COUNT 可数名词","cn":"(尤为医生、护士用语)排便，大便","en":"Some people, especially doctors or nurses, use motion as a polite way of referring to a person's act of defecation or the faeces produced.","ex":{"en":"Try to make sure your bowel motions are regular and that you avoid any constipation.","cn":"尽量保证大便规律，避免便秘。"}},{"pos":"PHRASE 短语","cn":"走过场;应付差事","en":"If you say that someone is going through the motions, you think they are only saying or doing something because it is expected of them without being interested, enthusiastic, or sympathetic.","ex":{"en":"'You really don't care, do you?' she said quietly. 'You're just going through the motions.'","cn":"“你其实不在意，对不对？”她悄声说，“你就是装装样子而已。”"}},{"pos":"PHRASE 短语","cn":"假装做;装装样子","en":"If you go through the motions, you pretend to do something by making the movements associated with a particular action.","ex":{"en":"The sailor went through all the motions smartly","cn":"这个水手机灵地走了走过场。"}},{"pos":"PHRASE 短语","cn":"正在发生;在进行中;即将发生","en":"If a process or event is in motion, it is happening. If it is set in motion, it is happening or beginning to happen.","ex":{"en":"His job as England manager begins in earnest now his World Cup campaign is in motion","cn":"现在世界杯足球赛的征战工作已经展开，而他作为英格兰队主教练的工作也真正开始了。"}},{"pos":"PHRASE 短语","cn":"开动;激活;启动","en":"If someone sets the wheels in motion, they take the necessary action to make something start happening.","ex":{"en":"I have set the wheels in motion to sell Endsleigh Court.","cn":"我已着手出售恩德斯勒公馆。"}}]},"examples":[{"en":"At a single motion of his hand, the room fell silent.","cn":"他手一挥，屋子里便安静了下来。"},{"en":"The swaying motion of the ship was making me feel seasick.","cn":"船身摇摆不定，让我觉得恶心。"}]},"mom":{"oxford":{"phon":"mɒm","pos":"noun","senses":[{"en":"a mother","cn":"妈妈；妈","ex":{"en":"Where's my mom?","cn":"我妈在哪儿？"}}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"母亲;妈妈","en":"Your mom is your mother.","ex":{"en":"We waited for Mom and Dad to get home","cn":"我们等爸爸妈妈回家。"}}]},"media":{"uk":"media/uk/mom__gb_1.mp3","us":"media/us/mom__us_1.mp3"},"examples":[{"en":"Are you listening, Mom?","cn":"妈，你在听吗？"},{"en":"Where's my mom?","cn":"我妈在哪儿？"}]},"motivation":{"media":{"uk":"media/uk/motivation__gb_1.mp3","us":"media/us/motivation__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"动力;诱因","en":"Your motivation for doing something is what causes you to want to do it.","ex":{"en":"Money is my motivation","cn":"金钱是我的动力。"}}]},"examples":[{"en":"Most people said that pay was their main motivation for working.","cn":"大多数人说赚取报酬是他们工作的主要动机。"},{"en":"( SAfrE ) All research proposals must be accompanied by a full motivation.","cn":"所有研究计划书均须详述研究动机。"}],"oxford":{"phon":"ˌməʊtɪˈveɪʃn","pos":"noun","senses":[{"en":"the reason why somebody does something or behaves in a particular way","cn":"动机；原因","g":"[countable, uncountable]","ex":{"en":"What is the motivation behind this sudden change?","cn":"这一突然转变背后的动机是什么？"}},{"en":"the feeling of wanting to do something, especially something that involves hard work and effort","cn":"积极性；干劲","g":"[uncountable]","ex":{"en":"He's intelligent enough but he lacks motivation.","cn":"他很聪明，但缺乏积极性。"}},{"en":"a statement or piece of writing in which you give reasons for something","cn":"陈述理由的报告","g":"[countable]","lab":"South African English","ex":{"en":"All research proposals must be accompanied by a full motivation.","cn":"提交研究计划时必须附上一份详述研究动机的报告。"}}]}},"mock":{"oxford":{"phon":"mɒk","pos":"verb","senses":[{"en":"to laugh at somebody/something in an unkind way, especially by copying what they say or do","cn":"嘲笑；（模仿）嘲弄","g":"[transitive, intransitive]","ex":{"en":"He's always mocking my French accent.","cn":"他总是嘲笑我的法国口音。"}},{"en":"to show no respect for something","cn":"不尊重；蔑视","g":"[transitive]","lab":"formal","ex":{"en":"The new exam mocked the needs of the majority of children.","cn":"新的考试无视大多数孩子的需求。"}},{"en":"not sincere","cn":"虚假的；不诚实的","ex":{"en":"mock horror/surprise","cn":"假装恐惧；故作惊讶"},"pos":"adjective"},{"en":"that is a copy of something; not real","cn":"模仿的；模拟的","ex":{"en":"a mock election","cn":"模拟选举"},"pos":"adjective"},{"en":"(in the UK) a practice exam that you do before the official one","cn":"（英国）模拟考试","ex":{"en":"The mocks are in November.","cn":"模拟考试在 11 月进行。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"嘲笑；嘲弄；（模仿）取笑","en":"If someone mocks you, they show or pretend that they think you are foolish or inferior, for example by saying something funny about you, or by imitating your behaviour.","ex":{"en":"I thought you were mocking me","cn":"我还以为你是在嘲笑我。"}},{"pos":"ADJ 形容词","cn":"假的;仿制的;假装的","en":"You use mock to describe something which is not real or genuine, but which is intended to be very similar to the real thing.","ex":{"en":"'It's tragic!' swoons Jeffrey in mock horror","cn":"“真惨啊！”杰弗里假装吓昏了过去。"}},{"pos":"N-COUNT 可数名词","cn":"模拟考试","en":"Mocks are practice exams that you take as part of your preparation for real exams.","ex":{"en":"She went from a D in her mocks to a B in the real thing.","cn":"她模拟考试得了D，到了真正考试的时候却拿了个B。"}}]},"media":{"uk":"media/uk/mock__gb_1.mp3","us":"media/us/mock__us_1.mp3"},"examples":[{"en":"The other children mocked her, laughing behind their hands.","cn":"其他孩子学她的样子，用手捂着嘴笑。"},{"en":"You can mock, but at least I'm willing to have a try!","cn":"你可以嘲笑我，但我至少愿意试一试。"}]},"mould":{"oxford":{"phon":"məʊld","pos":"noun","senses":[{"en":"a container that you pour a liquid or soft substance into, which then becomes solid in the same shape as the container, for example when it is cooled or cooked","cn":"模具；铸模","g":"[countable]","ex":{"en":"A clay mould is used for casting bronze statues.","cn":"用黏土模具来浇铸青铜塑像。"}},{"en":"a particular style showing the characteristics, attitudes or behaviour that are typical of somebody/something","cn":"（独特）类型，个性，风格","g":"[countable, usually singular]","ex":{"en":"a hero in the ‘Superman’ mould","cn":"“超人”式的英雄"}},{"en":"a fine soft green, grey or black substance like fur that is a type of fungus and that grows on old food or on objects that are left in warm wet air","cn":"霉；霉菌","g":"[uncountable, countable]","ex":{"en":"There's mould on the cheese.","cn":"干酪发霉了。"}},{"en":"to shape a soft substance into a particular form or object by pressing it or by putting it into a mould","cn":"（用模具）浇铸，塑造","g":"[transitive]","ex":{"en":"First, mould the clay into the desired shape.","cn":"首先，将陶土做成需要的形状。"},"pos":"verb"},{"en":"to strongly influence the way somebody’s character, opinions, etc. develop","cn":"对…影响重大；将…塑造成","g":"[transitive]","ex":{"en":"The experience had moulded and coloured her whole life.","cn":"这次经历影响了她的一生。"},"pos":"verb"},{"en":"to fit or make something fit tightly around the shape of something","cn":"（使）紧贴于，吻合","g":"[intransitive, transitive]","ex":{"en":"The fabric moulds to the body.","cn":"这种织物很贴身。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模子;铸模；模具","en":"A mould is a hollow container that you pour liquid into. When the liquid becomes solid, it takes the same shape as the mould.","ex":{"en":"Spoon the mixture carefully into the mould","cn":"用勺小心地把混合物舀起，倒入模具内。"}},{"pos":"N-COUNT 可数名词","cn":"(性格、态度、行为或生活方式的)模式，类型","en":"If a person fits into or is cast in a mould of a particular kind, they have the characteristics, attitudes, behaviour, or lifestyle that are typical of that type of person.","ex":{"en":"At first sight, Joe Pesci is not exactly cast in the leading man mould","cn":"第一眼看上去，乔·佩希并不是当领袖的料。"}},{"pos":"VERB 动词","cn":"塑造;把…塑制成","en":"If you mould a soft substance such as plastic or clay, you make it into a particular shape or into an object.","ex":{"en":"Using 2 spoons, mould the cheese mixture into small balls or ovals","cn":"用两把小匙将奶酪混合物塑成圆球或椭圆球形状。"}},{"pos":"VERB 动词","cn":"影响;改变","en":"To mould someone or something means to change or influence them over a period of time so that they develop in a particular way.","ex":{"en":"She was only 17 at the time and the experience moulded her personality","cn":"那时她只有17岁，那次经历影响了她的性格。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)轮廓吻合，紧贴","en":"When something moulds to an object or when you mould it there, it fits round the object tightly so that the shape of the object can still be seen.","ex":{"en":"You need a malleable pillow that will mould to the curves of your neck","cn":"你需要一个柔韧性好、能与你的颈椎弯曲弧度相吻合的枕头。"}},{"pos":"N-MASS 物质名词","cn":"霉;霉菌","en":"Mould is a soft grey, green, or blue substance that sometimes forms in spots on old food or on damp walls or clothes."}]},"media":{"uk":"media/uk/mould__gb_1.mp3","us":"media/us/mould__us_1.mp3"},"examples":[{"en":"He moulded them into a superb team.","cn":"他将他们塑造成一支非凡的队伍。"},{"en":"First, mould the clay into the desired shape.","cn":"首先，将陶土做成需要的形状。"}]},"modulate":{"oxford":{"phon":"ˈmɒdjəleɪt","pos":"verb","senses":[{"en":"to change the quality of your voice in order to create a particular effect by making it louder, softer, lower, etc.","cn":"调节（嗓音的大小、强弱、高低等）","g":"[transitive]","lab":"formal"},{"en":"to change from one musical key (= set of notes) to another","cn":"变调；转调","g":"[intransitive]","lab":"music"},{"en":"to affect something so that it becomes more regular, slower, etc.","cn":"调整；调节；控制","g":"[transitive]","lab":"specialist","ex":{"en":"drugs that effectively modulate the disease process","cn":"可以有效控制疾病发展的药品"}},{"en":"to change the rate at which a sound wave or radio signal vibrates (= the frequency) so that it is clearer","cn":"调制（声波或无线电波频率）；调谐","g":"[transitive]","lab":"specialist"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"改变，调节(嗓音或声音)","en":"If you modulate your voice or a sound, you change or vary its loudness, pitch, or tone in order to create a particular effect.","ex":{"en":"He carefully modulated his voice.","cn":"他小心地压低了声音。"}},{"pos":"VERB 动词","cn":"调节;调整","en":"To modulate an activity or process means to alter it so that it is more suitable for a particular situation.","ex":{"en":"These chemicals modulate the effect of potassium.","cn":"这些化学物质可以调节钾的功效。"}}]},"media":{"uk":"media/uk/modulate__gb_1.mp3","us":"media/us/modulate__us_1.mp3"},"examples":[{"en":"drugs that effectively modulate the disease process","cn":"可以有效控制疾病发展的药品"},{"en":"These drugs modulate the disease process.","cn":"这些药物能控制病情的发展。"}]},"more":{"media":{"uk":"media/uk/more__gb_1.mp3","us":"media/us/more__us_1.mp3"},"oxford":{"phon":"mɔː(r)","pos":"determiner, pronoun","senses":[{"en":"a larger number or amount of","cn":"（数、量等）更多的，更大的","ex":{"en":"I want some more!","cn":"我还要！"}},{"en":"used to form the comparative of most adjectives and adverbs with two or more syllables","cn":"（与大多数两个或两个以上音节的形容词或副词连用，构成比较级）更","ex":{"en":"She was far more intelligent than her sister.","cn":"她比她姐姐聪明多了。"},"pos":"adverb"},{"en":"to a greater degree than something else; to a greater degree than usual","cn":"（程度上）更强，更多","lab":"formal","ex":{"en":"I like the film more than the book.","cn":"我喜欢这部电影胜过这本书。"},"pos":"adverb"},{"en":"again","cn":"又；再；重新","ex":{"en":"Could you repeat that once more (= one more time)?","cn":"你能再重复一遍吗？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"更多;较多(该词前可使用 a little，a lot，a bit，far和much)","en":"You use more to indicate that there is a greater amount of something than before or than average, or than something else. You can use 'a little', 'a lot', 'a bit', 'far', and 'much' in front of more .","ex":{"en":"More and more people are surviving heart attacks","cn":"越来越多的心脏病患者存活下来。"}},{"pos":"PREP-PHRASE 短语介词","cn":"超过;超出","en":"You use more than before a number or amount to say that the actual number or amount is even greater.","ex":{"en":"The Afghan authorities say the airport had been closed for more than a year.","cn":"阿富汗当局称，该机场已经关闭一年多了。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"比较多地；更加","en":"You use more to indicate that something or someone has a greater amount of a quality than they used to or than is average or usual.","ex":{"en":"Prison conditions have become more brutal","cn":"监狱条件变得更加严酷。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"更像（前者）地;与其说（是）…，倒不如说（是）","en":"If you say that something is more one thing than another, you mean that it is like the first thing rather than the second.","ex":{"en":"The exhibition at Boston's Museum of Fine Arts is more a production than it is a museum display","cn":"波士顿美术博物馆的展览与其说是一次博物馆展出，倒不如说是一场精心设计的展演活动。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"更大程度地；更经常地","en":"If you do something more than before or more than someone else, you do it to a greater extent or more often.","ex":{"en":"When we are tired, tense, depressed or unwell, we feel pain much more","cn":"当我们劳累、紧张、沮丧或生病时，疼痛感更明显。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"继续;再","en":"You can use more to indicate that something continues to happen for a further period of time.","ex":{"en":"Things might have been different if I'd talked a bit more.","cn":"如果当时我再多说一点的话，结果或许会不一样。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"再;另外;又一次","en":"You use more to indicate that something is repeated. For example, if you do something 'once more', you do it again once.","ex":{"en":"This train would stop twice more in the suburbs before rolling southeast toward Munich","cn":"火车向东南驶往慕尼黑前，会在郊区再停两站。"}},{"pos":"DET 限定词","cn":"另外的;附加的(该词前可使用 a little，a lot，a bit，far 和 much)","en":"You use more to refer to an additional thing or amount. You can use 'a little', 'a lot', 'a bit', 'far' and 'much' in front of more .","ex":{"en":"They needed more time to consider whether to hold an inquiry.","cn":"他们需要更多的时间来考虑是否进行调查。"}},{"pos":"PRON 代词","cn":"(用于 no more，no less, neither more nor less 等短语中，表示所说完全无误)多了的部分","en":"You can use more in expressions like 'no more, no less' and 'neither more nor less' to indicate that what you are saying is exactly true or correct.","ex":{"en":"I told him the truth. No more, no less","cn":"我告诉了他真相，未加任何演绎。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"还有;再者;而且","en":"You use more in conversations when you want to draw someone's attention to something interesting or important that you are about to say.","ex":{"en":"Europe's economies have converged in several areas. More interestingly, there has been convergence in economic growth rates","cn":"欧洲的经济已在多个领域互相趋同;更有意思的是，各国经济增长率也渐趋一致。"}},{"pos":"PHRASE 短语","cn":"越来越","en":"You can use more and more to indicate that something is becoming greater in amount, extent, or degree all the time.","ex":{"en":"Her life was heading more and more where she wanted it to go","cn":"她的生活越来越接近她理想的目标。"}},{"pos":"PHRASE 短语","cn":"或多或少;大概;几乎","en":"If something is more or less true, it is true in a general way, but is not completely true.","ex":{"en":"The Conference is more or less over","cn":"会议快结束了。"}},{"pos":"PHRASE 短语","cn":"比…更;比…更重要","en":"If something is more than a particular thing, it has greater value or importance than this thing.","ex":{"en":"He's more than a coach, he's a friend.","cn":"他不只是教练，更是朋友。"}},{"pos":"PHRASE 短语","cn":"超出需要;超乎寻常","en":"You use more than to say that something is true to a greater degree than is necessary or than average.","ex":{"en":"Lithuania produces more than enough food to feed itself.","cn":"立陶宛的粮食生产供大于求。"}},{"pos":"PHRASE 短语","cn":"不超过;不到;至多","en":"You use no more than or not more than when you want to emphasize how small a number or amount is.","ex":{"en":"Each box requires no more than a few hours of labor to build","cn":"做成一个盒子不超过几个小时。"}},{"pos":"PHRASE 短语","cn":"只不过;仅仅","en":"If you say that someone or something is nothing more than a particular thing, you are emphasizing that they are only that thing, and nothing more interesting or important.","ex":{"en":"The newly discovered notes are nothing more than Lang's personal journal.","cn":"新发现的笔记只不过是朗的个人日志。"}},{"pos":"PHRASE 短语","cn":"更有甚者;更为重要的是;此外","en":"You can use what is more or what's more to introduce an extra piece of information which supports or emphasizes the point you are making.","ex":{"en":"Many more institutions, especially banks, were allowed to lend money for mortgages, and what was more, banks could lend out more money than they actually held","cn":"允许更多的机构，尤其是银行推出抵押贷款;此外，银行发放的贷款可以超过其实际持有资金。"}},{"pos":"","cn":"","en":"all the more→see: ; any more→see: ;"}]},"examples":[{"en":"It had more the appearance of a deliberate crime than of an accident.","cn":"这件事看来是故意犯罪，而不是事故。"},{"en":"She spends more and more time alone in her room.","cn":"她一个人待在屋里的时间越来越多。"}]},"modelling":{"media":{"uk":"media/uk/modelling__gb_1.mp3","us":"media/us/modelling__us_1.mp3"},"oxford":{"phon":"ˈmɒdəlɪŋ","pos":"noun","senses":[{"en":"the work of a fashion model","cn":"（时装）模特儿工作，模特儿表演","ex":{"en":"a career in modelling","cn":"模特儿生涯"}},{"en":"the activity of making models of objects","cn":"（实物）模型制造","ex":{"en":"clay modelling","cn":"黏土模型制造"}},{"en":"the work of making a simple description of a system or a process that can be used to explain it, etc.","cn":"系统模型化；系统模型的建立","ex":{"en":"mathematical/statistical/computer modelling","cn":"数学／统计／电脑建模"}}]},"examples":[{"en":"mathematical/statistical/computer modelling","cn":"数学/统计学/电脑模型的建立"},{"en":"a modelling agency","cn":"模特儿经纪公司"}]},"modest":{"media":{"uk":"media/uk/modest__gb_1.mp3","us":"media/us/modest__us_1.mp3"},"oxford":{"phon":"ˈmɒdɪst","pos":"adjective","senses":[{"en":"not very large, expensive, important, etc.","cn":"些许的；不太大（或太贵、太重要等）的","ex":{"en":"modest improvements/reforms","cn":"不太显著的改进／改革"}},{"en":"not talking much about your own abilities or possessions","cn":"谦虚的；谦逊的","lab":"approving","ex":{"en":"She's very modest about her success.","cn":"她对自己的成功非常谦虚。"}},{"en":"shy about showing much of the body; not intended to attract attention, especially in a sexual way","cn":"庄重的；朴素的；不性感的","ex":{"en":"a modest dress","cn":"端庄的连衣裙"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(房屋等)不太大的，不算昂贵的，普通的","en":"A modest house or other building is not large or expensive.","ex":{"en":"...the modest home of a family who lived off the land","cn":"靠土地过活的一户人家的简朴住房"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(数量、比率或改进程度)不太高的，适度的，适中的","en":"You use modest to describe something such as an amount, rate, or improvement which is fairly small.","ex":{"en":"Swiss unemployment rose to the still modest rate of 0.7%","cn":"瑞士的失业率上升到了0.7%，这个百分比仍然不算太高。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谦虚的;谦恭的;谦逊的","en":"If you say that someone is modest, you approve of them because they do not talk much about their abilities or achievements.","ex":{"en":"He's modest, as well as being a great player","cn":"他是一名谦虚而伟大的运动员。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(女性或其衣着)端庄的，保守的;(行为)正派的，检点的","en":"You can describe a woman as modest when she avoids doing or wearing anything that might cause men to have sexual feelings towards her. You can also describe her clothes or behaviour as modest .","ex":{"en":"Asian women are more modest and shy, yet they tend to have an inner force","cn":"亚洲女性表现得更为端庄腼腆，却往往外柔内刚。"}}]},"examples":[{"en":"The research was carried out on a modest scale.","cn":"这个研究项目开展的规模不算太大。"},{"en":"She's very modest about her success.","cn":"她对自己的成功非常谦虚。"}]},"morals":{"oxford":{"phon":"ˈmɒrəl","pos":"adjective","senses":[{"en":"concerned with principles of right and wrong behaviour","cn":"道德的"},{"en":"based on your own sense of what is right and fair, not on legal rights or duties","cn":"道义上的；道德上的"}]}},"motorcycles":{"oxford":{"phon":"ˈməʊtəsaɪkl","pos":"noun","senses":[{"en":"a road vehicle with two wheels, driven by an engine, with one seat for the driver and often a seat for a passenger behind the driver","cn":"摩托车"}]}},"motivator":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something or someone that makes you want to do or achieve something","cn":"起激励作用的事物[人]﹐促进因素，动力"}]},"examples":[{"en":"Money is a good motivator.","cn":"钱是一个很大的动力。","src":"ld"}],"media":{"uk":"media/uk/motivator__gb_1.mp3","us":"media/us/motivator__us_1.mp3"},"oxford":{"phon":"ˈməʊtɪveɪtə(r)","pos":"noun","senses":[{"en":"a thing or person that makes somebody want to do something, especially something that involves hard work and effort","cn":"推动…甘愿苦干；激励；激发","ex":{"en":"Desire for status can be a powerful motivator.","cn":"对地位的渴望可以成为一股强大的推动力。"}}]}},"moreover":{"oxford":{"phon":"mɔːrˈəʊvə(r)","pos":"adverb","senses":[{"en":"used to introduce some new information that adds to or supports what you have said previously","cn":"此外；而且","ex":{"en":"A talented artist, he was, moreover, a writer of some note.","cn":"他是一位有才华的艺术家，同时也是颇有名气的作家。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"再者;而且;此外","en":"You use moreover to introduce a piece of information that adds to or supports the previous statement.","ex":{"en":"She saw that there was indeed a man immediately behind her. Moreover, he was observing her strangely","cn":"她看见真有一个男的紧跟在她身后，而且在怪异地注视自己。"}}]},"media":{"uk":"media/uk/moreover__gb_1.mp3","us":"media/us/moreover__us_1.mp3"},"examples":[{"en":"A talented artist, he was, moreover, a writer of some note.","cn":"他是一位有才华的艺术家，同时也是颇有名气的作家。"},{"en":"The rent is reasonable and, moreover, the location is perfect.","cn":"租金合理﹐而且位置绝佳。"}]},"mode":{"oxford":{"phon":"məʊd","pos":"noun","senses":[{"en":"a particular way of doing something; a particular type of something","cn":"方式；风格；样式","g":"[countable]","ex":{"en":"a mode of communication","cn":"交流方式"}},{"en":"the way in which a piece of equipment is set to perform a particular task","cn":"（设备的）模式，工作状态","g":"[countable, uncountable]","ex":{"en":"Switch the camera into the automatic mode.","cn":"将照相机调到自动拍摄模式。"}},{"en":"a particular way of feeling or behaving","cn":"（情感或行为的）状态，状况","g":"[uncountable, countable]","ex":{"en":"to be in holiday mode","cn":"处于假日状态"}},{"en":"a particular style or fashion in clothes, art, etc.","cn":"（衣着、艺术等的）形式，风格","g":"[countable, usually singular]","ex":{"en":"a pop video made by a director who really understands the mode","cn":"由真正了解流行风格的导演执导的流行音乐录像带"}},{"en":"a set of notes in music that form a scale","cn":"（音乐的）调式","g":"[singular]","lab":"specialist","ex":{"en":"major/minor mode","cn":"大调／小调调式"}},{"en":"the value that appears most frequently in a series of numbers","cn":"众数（一组数字中出现次数最多的数）","g":"[singular]","lab":"mathematics"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方法;做法;方式","en":"A mode of life or behaviour is a particular way of living or behaving.","ex":{"en":"...the capitalist mode of production","cn":"资本主义生产方式"}},{"pos":"N-COUNT 可数名词","cn":"（艺术、着装等的）风格、文体","en":"A mode is a particular style in art, literature, or dress.","ex":{"en":"...a slightly more elegant and formal mode of dress","cn":"略显典雅和正式的着装风格"}},{"pos":"N-COUNT 可数名词","cn":"(照相机、电子设备的)模式，状态","en":"On some cameras or electronic devices, the different modes available are the different programs or settings that you can choose when you use them.","ex":{"en":"...when the camera is in manual mode.","cn":"当相机处于手动拍摄模式的时候"}}]},"media":{"uk":"media/uk/mode__gb_1.mp3","us":"media/us/mode__us_1.mp3"},"examples":[{"en":"a pop video made by a director who really understands the mode","cn":"由真正了解流行风格的制作人制作的流行音乐录像带"},{"en":"Switch the camera into the automatic mode.","cn":"将照相机调到自动拍摄模式。"}]},"moral":{"oxford":{"phon":"ˈmɒrəl","pos":"adjective","senses":[{"en":"connected with principles of right and wrong behaviour","cn":"道德的","g":"[only before noun]","ex":{"en":"a moral issue/dilemma","cn":"道德议题／困境"}},{"en":"based on your own sense of what is right and fair, not on legal rights or duties","cn":"道义上的；道德上的","g":"[only before noun]","ex":{"en":"moral responsibility/duty/authority","cn":"道义上的责任／义务／权威"}},{"en":"following the standards of behaviour considered acceptable and right by most people","cn":"品行端正的；有道德的","ex":{"en":"He led a very moral life.","cn":"他这个人一向很正派。"}},{"en":"able to understand the difference between right and wrong","cn":"能辨别是非的","g":"[only before noun]","ex":{"en":"Children are not naturally moral beings.","cn":"儿童并非天生就能分辨是非。"}},{"en":"standards or principles of good behaviour, especially in matters of sexual relationships","cn":"品行，道德（尤指性关系方面）","g":"[plural]","lab":"old-fashioned","ex":{"en":"Young people these days have no morals.","cn":"现在的年轻人根本不讲道德。"},"pos":"noun"},{"en":"a practical lesson that a story, an event or an experience teaches you","cn":"寓意；教益","g":"[countable]","ex":{"en":"The moral of the story is always stick to what you do best.","cn":"这个故事的寓意是要始终做自己最擅长的事。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"道德（规范）;品德;品行","en":"Morals are principles and beliefs concerning right and wrong behaviour.","ex":{"en":"...Western ideas and morals","cn":"西方的思想和道德规范"}},{"pos":"ADJ 形容词","cn":"道德上的;道义上的","en":"Moral means relating to beliefs about what is right or wrong.","ex":{"en":"She describes her own moral dilemma in making the film.","cn":"她讲述了拍摄这部电影过程中她在道义上所面临的两难选择。"}},{"pos":"ADJ 形容词","cn":"（勇气或职责）道义上的;基于道德规范的","en":"Moral courage or duty is based on what you believe is right or acceptable, rather than on what the law says should be done.","ex":{"en":"The Government had a moral, if not a legal duty to pay compensation.","cn":"政府即使没有法律责任，在道义上也有责任来赔偿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有道德的;品行端正的","en":"A moral person behaves in a way that is believed by most people to be good and right.","ex":{"en":"The people who will be on the committee are moral, cultured, competent people.","cn":"进入委员会的人要品行端正，有文化，有能力。"}},{"pos":"ADJ 形容词","cn":"(支持)道义上的，精神上的","en":"If you give someone moral support, you encourage them in what they are doing by expressing approval.","ex":{"en":"Moral as well as financial support was what the West should provide.","cn":"西方国家应该提供道义支持和经济援助。"}},{"pos":"N-COUNT 可数名词","cn":"(由故事、事件引出的)道德训诫，寓意","en":"The moral of a story or event is what you learn from it about how you should or should not behave.","ex":{"en":"I think the moral of the story is let the buyer beware","cn":"我想这个故事的寓意是提醒购物者当心。"}},{"pos":"","cn":"","en":"moral victory→see: ;"}]},"media":{"uk":"media/uk/moral__gb_1.mp3","us":"media/us/moral__us_1.mp3"},"examples":[{"en":"( BrE ) The job was to call on all her diplomatic skills and moral courage (= the courage to do what you think is right).","cn":"这项工作需要她发挥全部的外交才能和捍卫正义的勇气。"},{"en":"Governments have at least a moral obligation to answer these questions.","cn":"政府至少在道义上有责任回应这些问题。"}]},"mood":{"media":{"uk":"media/uk/mood__gb_1.mp3","us":"media/us/mood__us_1.mp3"},"oxford":{"phon":"muːd","pos":"noun","senses":[{"en":"the way you are feeling at a particular time","cn":"情绪；心情","g":"[countable]","ex":{"en":"She's in a good mood today (= happy and friendly).","cn":"她今天心情很好。"}},{"en":"a period of being angry or impatient","cn":"坏心境；坏脾气","g":"[countable]","ex":{"en":"I wonder why he's in such a mood today.","cn":"我不知道他为什么今天脾气这么坏。"}},{"en":"the way a group of people feel about something; the atmosphere in a place or among a group of people","cn":"气氛；氛围","g":"[singular]","ex":{"en":"The mood of the meeting was distinctly pessimistic.","cn":"这次会议的气氛显然很悲观。"}},{"en":"one of the sets of verb forms or categories of verb use that expresses facts, orders, questions, wishes or conditions","cn":"（动词的）语气","g":"[countable]","lab":"grammar","ex":{"en":"the indicative/imperative/subjunctive mood","cn":"陈述／祈使／虚拟语气"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心情;心境","en":"Your mood is the way you are feeling at a particular time. If you are in a good mood, you feel cheerful. If you are in a bad mood, you feel angry and impatient.","ex":{"en":"He is clearly in a good mood today","cn":"明摆着，他今天心情不错。"}},{"pos":"N-COUNT 可数名词","cn":"坏心情;坏脾气","en":"If someone is in a mood, the way they are behaving shows that they are feeling angry and impatient.","ex":{"en":"She was obviously in a mood.","cn":"她显然情绪不佳。"}},{"pos":"N-SING 单数名词","cn":"（群体的）态度，心态，意愿","en":"The mood of a group of people is the way that they think and feel about an idea, event, or question at a particular time.","ex":{"en":"The government seemed to be in tune with the popular mood","cn":"政府似乎和民众的意愿是一致的。"}},{"pos":"N-COUNT 可数名词","cn":"气氛;氛围","en":"The mood of a place is the general impression that you get of it.","ex":{"en":"First set the mood with music","cn":"首先用音乐烘托气氛。"}},{"pos":"N-VAR 可变名词","cn":"(语法中的)语气","en":"In grammar, the mood of a clause is the way in which the verb forms are used to show whether the clause is, for example, a statement, a question, or an instruction."}]},"examples":[{"en":"The movie captures the mood of the interwar years perfectly.","cn":"这部电影恰如其分地捕捉到了两次世界大战中间这些年的氛围。"},{"en":"Some addicts suffer violent mood swings (= changes of mood) if deprived of the drug.","cn":"一些吸毒成瘾的人一旦没有毒品就会出现情绪的极度波动。"}]},"modernization":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to improve something, so that it includes the most modern equipment, methods, or information","cn":""},{"en":"to make big changes to a place or organization, by putting in modern equipment or modern systems, and getting rid of old ones","cn":""}]},"examples":[{"en":"They need more funds to modernize the country’s telephone system.","cn":"","src":"ld"},{"en":"The business will lose money if it doesn’t modernize.","cn":"","src":"ld"}],"media":{"uk":"media/uk/modernization__gb_1.mp3","us":"media/us/modernization__us_1.mp3"},"oxford":{"phon":"ˌmɒdənaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the process of making a system, methods, etc. more modern and more suitable for use at the present time","cn":"现代化","ex":{"en":"In 1955 the railways' modernization programme was drawn up.","cn":"1955 年制定了铁路现代化计划。"}}]}},"monkeys":{"oxford":{"phon":"ˈmʌŋki","pos":"noun","senses":[{"en":"an animal with a long tail, that climbs trees and lives in hot countries. There are several types of monkey and they are related to apes and humans.","cn":"猴子"},{"en":"( informal ) a child who is active and likes playing tricks on people","cn":"顽皮的孩子；调皮鬼；捣蛋鬼"}]}},"monolinguals":{"oxford":{"phon":"ˌmɒnəˈlɪŋɡwəl","pos":"adj.","senses":[{"en":"speaking or using only one language","cn":"单语的；只用一种语言的"}]},"media":{"uk":"media/uk/monolingual__gb_1.mp3","us":"media/us/monolingual__us_1.mp3"}},"molten":{"media":{"uk":"media/uk/molten__gb_1.mp3","us":"media/us/molten__us_1.mp3"},"oxford":{"phon":"ˈməʊltən","pos":"adjective","senses":[{"en":"heated to a very high temperature so that it becomes liquid","cn":"熔化的；熔融的","ex":{"en":"molten lead","cn":"熔铅"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"熔化的;熔融的","en":"Molten rock, metal, or glass has been heated to a very high temperature and has become a hot thick liquid.","ex":{"en":"The molten metal is poured into the mould.","cn":"把熔化的金属倒入铸模。"}}]},"examples":[{"en":"molten iron","cn":"熔铁"}]},"motivates":{"oxford":{"phon":"ˈməʊtɪveɪt","pos":"verb","senses":[{"en":"to be the reason why sb does sth or behaves in a particular way","cn":"成为 … 的动机；是 … 的原因"},{"en":"to make sb want to do sth, especially sth that involves hard work and effort","cn":"推动 … 甘愿苦干；激励；激发"}]},"media":{"uk":"media/uk/motivate__gb_1.mp3","us":"media/us/motivate__us_1.mp3"}},"modern":{"media":{"uk":"media/uk/modern__gb_1.mp3","us":"media/us/modern__us_1.mp3"},"oxford":{"phon":"ˈmɒdn","pos":"adjective","senses":[{"en":"of the present time or recent times","cn":"现代的；当代的；近代的","g":"[only before noun]","ex":{"en":"the modern industrial world","cn":"当今工业世界"}},{"en":"new and intended to be different from traditional styles","cn":"新式的；有别于传统的","g":"[only before noun]","ex":{"en":"The gallery has regular exhibitions of modern art.","cn":"画廊定期举办现代艺术展览。"}},{"en":"using the latest technology, designs, materials, ideas, etc.","cn":"现代化的；先进的；最新的","lab":"usually approving","ex":{"en":"The company needs to invest in a modern computer system.","cn":"公司需要投资建立最新的计算机系统。"}},{"en":"new and not always accepted by most members of society","cn":"新式的，超前的（大部分公众不一定接受）","ex":{"en":"She has very modern ideas about educating her children.","cn":"在教育子女方面，她有非常新式的观点。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"近代的;现代的","en":"Modern means relating to the present time, for example the present decade or present century.","ex":{"en":"...the problem of materialism in modern society.","cn":"现代社会的实利主义问题"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"现代化的;新式的;最新的","en":"Something that is modern is new and involves the latest ideas or equipment.","ex":{"en":"Modern technology has opened our eyes to many things","cn":"现代科技开阔了我们的眼界，让我们了解了许多事物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新潮的;时髦的;摩登的","en":"People are sometimes described as modern when they have opinions or ways of behaviour that have not yet been accepted by most people in a society.","ex":{"en":"They were very modern Tories in almost every sense","cn":"从几乎所有意义上说，他们都属于非常新潮的保守主义分子。"}},{"pos":"ADJ 形容词","cn":"(艺术、舞蹈、音乐、建筑的风格)现代的，近代的","en":"Modern is used to describe styles of art, dance, music, and architecture that have developed in recent times, in contrast to classical styles.","ex":{"en":"...a modern dance company.","cn":"现代舞蹈团"}}]},"examples":[{"en":"She has very modern ideas about educating her children.","cn":"在教育子女方面，她有非常新式的观点。"},{"en":"the most modern, well-equipped hospital in London","cn":"伦敦最先进的、设备最精良的医院"}]},"monday":{"media":{"uk":"media/uk/monday__gb_1.mp3","us":"media/us/monday__us_1.mp3"},"oxford":{"phon":"ˈmʌndeɪ","pos":"noun","senses":[{"en":"the day of the week after Sunday and before Tuesday, the first day of the working week","cn":"星期一","lab":"informal or North American English","ex":{"en":"It's Monday today, isn't it?","cn":"今天是星期一，对吧？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"星期一;周一","en":"Monday is the day after Sunday and before Tuesday.","ex":{"en":"I went back to work on Monday","cn":"我周一回去上班了。"}}]},"examples":[{"en":"( BrE ) ‘When did the accident happen?’ ‘It was the Monday (= the Monday of the week we are talking about). ’ “","cn":"事故是什么时候发生的？” “就在那个星期一。”"},{"en":"I went to Paris on Thursday, and came back the following Monday.","cn":"我星期四去了巴黎，第二周的星期一就回来了。"}]},"moving":{"media":{"uk":"media/uk/moving__gb_1.mp3","us":"media/us/moving__us_1.mp3"},"oxford":{"phon":"ˈmuːvɪŋ","pos":"adjective","senses":[{"en":"causing strong, often sad, feelings about somebody/something","cn":"感人的；令人伤感的","ex":{"en":"a deeply moving experience","cn":"非常动人的经历"}},{"en":"changing from one place or position to another","cn":"移动的；运动的","g":"[only before noun]","ex":{"en":"the moving parts of a machine","cn":"机器的活动部件"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感人的;令人感伤（或同情）的","en":"If something is moving, it makes you feel strongly an emotion such as sadness, pity, or sympathy.","ex":{"en":"It is very moving to see how much strangers can care for each other","cn":"看到陌生人之间这般彼此关照，实在令人感动。"}},{"pos":"ADJ 形容词","cn":"(模型或机器部件)活动的，可移动的","en":"A moving model or part of a machine moves or is able to move."},{"pos":"PHRASE 短语","cn":"推动力；起激励作用的人(或事)","en":"The moving spirit or moving force behind something is the person or thing that caused it to start and to keep going, or that influenced people to take part in it.","ex":{"en":"She alone must have been the moving spirit behind the lawsuit that lost me my position","cn":"肯定是她一个人主使了让我丢掉职位的诉讼。"}}]},"examples":[{"en":"She described her experiences in Africa very movingly.","cn":"她十分动人地描述了她在非洲的经历。"},{"en":"the moving parts of a machine","cn":"机器的活动部件"}]},"mortar":{"oxford":{"phon":"ˈmɔːtə(r)","pos":"noun","senses":[{"en":"a mixture of sand, water, lime and cement used in building for holding bricks and stones together","cn":"砂浆；灰浆","g":"[uncountable]"},{"en":"a heavy gun that fires bombs and shells high into the air; the bombs that are fired by this gun","cn":"迫击炮；迫击炮弹","g":"[countable]","ex":{"en":"to come under mortar fire/attack","cn":"受到迫击炮火的袭击"}},{"en":"a small hard bowl in which you can crush substances such as seeds and grains to make them into powder with a special object (called a pestle)","cn":"研钵；臼","g":"[countable]"},{"en":"to attack somebody/something using a mortar","cn":"用迫击炮攻击（或袭击）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"迫击炮","en":"A mortar is a big gun which fires missiles high into the air over a short distance.","ex":{"en":"The two sides exchanged fire with artillery, mortars and small arms","cn":"双方交火时动用了大炮、迫击炮和轻武器。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"灰浆;砂浆;胶泥","en":"Mortar is a mixture of sand, water, and cement or lime which is put between bricks to hold them together."},{"pos":"N-COUNT 可数名词","cn":"研钵;臼","en":"A mortar is a bowl in which you can crush things such as herbs, spices, or grain using a rod called a pestle."},{"pos":"","cn":"","en":"bricks and mortar→see: ;"}]},"media":{"img":["media/pic/crushing_kitchenutensils_comp.jpg","media/thumb/pestleandmortar.jpg","media/ldoce/img/pestle.jpg"],"uk":"media/uk/mortar__gb_1.mp3","us":"media/us/mortar__us_1.mp3"},"examples":[{"en":"to come under mortar fire/attack","cn":"受到迫击炮火的袭击"},{"en":"A cameraman was killed when his vehicle came under mortar fire .","cn":"一名摄影师因所乘坐的汽车遭到迫击炮袭击而丧生。"}]},"money":{"media":{"img":["media/pic/money_comp.jpg","media/thumb/coin.jpg"],"uk":"media/uk/money__gb_1.mp3","us":"media/us/money__us_1.mp3"},"oxford":{"phon":"ˈmʌni","pos":"noun","senses":[{"en":"what you earn by working or selling things, and use to buy things","cn":"钱；金钱","g":"[uncountable]","lab":"informal","ex":{"en":"to borrow/save/spend/earn money","cn":"借钱；存钱；花钱；挣钱"}},{"en":"coins or paper notes","cn":"钱币；钞票","g":"[uncountable]","ex":{"en":"I counted the money carefully.","cn":"我仔细点过这笔钱。"}},{"en":"a person’s wealth including their property","cn":"财产；财富","g":"[uncountable]","ex":{"en":"He lost all his money.","cn":"他失去了全部财产。"}},{"en":"sums of money","cn":"款项","g":"[plural]","lab":"law or old use","ex":{"en":"a statement of all monies paid into your account","cn":"存入你的账户的所有款项的明细表"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"钱;金钱","en":"Money is the coins or bank notes that you use to buy things, or the sum that you have in a bank account.","ex":{"en":"A lot of the money that you pay at the cinema goes back to the film distributors","cn":"你在电影院消费的一大部分钱都会回到电影发行商手里。"}},{"pos":"N-PLURAL 复数名词","cn":"款项;钱款","en":"Monies is used to refer to several separate sums of money that form part of a larger amount that is received or spent.","ex":{"en":"We drew up a schedule of payments for the rest of the monies owed.","cn":"我们起草了一份剩余欠款的还款计划。"}},{"pos":"PHRASE 短语","cn":"有花不完的钱;钱多得烫手;钱多得烧包","en":"If you say that someone has money to burn, you mean that they have more money than they need or that they spend their money on things that you think are unnecessary.","ex":{"en":"He was a high-earning broker with money to burn.","cn":"他是高收入的经纪人，有花不完的钱。"}},{"pos":"PHRASE 短语","cn":"非常有钱的;手头宽裕的","en":"If you are in the money, you have a lot of money to spend.","ex":{"en":"If you are one of the lucky callers chosen to play, you could be in the money.","cn":"如果你有幸成为其中一个被选中参加表演的来电者，就可能会赚大钱。"}},{"pos":"PHRASE 短语","cn":"挣钱;赚钱","en":"If you make money, you obtain money by earning it or by making a profit.","ex":{"en":"They couldn't find work or make money in the cities.","cn":"他们在城市找不到工作，也赚不到钱。"}},{"pos":"PHRASE 短语","cn":"用行动证明自己的话；说到做到;说给钱就给钱","en":"If you say that you want someone to put their money where their mouth is, you want them to spend money to improve a bad situation, instead of just talking about improving it.","ex":{"en":"The government might be obliged to put its money where its mouth is to prove its commitment.","cn":"政府也许会被迫付出行动，以兑现承诺。"}},{"pos":"PHRASE 短语","cn":"(因掌握内情而下的)高明赌注","en":"If you say that the smart money is on a particular person or thing, you mean that people who know a lot about it think that this person will be successful, or this thing will happen.","ex":{"en":"With England not playing, the smart money was on the Germans","cn":"英格兰队没有参赛，所以人们看好德国队应该会赢。"}},{"pos":"PHRASE 短语","cn":"金钱万能;有钱能使鬼推磨","en":"If you say that money talks, you mean that if someone has a lot of money, they also have a lot of power.","ex":{"en":"The formula in Hollywood is simple—money talks.","cn":"好莱坞的生存规则很简单，就是金钱万能。"}},{"pos":"PHRASE 短语","cn":"白白扔钱;花冤枉钱","en":"If you say that someone is throwing money at a problem, you are critical of them for trying to improve it by spending money on it, instead of doing more thoughtful and practical things to improve it.","ex":{"en":"The Australian government's answer to the problem has been to throw money at it.","cn":"澳大利亚政府对这个问题的解决方案一直就是大把往里扔钱。"}},{"pos":"PHRASE 短语","cn":"花钱填无底洞;继续砸钱","en":"If you say that someone is throwing good money after bad, you are critical of them for trying to improve a bad situation by spending more money on it, instead of doing more thoughtful or practical things to improve it.","ex":{"en":"Further heavy intervention would be throwing good money after bad.","cn":"进一步加大干预的力度只会是继续白扔钱。"}},{"pos":"PHRASE 短语","cn":"钱花得值;物有所值；没白忙活","en":"If you get your money's worth, you get something which is worth the money that it costs or the effort you have put in.","ex":{"en":"The fans get their money's worth.","cn":"粉丝们的钱没白花。"}},{"pos":"","cn":"","en":"to see the colour of someone's money→see: ; a licence to print money→see: ; to be rolling in money→see: ; money for old rope→see: ; to give someone a run for their money→see: ;"}]},"examples":[{"en":"Thousands of people paid good money to watch the band perform.","cn":"成千上万的人花很多钱去观看这支乐队的演出。"},{"en":"For my money, he's one of the greatest comedians of all time.","cn":"依我看，历来的喜剧演员，他是数一数二的。"}]},"motorized":{"media":{"uk":"media/uk/motorized__gb_1.mp3","us":"media/us/motorized__us_1.mp3"},"oxford":{"phon":"ˈməʊtəraɪzd","pos":"adjective","senses":[{"en":"having an engine","cn":"有引擎的；机动的","ex":{"en":"motorized vehicles","cn":"机动车辆"}},{"en":"using vehicles with engines","cn":"使用机动车的；摩托化的；机动化的","ex":{"en":"motorized forces/divisions","cn":"摩托化部队／师"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（车辆）装有发动机的，机动的","en":"A motorized vehicle has an engine.","ex":{"en":"Around 1910 motorized carriages were beginning to replace horse-drawn cabs.","cn":"大约从1910年起，机动车开始取代马车。"}},{"pos":"ADJ 形容词","cn":"（部队）摩托化的，机动的","en":"A motorized group of soldiers is equipped with motor vehicles.","ex":{"en":"...motorized infantry and artillery.","cn":"摩托化的步兵和炮兵部队"}}]},"examples":[{"en":"motorized forces/divisions","cn":"摩托化部队/师"},{"en":"motorized vehicles","cn":"机动车辆"}]},"mores":{"media":{"uk":"media/uk/mores__gb_1.mp3","us":"media/us/mores__us_1.mp3"},"oxford":{"phon":"ˈmɔːreɪz","pos":"noun","senses":[{"en":"the customs and behaviour that are considered typical of a particular social group or community","cn":"风俗习惯；传统","ex":{"en":"changes in social mores","cn":"社会习俗的变化"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"习俗;传统习惯;惯例","en":"The mores of a particular place or group of people are the customs and behaviour that are typically found in that place or group.","ex":{"en":"...the accepted mores of British society.","cn":"英国社会接受的习俗"}}]},"examples":[{"en":"contemporary social and sexual mores","cn":"当代社会习俗和性观念"}]},"monkey":{"oxford":{"phon":"ˈmʌŋki","pos":"noun","senses":[{"en":"an animal with a long tail, that climbs trees and lives in hot countries. There are several types of monkey and they are related to apes and humans.","cn":"猴子","ex":{"en":"Like humans, apes and monkeys live in complex social groupings.","cn":"与人类一样，类人猿和猴子都生活在复杂的社会群体中。"}},{"en":"a child who is active and likes playing tricks on people","cn":"顽皮的孩子；调皮鬼；捣蛋鬼","lab":"informal","ex":{"en":"Come here, you cheeky little monkey!","cn":"过来，你这没有教养的小捣蛋鬼！"}},{"en":"£500","cn":"500 英镑","lab":"British English, slang，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猴","en":"A monkey is an animal with a long tail which lives in hot countries and climbs trees."},{"pos":"N-COUNT 可数名词","cn":"淘气鬼;捣蛋鬼","en":"If you refer to a child as a monkey, you are saying in an affectionate way that he or she is very lively and naughty.","ex":{"en":"She's such a little monkey.","cn":"她真是一个小捣蛋鬼。"}}]},"media":{"img":["media/pic/primates_comp.jpg","media/thumb/spidermonkey.jpg"],"uk":"media/uk/monkey__gb_1.mp3","us":"media/us/monkey__us_1.mp3"},"examples":[{"en":"Come here, you cheeky little monkey!","cn":"过来，你这没有教养的小捣蛋鬼！"},{"en":"Stop that, you little monkey!","cn":"别这样﹐你这个小淘气鬼！"}]},"morning":{"media":{"uk":"media/uk/morning__gb_1.mp3","us":"media/us/morning__us_1.mp3"},"oxford":{"phon":"ˈmɔːnɪŋ","pos":"noun","senses":[{"en":"the early part of the day from the time when people wake up until 12 o'clock in the middle of the day or before lunch","cn":"早晨；上午","ex":{"en":"They left for Spain early this morning.","cn":"他们今天一早就出发去西班牙了。"}},{"en":"the part of the day from midnight to midday","cn":"午夜至正午的时间","ex":{"en":"I didn't get home until two in the morning!","cn":"我凌晨两点才到家！"}},{"en":"in the morning of each day","cn":"在上午；在早晨；每天上午","ex":{"en":"I only work mornings.","cn":"我只在上午工作。"}},{"en":"short for good morning (= used to say hello politely when people first see each other in the morning)","cn":"那天，那天早上，那天晚上，那个星期（用于指说话前不久的日子）","pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"早晨;上午(从人们通常醒来到中午或午餐前的一段时间)","en":"The morning is the part of each day between the time that people usually wake up and 12 o'clock noon or lunchtime.","ex":{"en":"During the morning your guide will take you around the city","cn":"导游上午会带你们游览全城。"}},{"pos":"N-SING 单数名词","cn":"凌晨，早晨，上午(从子夜到中午的这段时间)","en":"If you refer to a particular time in the morning, you mean a time between 12 o'clock midnight and 12 o'clock noon.","ex":{"en":"I often stayed up until two or three in the morning","cn":"我经常凌晨两三点才睡。"}},{"pos":"PHRASE 短语","cn":"第二天上午;次日上午","en":"If you say that something will happen in the morning, you mean that it will happen during the morning of the following day.","ex":{"en":"I'll fly it to London in the morning","cn":"我明天上午会把它用航空快件寄到伦敦。"}},{"pos":"PHRASE 短语","cn":"日日夜夜;夜以继日；一直","en":"If you say that something happens morning, noon and night, you mean that it happens all the time.","ex":{"en":"You get fit by playing the game, day in, day out, morning, noon and night.","cn":"从早到晚都坚持做这项运动，日复一日，你就能强壮起来。"}}]},"examples":[{"en":"We got the news on the morning of the wedding.","cn":"我们在举行婚礼的那天上午得到这个消息。"},{"en":"It must have happened at about five o'clock in the morning.","cn":"这件事一定发生在凌晨五点钟左右。"}]},"moisture":{"oxford":{"phon":"ˈmɔɪstʃə(r)","pos":"noun","senses":[{"en":"very small drops of water or other liquid that are present in the air, on a surface or in a substance","cn":"水分；潮气；水汽","ex":{"en":"the skin’s natural moisture","cn":"皮肤的天然水分"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"潮气;湿气;水分","en":"Moisture is tiny drops of water in the air, on a surface, or in the ground.","ex":{"en":"When the soil is dry, more moisture is lost from the plant","cn":"土壤干燥时，植物会流失更多的水分。"}}]},"media":{"uk":"media/uk/moisture__gb_1.mp3","us":"media/us/moisture__us_1.mp3"},"examples":[{"en":"a material that is designed to absorb/retain moisture","cn":"用来吸收/保持水分的材料"},{"en":"the skin's natural moisture","cn":"皮肤的天然水分"}]},"month":{"media":{"uk":"media/uk/month__gb_1.mp3","us":"media/us/month__us_1.mp3"},"oxford":{"phon":"mʌnθ","pos":"noun","senses":[{"en":"any of the twelve periods of time into which the year is divided, for example May or June","cn":"月；月份","g":"[countable]","ex":{"en":"The months of July and August are the hottest.","cn":"七八月份是最热的时候。"}},{"en":"a period of about 30 days, for example, 3 June to 3 July","cn":"约 30 天的时间；一个月的时间","g":"[countable]","ex":{"en":"The baby is three months old.","cn":"这婴儿三个月大了。"}},{"en":"a long time, especially a period of several months","cn":"数月；很长时间","g":"[plural]","ex":{"en":"He had to wait for months for the visas to come through.","cn":"他不得不等好几个月才领到签证。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"月;月份","en":"A month is one of the twelve periods of time that a year is divided into, for example January or February.","ex":{"en":"The trial is due to begin next month.","cn":"审判将于下个月开始。"}},{"pos":"N-COUNT 可数名词","cn":"一个月（的时间）","en":"A month is a period of about four weeks.","ex":{"en":"She was here for a month","cn":"她在这儿呆了一个月。"}}]},"examples":[{"en":"Have you read this month's ‘Physics World’?","cn":"你看过这个月的《物理世界》吗？"},{"en":"They lived in Toronto during their first few months of marriage.","cn":"他们婚后的头几个月住在多伦多。"}]},"movement":{"media":{"uk":"media/uk/movement__gb_1.mp3","us":"media/us/movement__us_1.mp3"},"oxford":{"phon":"ˈmuːvmənt","pos":"noun","senses":[{"en":"an act of moving the body or part of the body","cn":"（身体部位的）运动，转动，活动","g":"[countable, uncountable]","sc":"changing position","ex":{"en":"hand/eye movements","cn":"手／眼睛的动作"}},{"en":"an act of moving from one place to another or of moving something from one place to another","cn":"移动；迁移；转移；活动","g":"[countable, uncountable]","sc":"changing position","ex":{"en":"enemy troop movements","cn":"敌军的调动"}},{"en":"a group of people who share the same ideas or aims","cn":"（具有共同思想或目标的）运动","g":"[countable + singular or plural verb]","lab":"especially North American English","sc":"group of people","ex":{"en":"the trade union movement","cn":"工会运动"}},{"en":"a person’s activities over a period of time, especially as watched by somebody else","cn":"（尤指受监视者的）活动；行踪","g":"[plural]","sc":"person’s activities","ex":{"en":"The police are keeping a close watch on the suspect's movements.","cn":"警察正在密切监视嫌疑犯的活动。"}},{"en":"a slow steady change in what people in society do or think","cn":"（社会活动或思潮的）变化，演变","g":"[singular]","sc":"change of ideas/behaviour","ex":{"en":"We see a big movement away from cash.","cn":"我们正在经历一场弃用现金的大潮。"}},{"en":"progress, especially in a particular task","cn":"（尤指某一工作的）进步，进展","g":"[uncountable]","sc":"progress","ex":{"en":"It needs cooperation from all the countries to get any movement in arms control.","cn":"要在军控方面取得进展需要所有国家的合作。"}},{"en":"a change in amount","cn":"量的变化；增减","g":"[uncountable, countable]","sc":"change in amount","ex":{"en":"There has been no movement in oil prices.","cn":"石油价格没有变化。"}},{"en":"any of the main parts that a long piece of music is divided into","cn":"乐章","g":"[countable]","sc":"music","ex":{"en":"the slow movement of the First Concerto","cn":"第一协奏曲的和缓乐章"}},{"en":"an act of emptying waste material from the bowels; the waste material that is emptied","cn":"解大便；粪便","g":"[countable]","lab":"medical","sc":"of bowels"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(拥有共同信仰、思想或目标的)运动，运动团体","en":"A movement is a group of people who share the same beliefs, ideas, or aims.","ex":{"en":"It's part of a broader Hindu nationalist movement that's gaining strength throughout the country.","cn":"这是一场凝聚全国力量的更大规模的印度教民族主义运动的一部分。"}},{"pos":"N-VAR 可变名词","cn":"活动;运行;移动","en":"Movement involves changing position or going from one place to another.","ex":{"en":"They actually monitor the movement of the fish going up river.","cn":"他们实际上在监测鱼类迁往上游的活动。"}},{"pos":"N-VAR 可变名词","cn":"(军队作战或演习时的)调遣，调动","en":"A movement is a planned change in position that an army makes during a battle or military exercise.","ex":{"en":"There are reports of fresh troop movements across the border.","cn":"有报告说，新近有军队越过边境。"}},{"pos":"N-VAR 可变名词","cn":"(态度、观点、政策等的)逐渐变化，趋势，动向","en":"Movement is a gradual development or change of an attitude, opinion, or policy.","ex":{"en":"...the movement towards democracy in Latin America","cn":"拉丁美洲的民主进程"}},{"pos":"N-PLURAL 复数名词","cn":"(某人在某一时期内的)行动，活动，动向","en":"Your movements are everything which you do or plan to do during a period of time.","ex":{"en":"I want a full account of your movements the night Mr Gower was killed.","cn":"请你完整地描述一下高尔先生被杀的那天晚上你的一切行踪。"}},{"pos":"N-COUNT 可数名词","cn":"乐章","en":"A movement of a piece of classical music is one of its main sections.","ex":{"en":"...the first movement of Beethoven's 7th symphony.","cn":"贝多芬《第七交响曲》第一乐章"}}]},"examples":[{"en":"It needs cooperation from all the countries to get any movement in arms control.","cn":"要在军控方面取得进展需要所有国家的合作。"},{"en":"She observed the gentle movement of his chest as he breathed.","cn":"她观察着他呼吸时胸部的微微起伏。"}]},"mountainside":{"media":{"uk":"media/uk/mountainside__gb_1.mp3","us":"media/us/mountainside__us_1.mp3"},"oxford":{"phon":"ˈmaʊntənsaɪd","pos":"noun","senses":[{"en":"the side or slope of a mountain","cn":"山坡","ex":{"en":"Tracks led up the mountainside.","cn":"足迹通向山坡。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山坡;山腹","en":"A mountainside is one of the steep sides of a mountain.","ex":{"en":"The couple trudged up the dark mountainside.","cn":"这对夫妇在黑黝黝的山坡上艰难跋涉。"}}]},"examples":[{"en":"Tracks led up the mountainside.","cn":"小径沿着山坡向上延伸。"},{"en":"Great rocks rolled down the mountainside.","cn":"巨大的岩石顺着山坡滚落下来。"}]},"motorcycle":{"oxford":{"phon":"ˈməʊtəsaɪkl","pos":"noun","senses":[{"en":"a road vehicle with two wheels, driven by an engine, with one seat for the driver and often a seat for a passenger behind the driver","cn":"摩托车","lab":"British English","ex":{"en":"He never learned to ride a motorcycle or to drive a car.","cn":"他从未学过骑摩托车或驾驶汽车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摩托车","en":"A motorcycle is a vehicle with two wheels and an engine."}]},"media":{"img":["media/pic/cycles_comp.jpg","media/thumb/motorcycle.jpg"],"uk":"media/uk/motorcycle__gb_1.mp3","us":"media/us/motorcycle__us_1.mp3"},"examples":[{"en":"a motorcycle accident","cn":"摩托车事故"},{"en":"motorcycle racing","cn":"摩托车赛"}]},"mopped":{"oxford":{"phon":"mɒp","pos":"noun","senses":[{"en":"a tool for washing floors that has a long handle with a bunch of thick strings or soft material at the end","cn":"拖把；墩布"},{"en":"a kitchen utensil (= a tool) for washing dishes, that has a short handle with soft material at one end","cn":"洗碗刷"}]}},"mounds":{"oxford":{"phon":"maʊnd","pos":"noun","senses":[{"en":"a large pile of earth or stones; a small hill","cn":"土墩；小丘；小山岗"},{"en":"a pile","cn":"一堆"}]}},"mosques":{"oxford":{"phon":"mɒsk","pos":"noun","senses":[{"en":"a building in which Muslims worship","cn":"清真寺"}]}},"mountaineers":{"oxford":{"phon":"ˌmaʊntəˈnɪə(r)","pos":"noun","senses":[{"en":"a person who climbs mountains as a sport","cn":"登山者；登山运动员"}]}},"monitoring":{"oxford":{"phon":"ˈmɒnɪtə(r)","pos":"noun","senses":[{"en":"a television screen used to show particular kinds of information; a screen that shows information from a computer","cn":"显示屏；监视器；（计算机）显示器"},{"en":"a piece of equipment used to check or record sth","cn":"监控器；监测器"}]}},"modeling":{"oxford":{"phon":"ˈmɒdəlɪŋ","pos":"noun","senses":[{"en":"the work of a fashion model （","cn":"时装）模特儿工作，模特儿表演"},{"en":"the activity of making models of objects （","cn":"实物）模型制造"}]}},"models":{"oxford":{"phon":"ˈmɒdl","pos":"noun","senses":[{"en":"a copy of sth, usually smaller than the original object （","cn":"依照实物按比例制成的）模型"},{"en":"a particular design or type of product","cn":"样式；设计；型"}]}},"moves":{"oxford":{"phon":"muːv","pos":"verb","senses":[{"en":"to change position or make sb/sth change position in a way that can be seen, heard or felt （","cn":"使）改变位置，移动"},{"en":"to change; to change sth","cn":"变化；改变；转变"}]}},"monks":{"oxford":{"phon":"mʌŋk","pos":"noun","senses":[{"en":"a member of a religious group of men who often live apart from other people in a monastery and who do not marry or have personal possessions","cn":"僧侣；修道士"}]}},"monitors":{"oxford":{"phon":"ˈmɒnɪtə(r)","pos":"noun","senses":[{"en":"a television screen used to show particular kinds of information; a screen that shows information from a computer","cn":"显示屏；监视器；（计算机）显示器"},{"en":"a piece of equipment used to check or record sth","cn":"监控器；监测器"}]}},"moments":{"oxford":{"phon":"ˈməʊmənt","pos":"noun","senses":[{"en":"a very short period of time","cn":"片刻；瞬间"},{"en":"an exact point in time","cn":"某个时刻；当时"}]}},"movements":{"oxford":{"phon":"ˈmuːvmənt","pos":"noun","senses":[{"en":"an act of moving the body or part of the body （","cn":"身体部位的）运动，转动，活动"},{"en":"an act of moving from one place to another or of moving sth from one place to another","cn":"移动；迁移；转移；活动"}]}},"mops":{"oxford":{"phon":"mɒp","pos":"noun","senses":[{"en":"a tool for washing floors that has a long handle with a bunch of thick strings or soft material at the end","cn":"拖把；墩布"},{"en":"a kitchen utensil (= a tool) for washing dishes, that has a short handle with soft material at one end","cn":"洗碗刷"}]}},"moths":{"oxford":{"phon":"mɒθ","pos":"noun","senses":[{"en":"a flying insect with a long thin body and four large wings, like a butterfly , but less brightly coloured. Moths fly mainly at night and are attracted to bright lights.","cn":"蛾；飞蛾"}]}},"mobilized":{"oxford":{"phon":"ˈməʊbəlaɪz","pos":"verb","senses":[{"en":"to work together in order to achieve a particular aim; to organize a group of people to do this","cn":"组织；鼓动；动员"},{"en":"to find and start to use sth that is needed for a particular purpose","cn":"调动；调用"}]}},"mothers":{"oxford":{"phon":"ˈmʌðə(r)","pos":"noun","senses":[{"en":"a female parent of a child or animal; a person who is acting as a mother to a child","cn":"母亲；妈妈"},{"en":"the title of a woman who is head of a convent (= a community of nuns ) （","cn":"对女修道院院长的尊称）"}]}},"mondays":{"oxford":{"phon":"ˈmʌndeɪ","pos":"noun","senses":[{"en":"the day of the week after Sunday and before Tuesday, the first day of the working week","cn":"星期一"}]}},"mountains":{"oxford":{"phon":"ˈmaʊntən","pos":"noun","senses":[{"en":"a very high hill, often with rocks near the top","cn":"高山；山岳"},{"en":"( informal ) a very large amount or number of sth","cn":"许多；大量"}]}},"months":{"oxford":{"phon":"mʌnθ","pos":"noun","senses":[{"en":"any of the twelve periods of time into which the year is divided, for example May or June","cn":"月；月份"},{"en":"a period of about 30 days, for example, 3 June to 3 July","cn":"约 30 天的时间；一个月的时间"}]}},"monuments":{"oxford":{"phon":"ˈmɒnjumənt","pos":"noun","senses":[{"en":"a building, column, statue, etc. built to remind people of a famous person or event","cn":"纪念碑（或馆、堂、像等）"},{"en":"a building that has special historical importance","cn":"历史遗迹；有历史价值的建筑"}]}},"monitored":{"oxford":{"phon":"ˈmɒnɪtə(r)","pos":"noun","senses":[{"en":"a television screen used to show particular kinds of information; a screen that shows information from a computer","cn":"显示屏；监视器；（计算机）显示器"},{"en":"a piece of equipment used to check or record sth","cn":"监控器；监测器"}]}},"moonlighting":{"oxford":{"phon":"ˈmuːnlaɪt","pos":"noun","senses":[{"en":"the light of the moon","cn":"月光"},{"en":"( informal ) to have a second job that you do secretly, usually without paying tax on the extra money that you earn （","cn":"暗中）兼职，从事第二职业"}]},"media":{"uk":"media/ldoce/hwd/bre/5/moonlight_n0205.mp3","us":"media/ldoce/hwd/ame/1/moonlight1.mp3"},"examples":[{"en":"She’s been moonlighting as a waitress in the evenings.","cn":""}]},"motives":{"oxford":{"phon":"ˈməʊtɪv","pos":"noun","senses":[{"en":"a reason for doing sth","cn":"动机；原因；目的"},{"en":"( technical","cn":"术语 ) causing movement or action 发动的；导致运动的"}]}},"mornings":{"oxford":{"phon":"ˈmɔːnɪŋ","pos":"noun","senses":[{"en":"the early part of the day from the time when people wake up until midday or before lunch","cn":"早晨；上午"},{"en":"the part of the day from midnight to midday","cn":"午夜至正午的时间"}]}},"moved":{"oxford":{"phon":"muːv","pos":"verb","senses":[{"en":"to change position or make sb/sth change position in a way that can be seen, heard or felt （","cn":"使）改变位置，移动"},{"en":"to change; to change sth","cn":"变化；改变；转变"}]}},"movies":{"oxford":{"phon":"ˈmuːvi","pos":"noun","senses":[{"en":"a series of moving pictures recorded with sound that tells a story, shown at the cinema/movie theater","cn":"电影"}]}},"mole":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"痣;痦子","en":"A mole is a natural dark spot or small dark lump on someone's skin."},{"pos":"N-COUNT 可数名词","cn":"鼹鼠","en":"A mole is a small animal with black fur that lives underground."},{"pos":"N-COUNT 可数名词","cn":"间谍;卧底;内奸","en":"A mole is a member of a government or other organization who gives secret information to the press or to a rival organization.","ex":{"en":"He had been recruited by the Russians as a mole and trained in Moscow.","cn":"他被俄国人征募为间谍，并在莫斯科接受了训练。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n 4 n 5 n ","senses":[{"en":"You may have never seen the fuzzy, pointy-nosed animal called a mole even if you know what a mole is, since it lives underground most of the time."}]},"collocations":{"phrases":["MOLE + VERB dig, burrow, tunnel 2 person","VERB + MOLE plant They suspected that a mole had been planted in the organization. 3 mark on the skin","ADJ. hairy","VERB + MOLE remove"]},"media":{"uk":"media/ldoce/hwd/bre/3/mole0205.mp3","us":"media/ldoce/hwd/ame/5/mole1.mp3"},"oxford":{"phon":"məʊl","pos":"noun","senses":[{"en":"a small animal with dark grey fur, that is almost blind and digs tunnels under the ground to live in","cn":"鼹鼠（视力极差，居住在挖掘的地道里）"},{"en":"a small dark brown mark on the skin, sometimes slightly higher than the skin around it","cn":"色素痣"},{"en":"a person who works within an organization and secretly passes important information to another organization or country","cn":"间谍；内奸","ex":{"en":"They suspected that a mole had been planted in the organization.","cn":"他们怀疑组织里被安插了内奸。"}},{"en":"a unit for measuring the amount of substance","cn":"摩尔（计量物质的量的单位）","lab":"chemistry"}]}},"molecule":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分子","en":"A molecule is the smallest amount of a chemical substance which can exist by itself.","ex":{"en":"...the hydrogen bonds between water molecules.","cn":"水分子间的氢键"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the smallest unit into which any substance can be divided without losing its own chemical nature, usually consisting of two or more atoms","cn":"分子"}]},"vocab":{"pos":"n","senses":[{"en":"A molecule , or the simplest structural unit of a substance that still keeps the properties of that substance, is a scientific word that gets used by the nonscientific, as in \"Every single molecule in my body wants that chocolate cake!\""}]},"collocations":{"phrases":["ADJ. complex | simple | stable | CO 2 , DNA, hydrogen, water, etc.","VERB + MOLECULE form","MOLECULE + VERB combine | be composed of sth, contain sth","PREP. in a/the ~ the number of atoms in a molecule | ~ in the molecules in the crystal"]},"media":{"uk":"media/ldoce/hwd/bre/f/molecule0205.mp3","us":"media/ldoce/hwd/ame/8/molecule.mp3"},"examples":[{"en":"A molecule of water consists of two atoms of hydrogen and one atom of oxygen.","cn":"水分子由两个氢原子和一个氧原子构成。"},{"en":"molecular structure/biology","cn":"分子结构/生物学"}],"oxford":{"phon":"ˈmɒlɪkjuːl","pos":"noun","senses":[{"en":"a group of atoms that forms the smallest unit that a substance can be divided into without a change in its chemical nature","cn":"分子","ex":{"en":"A molecule of water consists of two atoms of hydrogen and one atom of oxygen.","cn":"水分子由两个氢原子和一个氧原子构成。"}}]}},"mortal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"终有一死的;不能永生的","en":"If you refer to the fact that people are mortal, you mean that they have to die and cannot live for ever.","ex":{"en":"A man is deliberately designed to be mortal. He grows, he ages, and he dies.","cn":"人注定终有一死：长大、衰老，然后消亡。"}},{"pos":"N-COUNT 可数名词","cn":"凡人;肉眼凡胎;普通人","en":"You can describe someone as a mortal when you want to say that they are an ordinary person.","ex":{"en":"Tickets seem unobtainable to the ordinary mortal.","cn":"普通人好像根本买不到票。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极其严重的;致命的","en":"You can use mortal to show that something is very serious or may cause death.","ex":{"en":"The police were defending themselves and others against mortal danger","cn":"警察在保护自己和他人免遭致命危险。"}},{"pos":"ADJ 形容词","cn":"极度的;极大的","en":"You can use mortal to emphasize that a feeling is extremely great or severe.","ex":{"en":"When self-esteem is high, we lose our mortal fear of jealousy.","cn":"自信心很强时，我们不再对妒忌感到极度惧怕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a fatal accident, illness, or injury is one that causes death","cn":""},{"en":"something that is lethal can cause death - use this especially about weapons or substances","cn":""},{"en":"something such as a disease or poison that is deadly can cause death","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"You are a mortal because you are mortal . This means that you are an individual destined to die because you are susceptible to death."}]},"collocations":{"phrases":["ADJ. lesser, mere, ordinary I just assumed you were a mere mortal like the rest of us. a holiday resort that caters for royalty as well as f"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdemortal.mp3","us":"media/ldoce/hwd/ame/0/mortal1.mp3"},"examples":[{"en":"( humorous ) She can deal with complicated numbers in her head, but we lesser mortals need calculators!","cn":"她可以心算复杂的数字，而我们常人就需要计算器！"},{"en":"We lived in mortal dread of him discovering our secret.","cn":"因为害怕他发现我们的秘密，我们终日惶恐不安。"}],"oxford":{"phon":"ˈmɔːtl","pos":"adjective","senses":[{"en":"that cannot live forever and must die","cn":"不能永生的；终将死亡的","ex":{"en":"We are all mortal.","cn":"我们都总有一死。"}},{"en":"causing death or likely to cause death; very serious","cn":"导致死亡的；致命的；非常危急的","lab":"literary","ex":{"en":"a mortal blow/wound","cn":"致命的一击／伤口"}},{"en":"lasting until death","cn":"至死方休的；不共戴天的","g":"[only before noun]","lab":"formal","ex":{"en":"mortal enemies","cn":"不共戴天的敌人"}},{"en":"extreme","cn":"极端的；非常厉害的","g":"[only before noun]","lab":"formal","ex":{"en":"We lived in mortal dread of him discovering our secret.","cn":"因为害怕他发现我们的秘密，我们终日惶恐不安。"}},{"en":"a human, especially an ordinary person with little power or influence","cn":"人；凡人；普通人","lab":"humorous","ex":{"en":"old stories about gods and mortals","cn":"关于天神和凡人的古老传说"},"pos":"noun"}]}},"mouthful":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(饮料或食物)一口之量","en":"A mouthful of drink or food is the amount that you put or have in your mouth.","ex":{"en":"She gulped down a mouthful of coffee","cn":"她咽下一大口咖啡。"}},{"pos":"N-SING 单数名词","cn":"冗长而拗口的词（或短语）;难读的词（或短语）","en":"If you describe a long word or phrase as a mouthful, you mean that it is difficult to say.","ex":{"en":"It's called the Pan-Carib-bean Disaster Preparedness and Prevention Project, which is quite a mouthful.","cn":"它被称为 the Pan-Caribbean Disaster Preparedness and Prevention Project（泛加勒比备灾防灾项目），名称相当冗长拗口。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of food or drink that you put into your mouth at one time 〔","cn":"食物或饮料的〕一口﹐一满口"},{"en":"a long word or phrase that is difficult to say","cn":"冗长而拗口的词[短语]"},{"en":"to speak angrily to someone, often swearing at them","cn":"对某人一顿痛骂﹔咒骂某人"}]},"collocations":{"phrases":["ADJ. great, large | small","VERB + MOUTHFUL drink, eat, gulp (down), have, swallow, take She took a large mouthful of bread and started to read the letter. | chew | spi","PREP. between ~s He told the story between mouthfuls. | through a ~ She answered through a mouthful of cake. | ~ of a mouthful of coffee"]},"media":{"uk":"media/ldoce/hwd/bre/2/mouthful0205.mp3","us":"media/ldoce/hwd/ame/a/mouthful.mp3"},"examples":[{"en":"She took a mouthful of water.","cn":"她喝了一大口水。"},{"en":"Michael told his story between mouthfuls.","cn":"迈克尔边吃边讲他的故事。"}],"oxford":{"phon":"ˈmaʊθfʊl","pos":"noun","senses":[{"en":"an amount of food or drink that you put in your mouth at one time","cn":"一口，一满口（的量）","g":"[countable]","ex":{"en":"She took a mouthful of water.","cn":"她喝了一大口水。"}},{"en":"a word or a phrase that is long and complicated or difficult to pronounce","cn":"又长又拗口的词（或短语）","g":"[singular]","lab":"informal","ex":{"en":"My name’s Zacharias. You can call me Zach if it’s too much of a mouthful.","cn":"我的名字是撒迦利亚。如果太拗口的话，你可以叫我扎克。"}}]}},"motif":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(作为装饰的)图形，图式","en":"A motif is a design which is used as a decoration or as part of an artistic pattern.","ex":{"en":"...a rose motif.","cn":"玫瑰图案"}},{"pos":"N-COUNT 可数名词","cn":"主题;中心思想","en":"A motif is a theme or idea that is frequently repeated throughout a piece of literature or music.","ex":{"en":"The motif of these volumes is that 'solitude is the richness of the soul, loneliness is its poverty.'","cn":"这几卷的主题是“孤独是灵魂的财富，寂寞是灵魂的贫瘠”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a regularly repeated arrangement of shapes, colours, or lines on a surface","cn":""},{"en":"a pattern used for decorating something, especially cloth or paper","cn":""},{"en":"the coloured patterns and shapes on an animal’s fur, feathers, or skin","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The race car decor in your room, the refrain of a song, the idea or object that keeps popping up in a story — these are all motifs , reoccurring elements that move throughout and shape music, art and novels."}]},"collocations":{"phrases":["ADJ. central, dominant Alienation is a central motif in her novels. | recurring | simple The rug was decorated with a simple flower motif. |","VERB + MOTIF be decorated with, have"]},"media":{"uk":"media/ldoce/hwd/bre/2/motif0205.mp3","us":"media/ldoce/hwd/ame/e/motif.mp3"},"examples":[{"en":"wallpaper with a flower motif","cn":"有鲜花图案的墙纸"},{"en":"The theme of creation is a recurrent motif in Celtic mythology.","cn":"天地万物的创造是凯尔特神话中反复出现的主题。"}],"oxford":{"phon":"məʊˈtiːf","pos":"noun","senses":[{"en":"a design or a pattern used as a decoration","cn":"装饰图案；装饰图形","ex":{"en":"wallpaper with a flower motif","cn":"有鲜花图案的墙纸"}},{"en":"a subject, an idea or a phrase that is repeated and developed in a work of literature or a piece of music","cn":"（文学作品或音乐的）主题，主旨，动机","ex":{"en":"Alienation is a central motif in her novels.","cn":"疏离是她小说的中心主题。"}}]}},"motel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(供驾车旅客住宿和停车的)汽车旅馆","en":"A motel is a hotel intended for people who are travelling by car."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building where people pay to stay and eat meals","cn":""},{"en":"a hotel for people travelling by car, usually with a place for the car near each room","cn":""},{"en":"a small hotel, especially an old one in the countryside. Also used in the names of some big modern hotels","cn":""}]},"collocations":{"phrases":["VERB + MOTEL check into/out of | stay at/in","PREP. at/in a/the ~ We spent a night at a motel on the way."]},"media":{"uk":"media/ldoce/hwd/bre/c/motel0205.mp3","us":"media/ldoce/hwd/ame/8/motel.mp3"},"oxford":{"phon":"məʊˈtel","pos":"noun","senses":[{"en":"a hotel for people who are travelling by car, with space for parking cars near the rooms","cn":"汽车旅馆（附有停车设施）","ex":{"en":"Harry was lying on his bed in his motel room.","cn":"哈利躺在汽车旅馆房间的床上。"}}]}},"mouthpiece":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（电话的）话筒，送话器","en":"The mouthpiece of a telephone is the part that you speak into.","ex":{"en":"He shouted into the mouthpiece.","cn":"他对着电话话筒大叫。"}},{"pos":"N-COUNT 可数名词","cn":"(乐器的)吹口;(其他装置的)衔口，嘴儿","en":"The mouthpiece of a musical instrument or other device is the part that you put into your mouth.","ex":{"en":"He showed him how to blow into the ivory mouthpiece.","cn":"他给他演示如何吹奏象牙吹口乐器。"}},{"pos":"N-COUNT 可数名词","cn":"发言人;代言人;喉舌","en":"The mouthpiece of an organization or person is someone who informs other people of the opinions and policies of that organization or person.","ex":{"en":"Their mouthpiece is the vice-president","cn":"他们的副总裁是他们的代言人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has been chosen to represent an organization or country","cn":""},{"en":"a person who officially gives the opinions of an organization, company, government etc","cn":""},{"en":"a word meaning spokesman or spokeswoman , used especially when you do not want to say whether the person is a man or a woman","cn":""}]},"collocations":{"phrases":["ADJ. phone/telephone","VERB + MOUTHPIECE cover (up), put your hand over He put his hand over the mouthpiece and called his wife to the phone. 2 sb/sth that informs","ADJ. official, political","VERB + MOUTHPIECE act as, be","PREP. ~ for/of The media is controlled by the state and acts as a mouthpiece for the ruling party."]},"media":{"img":["media/ldoce/img/bugle.jpg"],"uk":"media/ldoce/hwd/bre/f/mouthpiece0205.mp3","us":"media/ldoce/hwd/ame/9/mouthpiece.mp3"},"examples":[{"en":"The newspaper has become the official mouthpiece of the opposition party.","cn":"这份报纸已经成为反对党的官方喉舌。"},{"en":"The Press Secretary serves as the President's mouthpiece.","cn":"新闻部长担任总统的代言人。"}],"oxford":{"phon":"ˈmaʊθpiːs","pos":"noun","senses":[{"en":"the part of a phone or radio device that is next to your mouth when you speak","cn":"话筒；对讲机","ex":{"en":"I could see the referee talking into his mouthpiece.","cn":"我可以看到裁判用他的话筒说话。"}},{"en":"the part of a musical instrument that you place between your lips","cn":"（乐器的）吹口"},{"en":"a person, newspaper, etc. that speaks to represent another person or group of people","cn":"喉舌；传声筒；代言人","lab":"often disapproving","ex":{"en":"The newspaper has become the official mouthpiece of the opposition party.","cn":"这份报纸已经成为反对党的官方喉舌。"}}]}},"moan":{"collins":{"senses":[{"pos":"VERB 动词","cn":"呻吟;呜咽","en":"If you moan, you make a low sound, usually because you are unhappy or in pain.","ex":{"en":"Tony moaned in his sleep and then turned over on his side","cn":"托尼在睡梦中发出呻吟声，然后翻了个身。"}},{"pos":"VERB 动词","cn":"抱怨;发牢骚","en":"To moan means to complain or speak in a way which shows that you are very unhappy.","ex":{"en":"I used to moan if I didn't get at least six hours' sleep at night.","cn":"过去如果晚上的睡眠时间不足6小时的话，我就会抱怨。"}},{"pos":"N-COUNT 可数名词","cn":"抱怨","en":"A moan is a complaint.","ex":{"en":"They have been listening to people's gripes, moans and praise.","cn":"他们一直在倾听人们的牢骚、抱怨和表扬。"}},{"pos":"PHRASE 短语","cn":"抱怨；发牢骚","en":"If you have a moan, you complain about something.","ex":{"en":"You can go see him and have a good old moan.","cn":"你可以去看看他，好好地诉诉苦。"}},{"pos":"N-COUNT 可数名词","cn":"低沉的声音","en":"A moan is a low noise.","ex":{"en":"...the occasional moan of the wind round the corners of the house.","cn":"风刮过屋角时间或发出的呼啸声"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you are annoyed, unhappy, or not satisfied about something or someone","cn":""},{"en":"to formally complain about something to someone in authority","cn":""},{"en":"to complain about something that you think is wrong, especially publicly","cn":""}]},"collocations":{"phrases":["ADV. loudly | quietly, softly","PREP. in He moaned in despair. | with She was still conscious and was moaning loudly with pain. 2 complain","ADV. on They kept moaning on about their illnesses.","PREP. about What are you moaning about now? | at My parents moan at me if I'm home late. | to She's always moaning to me that she hasn't got","PHRASES moan and groan The unwilling children climbed into the bus, moaning and groaning."]},"media":{"uk":"media/ldoce/hwd/bre/9/moan_v0205.mp3","us":"media/ldoce/hwd/ame/3/moan1.mp3"},"examples":[{"en":"‘I might never see you again,’ she moaned.","cn":"她呻吟着说：“我可能再也见不到你了。”"},{"en":"They're always moaning and groaning about how much they have to do.","cn":"他们总是牢骚满腹，抱怨有很多事要做。"}],"oxford":{"phon":"məʊn","pos":"verb","senses":[{"en":"to make a long deep sound, usually because you are unhappy or suffering or are experiencing sexual pleasure","cn":"呻吟","g":"[intransitive, transitive]","ex":{"en":"The injured man was lying on the ground, moaning.","cn":"受伤的人躺在地上呻吟着。"}},{"en":"to complain about something in a way that other people find annoying","cn":"抱怨","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"What are you moaning on about now?","cn":"你在抱怨什么呢？"}},{"en":"to make a long deep sound","cn":"呼啸；发出萧萧声","g":"[intransitive]","lab":"literary","ex":{"en":"The wind was moaning through the trees.","cn":"风穿林木声萧萧。"}},{"en":"a long deep sound, usually made because you are unhappy or suffering or are experiencing sexual pleasure","cn":"呻吟声","g":"[countable]","ex":{"en":"a low moan of despair/anguish","cn":"绝望的／痛苦的低沉呻吟"},"pos":"noun"},{"en":"a complaint about something","cn":"抱怨","g":"[countable]","lab":"informal","ex":{"en":"We had a good moan about work.","cn":"我们对工作大大地抱怨了一番。"},"pos":"noun"},{"en":"a long deep sound, especially the sound that is made by the wind","cn":"（尤指风的）呼啸声，萧萧声","g":"[singular]","lab":"literary","ex":{"en":"She lay listening to the moan of the wind in the trees behind the house.","cn":"她躺着，听着屋后树林里风的呻吟声。"},"pos":"noun"}]}},"monarchy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"君主政体;君主制","en":"A monarchy is a system in which a country has a monarch.","ex":{"en":"In a few years we may no longer have a monarchy.","cn":"几年后君主政体可能将不复存在。"}},{"pos":"N-COUNT 可数名词","cn":"君主国;君主制国家","en":"A monarchy is a country that has a monarch."},{"pos":"N-COUNT 可数名词","cn":"皇室;王族","en":"The monarchy is used to refer to the monarch and his or her family.","ex":{"en":"The monarchy has to create a balance between its public and private lives.","cn":"皇室成员不得不在公众生活和私生活之间建立起一种平衡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the group of people who govern a country or the system they use to govern it","cn":""},{"en":"the government of a country, especially one such as the US, which is led by a president","cn":""},{"en":"a government, especially one that was not elected fairly or that you disapprove of","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A monarchy is a country that is ruled by a monarch , and monarchy is this system or form of government."}]},"collocations":{"phrases":["ADJ. strong, weak | absolute | constitutional | elective, hereditary","VERB + MONARCHY establish, set up | have The country still has a strong monarchy. | abolish the arguments for abolishing the monarchy | over"]},"media":{"uk":"media/ldoce/hwd/bre/f/monarchy0205.mp3","us":"media/ldoce/hwd/ame/a/monarchy.mp3"},"examples":[{"en":"There are several constitutional monarchies in Europe.","cn":"欧洲有若干个君主立宪国。"},{"en":"plans to abolish the monarchy","cn":"废除君主政体的计划"}],"oxford":{"phon":"ˈmɒnəki","pos":"noun","senses":[{"en":"a system of government by a king or a queen","cn":"君主制；君主政体","g":"[singular, uncountable]","lab":"especially North American English","ex":{"en":"plans to abolish the monarchy","cn":"废除君主政体的计划"}},{"en":"a country that is ruled by a king or a queen","cn":"君主国","g":"[countable]","ex":{"en":"There are several constitutional monarchies in Europe.","cn":"欧洲有若干个君主立宪国。"}},{"en":"the king or queen of a country and their family","cn":"君主及其家庭成员","g":"[singular]"}]}},"mortgage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"房屋抵押贷款","en":"A mortgage is a loan of money which you get from a bank or building society in order to buy a house.","ex":{"en":"...an increase in mortgage rates.","cn":"房屋抵押贷款利率的提高"}},{"pos":"VERB 动词","cn":"抵押(房屋、土地)借款","en":"If you mortgage your house or land, you use it as a guarantee to a company in order to borrow money from them.","ex":{"en":"They had to mortgage their home to pay the bills.","cn":"他们不得不抵押房屋借贷来支付这些款项。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that is borrowed, especially from a bank or company, which you agree to pay back by the end of a period of time","cn":""},{"en":"a large amount of money that someone borrows from a bank or company to buy a house","cn":""},{"en":"money that you pay for borrowing money, especially that you pay every year or every month at a fixed rate","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A mortgage is a loan in which the lender may use your property as payment if you don't pay back the loan. Offer your friend a mortgage for the $20 he wants . . . with his bike as security."}]},"collocations":{"phrases":["ADJ. big, huge | small | cheap Banks often offer their employees cheap mortgages. | endowment, fixed-rate, repayment","VERB + MORTGAGE have We've got a big mortgage. | get, raise (formal) , take out They were having trouble getting a mortgage. We'll have to t","MORTGAGE + NOUN (interest) payment, repayment They were struggling to keep up with their mortgage repayments. | rate a rise in mortgage rate","PREP. ~ of a mortgage of &pound; 80,000 | ~ on I couldn't get a mortgage on the property."]},"media":{"uk":"media/ldoce/hwd/bre/5/mortgage_v0205.mp3","us":"media/ldoce/hwd/ame/f/mortgage1.mp3"},"examples":[{"en":"He had to mortgage his house to pay his legal costs.","cn":"他不得不把房子抵押出去来付诉讼费。"},{"en":"to apply for/take out/pay off a mortgage","cn":"申请/取得/还清抵押贷款"}],"oxford":{"phon":"ˈmɔːɡɪdʒ","pos":"noun","senses":[{"en":"a legal agreement by which a bank or similar organization lends you money to buy a house, etc., and you pay the money back over a particular number of years; the sum of money that you borrow","cn":"按揭（由银行等提供房产等的抵押借款）；按揭贷款","lab":"especially North American English","ex":{"en":"to apply for/take out/pay off a mortgage","cn":"申请／取得／还清抵押贷款"}},{"en":"to give a bank, etc. the legal right to own your house, land, etc. if you do not pay the money back that you have borrowed from the bank to buy the house or land","cn":"（向银行等）抵押（房地产）","ex":{"en":"He had to mortgage his house to pay his legal costs.","cn":"他不得不把房子抵押出去来付诉讼费。"},"pos":"verb"}]}},"motto":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"箴言;格言;座右铭","en":"A motto is a short sentence or phrase that expresses a rule for sensible behaviour, especially a way of behaving in a particular situation.","ex":{"en":"Our motto is 'Plan for the worst and hope for the best'.","cn":"我们的格言是“做最坏的打算，抱最大的希望”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of words that have a particular meaning when used together, or which someone uses on a particular occasion","cn":""},{"en":"a fixed phrase which is used in a language and has a particular meaning","cn":""},{"en":"a group of words that has a special meaning which you cannot guess from the meanings of each separate word","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A motto is a slogan or favorite saying, like \"When life hands you lemons, make lemonade.\""}]},"collocations":{"phrases":["ADJ. club, family, school, etc.","VERB + MOTTO have Surfers have a motto?&lsquo;Life's a beach and then you die&rsquo;. | coin, have sth as, use sth as He was the first to co","PREP. ~ for a good motto for gardeners"]},"media":{"uk":"media/ldoce/hwd/bre/f/motto0205.mp3","us":"media/ldoce/hwd/ame/1/motto.mp3"},"examples":[{"en":"The school's motto is: ‘Duty, Honour, Country’.","cn":"这所学校的校训是：尽责、知耻、爱国。"},{"en":"‘Live and let live.’ That's my motto. “","cn":"待人宽如待己”，这是我的座右铭。"}],"oxford":{"phon":"ˈmɒtəʊ","pos":"noun","senses":[{"en":"a short sentence or phrase that expresses the aims and beliefs of a person, a group, an institution, etc. and is used as a rule of behaviour","cn":"座右铭；格言；箴言","ex":{"en":"The school's motto is: ‘Duty, Honour, Country’.","cn":"这所学校的校训是：尽责、知耻、爱国。"}}]}},"mosquito":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蚊子","en":"Mosquitos are small flying insects which bite people and animals in order to suck their blood."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small flying insect that sucks the blood of people and animals, sometimes spreading the disease malaria","cn":"蚊子"}]},"collocations":{"phrases":["QUANT. swarm","VERB + MOSQUITO swat He swatted the mosquito with a newspaper.","MOSQUITO + VERB fly | buzz, hum, whine | bite | carry sth, spread sth This strain of mosquito carries malaria and yellow fever.","MOSQUITO + NOUN bite I was awake all night scratching my mosquito bites. | larva fish that feed on mosquito larvae | net/netting | repellent","PHRASES a strain of mosquito"]},"media":{"img":["media/ldoce/img/mosquito.jpg","media/thumb/mosquito.jpg"],"uk":"media/ldoce/hwd/bre/5/mosquito0205.mp3","us":"media/ldoce/hwd/ame/a/mosquito.mp3"},"examples":[{"en":"a mosquito bite","cn":"蚊子叮伤"}],"oxford":{"phon":"məˈskiːtəʊ","pos":"noun","senses":[{"en":"a flying insect that bites humans and animals and drinks their blood. One type of mosquito can spread the disease malaria.","cn":"蚊子","ex":{"en":"I was awake all night scratching my mosquito bites.","cn":"我一晚上都没睡着，一个劲地挠蚊子叮咬的地方。"}}]}},"monsoon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(南亚地区的)季风季节，雨季","en":"The monsoon is the season in Southern Asia when there is a lot of very heavy rain.","ex":{"en":"...the end of the monsoon.","cn":"雨季的尾声"}},{"pos":"N-PLURAL 复数名词","cn":"(雨季的)季风雨，降雨","en":"Monsoon rains are sometimes referred to as the monsoons .","ex":{"en":"In Ban-gladesh, the monsoons have started.","cn":"在孟加拉，雨季已经开始了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"water that falls in small drops from clouds in the sky","cn":""},{"en":"light rain with very small drops of water","cn":""},{"en":"a short period of rain that can be heavy or light","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Monsoon is the term for the wind that carries heavy rains to southern Asia, and the rains themselves. During a monsoon , people wait indoors for it to stop."}]},"collocations":{"phrases":["ADJ. east, west, etc.","MONSOON + VERB set in The south-west monsoon sets in during April.","MONSOON + NOUN rains, season","PREP. during a/the ~ Travelling is much more difficult during the monsoon."]},"media":{"uk":"media/ldoce/hwd/bre/2/monsoon0205.mp3","us":"media/ldoce/hwd/ame/b/monsoon.mp3"},"oxford":{"phon":"ˌmɒnˈsuːn","pos":"noun","senses":[{"en":"a period of heavy rain in summer in South Asia; the rain that falls during this period","cn":"（南亚地区的）雨季，雨季的降雨","ex":{"en":"Travelling is much more difficult during the monsoon.","cn":"在雨季出行要难得多。"}},{"en":"a wind in South Asia that blows from the south-west in summer, bringing rain, and the north-east in winter","cn":"季风，季节风（盛行于南亚地区，夏季刮西南风，带来雨水，冬季刮东北风）","ex":{"en":"The monsoon blew relentlessly into our faces.","cn":"季风无情地吹打着我们的脸。"}}]}},"mongolia":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in north central Asia between Russia and China. Population 3,226,516 (2014). Capital: Ulaanbaatar (formerly Ulan Bator). Mongolia is a large country but has a small population because it includes a large area of desert and open plains. The country is","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/p028-000008421.mp3","us":"media/ldoce/hwd/ame/a/p028-000008421.mp3"},"oxford":{"phon":"mɒŋˈɡəʊliə","pos":"noun","senses":[{"en":"a country in East Asia","cn":"蒙古（东亚国家）"}]}},"morality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"道德；道义;伦理","en":"Morality is the belief that some behaviour is right and acceptable and that other behaviour is wrong.","ex":{"en":"...standards of morality and justice in society.","cn":"社会道德和正义的标准"}},{"pos":"N-COUNT 可数名词","cn":"道义准则;道德规范;伦理学","en":"A morality is a system of principles and values concerning people's behaviour, which is generally accepted by a society or by a particular group of people.","ex":{"en":"...a morality that is sexist.","cn":"存在性别歧视的道德规范"}},{"pos":"N-UNCOUNT 不可数名词","cn":"道德性；道德","en":"The morality of something is how right or acceptable it is.","ex":{"en":"...the arguments about the morality of blood sports.","cn":"有关猎杀动物行为是否道德的争论"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all of the basic ideas that a person or group of people has about what is morally good and right","cn":""},{"en":"ideas about what is right and wrong, and what is acceptable behaviour – used when talking about whether it is right to do a particular thing, or when talking about moral standards generally","cn":""},{"en":"moral rules for deciding what is right and wrong – often used about this as a subject that people study and discuss","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Morality is a concern with what’s right or wrong. Your sense of morality prevents you from cheating on your school exams, on your taxes, or on your spouse."}]},"collocations":{"phrases":["ADJ. conventional, traditional | personal, private | public, social | political | sexual | Christian","VERB + MORALITY preserve, protect, strengthen efforts to strengthen traditional morality","PHRASES standards of morality She criticized politicians' standards of personal morality."]},"media":{"uk":"media/ldoce/hwd/bre/1/morality0205.mp3","us":"media/ldoce/hwd/ame/6/morality.mp3"},"examples":[{"en":"a debate on the morality of abortion","cn":"有关堕胎是否道德的辩论"},{"en":"Standards of morality seem to be dropping.","cn":"道德标准似乎在下降。"}],"oxford":{"phon":"məˈræləti","pos":"noun","senses":[{"en":"principles relating to right and wrong or good and bad behaviour","cn":"道德；道德准则；道义","g":"[uncountable]","ex":{"en":"matters of public/private morality","cn":"公众／个人道德问题"}},{"en":"the degree to which something is right or wrong, good or bad, etc. according to moral principles","cn":"合乎道德的程度","g":"[uncountable]","ex":{"en":"There is a continuing debate on the morality of abortion.","cn":"关于堕胎是否道德的辩论持续不休。"}},{"en":"a system of moral principles followed by a particular group of people","cn":"道德规范；道德体系","g":"[uncountable, countable]"}]}},"mooring":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"泊地;停泊区","en":"A mooring is a place where a boat can be tied so that it cannot move away, or the object it is tied to.","ex":{"en":"Free moorings will be available.","cn":"将会有免费停泊区。"}},{"pos":"N-PLURAL 复数名词","cn":"(绳、链等)系船用具，系泊装置","en":"Moorings are the ropes, chains, and other objects used to moor a boat.","ex":{"en":"He cut the engine and grabbed the mooring lines","cn":"他关掉发动机，抓住系船的绳子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where ships can be loaded and unloaded","cn":""},{"en":"an area of water next to the land which is protected by walls so the water is calm, and is a place where ships can stay when they are not sailing","cn":""},{"en":"a place in a port where ships are loaded, unloaded, or repaired","cn":""}]},"collocations":{"phrases":["VERB + MOORING be torn from, break/come loose from, slip During the storm several of our boats were torn from their moorings. The crowds che","MOORING + NOUN post, rope"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdemooring.mp3","us":"media/ldoce/hwd/ame/b/laadmooring.mp3"},"examples":[{"en":"The boat slipped its moorings and drifted out to sea.","cn":"船的系泊绳索滑落，船漂向大海。"},{"en":"to find a mooring","cn":"找一个停泊地"}],"oxford":{"phon":"ˈmɔːrɪŋ","pos":"noun","senses":[{"en":"the ropes, chains, etc. by which a ship or boat is moored","cn":"系泊用具","g":"[plural]","ex":{"en":"The boat slipped its moorings and drifted out to sea.","cn":"船的系泊绳索滑落，船漂向大海。"}},{"en":"the place where a ship or boat is moored","cn":"停泊处；系泊区","g":"[countable]","ex":{"en":"private moorings","cn":"私人停泊区"}}]}},"module":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大学课程的)单元，模块","en":"A module is one of the separate parts of a course taught at a college or university.","ex":{"en":"These courses cover a twelve-week period and are organised into three four-week modules.","cn":"这些课程要上12周，分为3个单元，每单元4周。"}},{"pos":"N-COUNT 可数名词","cn":"(航天器的)分离舱","en":"A module is a part of a spacecraft which can operate by itself, often away from the rest of the spacecraft.","ex":{"en":"A rescue plan could be achieved by sending an unmanned module to the space station.","cn":"可以通过向太空站发射无人太空舱来实现救援计划。"}},{"pos":"N-COUNT 可数名词","cn":"（建筑物中的）构件，组件，模块","en":"A module is one of a set of parts from which some buildings are made. Each module is made separately, and the completed modules are then joined together to form the building."},{"pos":"N-COUNT 可数名词","cn":"(机器的)组件，部件;(尤指计算机的)模块，程序块","en":"A module is a part of a machine, especially a computer, which performs a particular function."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the separate units that a course of study has been divided into. Usually students choose a number of modules to study","cn":"单元〔课程学习单位〕"},{"en":"one of several parts of a piece of computer software that does a particular job 〔","cn":"计算机软件的〕模块﹐功能块﹐程序块"},{"en":"a part of a spacecraft that can be separated from the main part and used for a particular purpose 〔","cn":"航天器的〕分离舱"}]},"vocab":{"pos":"n","senses":[{"en":"A module is an individual part that combines with other components to make different things. You might have one module that's a cube, and another that's a slab of wood. Two cubes and a slab could make an end table."}]},"collocations":{"phrases":["ADJ. individual | compulsory, optional","VERB + MODULE do, study I'm doing two optional modules. | complete | divide sth into The course material is divided into four modules."]},"media":{"uk":"media/ldoce/hwd/bre/0/module0205.mp3","us":"media/ldoce/hwd/ame/4/module.mp3"},"examples":[{"en":"The course consists of ten core modules and five optional modules.","cn":"这门课程包括十个必修单元和五个选修单元。"},{"en":"the lunar module","cn":"登月舱"}],"oxford":{"phon":"ˈmɒdjuːl","pos":"noun","senses":[{"en":"a unit that can form part of a course of study, especially at a college or university in the UK","cn":"单元，模块（尤指英国大学课程的一部分）","ex":{"en":"The course consists of ten core modules and five optional modules.","cn":"这门课程包括十个必修单元和五个选修单元。"}},{"en":"a unit of a computer system or program that has a particular function","cn":"模块；功能块；程序块","lab":"computing","ex":{"en":"You can buy memory modules to increase storage capacity.","cn":"可以购买存贮模块以提高存贮容量。"}},{"en":"one of a set of separate parts or units that can be joined together to make a machine, a piece of furniture, a building, etc.","cn":"组件；模块；配件","ex":{"en":"Ships are now built in modules rather than built in a whole from the base up.","cn":"现在造船是先做出组件，而不是从船底开始整艘建起来。"}},{"en":"a unit of a spacecraft that can function independently of the main part","cn":"（航天器上独立的）舱","ex":{"en":"Photographs were taken from a lunar module","cn":"照片是从登月舱拍摄的。"}}]}},"momentum":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"势头;冲劲;动力","en":"If a process or movement gains momentum, it keeps developing or happening more quickly and keeps becoming less likely to stop.","ex":{"en":"This campaign is really gaining momentum","cn":"该运动的势头越来越猛。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(物理学中的)动量，冲量","en":"In physics, momentum is the mass of a moving object multiplied by its speed in a particular direction."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make something happen more quickly","cn":""},{"en":"if a vehicle, especially a large vehicle picks up speed or gathers speed , it starts to gradually move faster","cn":""},{"en":"if a vehicle or driver accelerates , they go faster, especially suddenly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Momentum is generally used to mean increasing forward motion. A boulder rolling down a hill gains momentum. So does a great idea, a team on a winning streak, or the economy."}]},"collocations":{"phrases":["ADJ. considerable, great, irresistible | initial | fresh She gave fresh momentum to the campaign.","VERB + MOMENTUM have The campaign for change now has considerable momentum. | build up, gain, gather, increase The car gathered momentum as ","MOMENTUM + VERB build up, increase | go Their momentum has gone, and they feel they cannot fight any longer.","PREP. ~ for keeping up the momentum for growth | ~ towards the irresistible momentum towards reunification of the two countries","PHRASES keep the momentum going We have to keep the momentum of our sales operation going."]},"media":{"uk":"media/ldoce/hwd/bre/e/momentum0205.mp3","us":"media/ldoce/hwd/ame/1/momentum.mp3"},"examples":[{"en":"They began to lose momentum in the second half of the game.","cn":"在比赛的下半场，他们的势头就逐渐减弱。"},{"en":"The fight for his release gathers momentum each day.","cn":"争取使他获释的斗争声势日益加强。"}],"oxford":{"phon":"məˈmentəm","pos":"noun","senses":[{"en":"the ability to keep increasing or developing","cn":"推进力；动力；势头","ex":{"en":"The fight for his release gathers momentum each day.","cn":"争取使他获释的斗争声势日益加强。"}},{"en":"a force that is gained by movement","cn":"冲力","ex":{"en":"The vehicle gained momentum as the road dipped.","cn":"那辆车顺着坡越跑冲力越大。"}},{"en":"the quantity of movement of a moving object, measured as its mass multiplied by its speed","cn":"动量","lab":"specialist"}]}},"monarch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"君主;帝王;女王;女皇","en":"The monarch of a country is the king, queen, emperor, or empress."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the male ruler of a country, who comes from a royal family","cn":""},{"en":"a woman who rules a country because she is from a royal family, or the wife of a king","cn":""},{"en":"a king or queen","cn":"君主﹔国王﹔女王"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you think the Queen of England is just the coolest thing ever, then you like monarchs : hereditary rulers of countries usually known as King or Queen."}]},"collocations":{"phrases":["ADJ. reigning | absolute | constitutional","MONARCH + VERB reign, rule","PHRASES the power of the monarch a new law which limited the power of the monarch"]},"media":{"uk":"media/ldoce/hwd/bre/8/monarch0205.mp3","us":"media/ldoce/hwd/ame/e/monarch.mp3"},"oxford":{"phon":"ˈmɒnək","pos":"noun","senses":[{"en":"a person who rules a country, for example a king or a queen","cn":"君主；帝王","ex":{"en":"a new law which limited the power of the monarch","cn":"限制君主权力的新法律"}}]}},"moist":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"湿润的;潮湿的","en":"Something that is moist is slightly wet.","ex":{"en":"Wipe off any excess make-up with a clean, moist cotton flannel","cn":"用干净的湿绒布擦去多余的化妆品。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"slightly wet","cn":""},{"en":"slightly wet, especially when this is pleasant or how something should be","cn":""},{"en":"slightly wet and sticky, in an unpleasant way – used especially about someone’s skin","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look Her skin felt moist and feverish. | become, grow Beth's dark eyes grew moist as she kissed her son. | remain | keep sth","ADV. very | reasonably, slightly","PREP. with His fingers were becoming moist with sweat."]},"media":{"uk":"media/ldoce/hwd/bre/7/moist0205.mp3","us":"media/ldoce/hwd/ame/8/moist.mp3"},"examples":[{"en":"Water the plants regularly to keep the soil moist.","cn":"定时浇灌植物以保持土壤湿润。"},{"en":"Her eyes were moist (= with tears).","cn":"她眼含泪水。"}],"oxford":{"phon":"mɔɪst","pos":"adjective","senses":[{"en":"slightly wet","cn":"微湿的；湿润的","ex":{"en":"The warm moist air is perfect for growing fruit trees.","cn":"温暖湿润的空气最适于果树生长。"}}]}},"moonlight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"月光;月色","en":"Moonlight is the light that comes from the moon at night.","ex":{"en":"They walked along the road in the moonlight","cn":"他们在月光下沿路散步。"}},{"pos":"VERB 动词","cn":"兼职,从事第二职业(尤指不为专职工作的老板和税收部门所知)","en":"If someone moonlights, they have a second job in addition to their main job, often without informing their main employers or the tax office.","ex":{"en":"...an engineer who was moonlighting as a taxi driver","cn":"兼职开出租车的工程师"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this to say that there is natural daylight, so that you can see easily enough to do something","cn":""},{"en":"the natural light of day","cn":""},{"en":"the light from the sun","cn":""}]},"collocations":{"phrases":["ADJ. bright, clear | faint, pale","QUANT. shaft a single shaft of moonlight","VERB + MOONLIGHT be bathed in, gleam in, glint in, shine in The fields were bathed in bright moonlight that night. His helmet glinted in the","MOONLIGHT + VERB filter, shine, stream the faint moonlight filtering through the stained glass windows","PREP. by ~ The castle looks fantastic by moonlight. | in the ~ The leaves were silver in the moonlight."]},"media":{"uk":"media/ldoce/hwd/bre/5/moonlight_n0205.mp3","us":"media/ldoce/hwd/ame/1/moonlight1.mp3"},"examples":[{"en":"to go for a walk by moonlight/in the moonlight","cn":"在月光下散步"},{"en":"The water looked silver in the moonlight.","cn":"月光下﹐水面一片银白色。"}],"oxford":{"phon":"ˈmuːnlaɪt","pos":"noun","senses":[{"en":"the light of the moon","cn":"月光","ex":{"en":"to go for a walk by moonlight/in the moonlight","cn":"在月光下散步"}},{"en":"to have a second job that you do secretly, without telling your main employer","cn":"（暗中）兼职，从事第二职业","ex":{"en":"He spent years moonlighting as a cab driver.","cn":"他多年来都在私下里兼职开出租车。"},"pos":"verb"}]}},"monopoly":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"垄断;专营服务","en":"If a company, person, or state has a monopoly on something such as an industry, they have complete control over it, so that it is impossible for others to become involved in it.","ex":{"en":"...Russian moves to end a state monopoly on land ownership.","cn":"俄国人采取的终止国家垄断土地所有权的措施"}},{"pos":"N-COUNT 可数名词","cn":"垄断企业;专卖者","en":"A monopoly is a company which is the only one providing a particular product or service.","ex":{"en":"...a state-owned monopoly.","cn":"国有垄断企业"}},{"pos":"N-SING 单数名词","cn":"独有;独具","en":"If you say that someone does not have a monopoly on something, you mean that they are not the only person who has that thing.","ex":{"en":"Women do not have a monopoly on feelings of betrayal.","cn":"被出卖的感觉并非只有女性才有。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be the most powerful or important person or thing in a situation and therefore able to control it completely","cn":""},{"en":"to completely control an activity, situation etc and unfairly prevent other people or organizations from having any control over it at all","cn":""},{"en":"a situation in which one person or organization unfairly has complete control","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A monopoly is the exclusive ownership or control of something. If your sister claims a monopoly over the television during the Tom Cruise movie marathon, you would be wise not to touch that remote."}]},"collocations":{"phrases":["ADJ. effective, near, virtual | absolute, total | government, state | domestic, local, national","VERB + MONOPOLY enjoy, exercise, have, hold The company has a virtual monopoly in world markets. | create, establish, gain, get, secure, set","MONOPOLY + NOUN position The company was able to exploit its monopoly position.","PREP. ~ in creating a monopoly in the export of wool | ~ of One company holds a monopoly of the raw materials. | ~ on The company lost its m","ADJ. giant, huge, powerful | public, state, state-controlled, state-owned the privatization of state-owned monopolies such as the gas and el"]},"media":{"uk":"media/ldoce/hwd/bre/d/monopoly0205.mp3","us":"media/ldoce/hwd/ame/e/monopoly1.mp3"},"examples":[{"en":"Electricity, gas and water were considered to be natural monopolies.","cn":"电、煤气和水垄断经营过去被认为是理所当然的。"},{"en":"In the past central government had a monopoly on television broadcasting.","cn":"过去，中央政府对电视节目播放实行垄断。"}],"oxford":{"phon":"məˈnɒpəli","pos":"noun","senses":[{"en":"the complete control of trade in particular goods or the supply of a particular service; a type of goods or a service that is controlled in this way","cn":"垄断；专营服务；被垄断的商品（或服务）","lab":"business","ex":{"en":"In the past central government had a monopoly on television broadcasting.","cn":"过去，中央政府对电视节目播放实行垄断。"}},{"en":"the complete control, possession or use of something; a thing that belongs only to one person or group and that other people cannot share","cn":"独占；专利；专利品","g":"[usually singular]","ex":{"en":"Managers do not have a monopoly on stress.","cn":"并不只是经营管理者有压力。"}},{"en":"a board game in which players have to pretend to buy and sell land and houses, using pieces of paper that look like money","cn":"地产大亨，“大富翁”（一种桌面游戏，玩家以玩具钞票买卖地产和房产）"}]}},"motive":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(行动的)动机，缘由","en":"Your motive for doing something is your reason for doing it.","ex":{"en":"Police have ruled out robbery as a motive for the killing.","cn":"警方已排除因抢劫而杀人的可能。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"why something happens, or why someone does something","cn":""},{"en":"the reason why something happens, especially something bad","cn":""},{"en":"a set of reasons that helps you to understand why something happens, especially when it seems difficult to understand","cn":""}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"Your reason for doing something is your motive . Your motive to go to school every day is to learn. Or maybe the thought of your parents' anger and a run-in with the truant officer is motive enough."}]},"collocations":{"phrases":["ADJ. hidden, ulterior | clear, good, strong There seemed to be no clear motive for the attack. I'd say he had a very strong motive for wanti","VERB + MOTIVE be inspired by, have She knew that he was inspired by base motives. | establish, find, suggest The police are still trying to ","PREP. ~ in What was their motive in setting fire to the building? | ~ behind There is no doubt about the motive behind it all. | ~ for There"]},"media":{"uk":"media/ldoce/hwd/bre/4/motive_n0205.mp3","us":"media/ldoce/hwd/ame/b/motive1.mp3"},"examples":[{"en":"I have an ulterior motive in offering to help you.","cn":"我主动提出要帮助你是有私心的。"},{"en":"There seemed to be no motive for the murder.","cn":"这起谋杀案看不出有什么动机。"}],"oxford":{"phon":"ˈməʊtɪv","pos":"noun","senses":[{"en":"a reason for doing something","cn":"动机；原因；目的","ex":{"en":"There seemed to be no motive for the murder.","cn":"这起谋杀案看不出有什么动机。"}},{"en":"causing movement or action","cn":"发动的；导致运动的","ex":{"en":"motive power/force (= for example electricity to operate machinery)","cn":"原动力"},"pos":"adjective"}]}},"modem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调制解调器","en":"A modem is a device which uses a telephone line to connect computers or computer systems.","ex":{"en":"He sent his work to his publishers by modem.","cn":"他通过网络把作品发给了出版商。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of electronic equipment that allows information from one computer to be sent along telephone wires to another computer","cn":"调制解调器"}]},"vocab":{"pos":"n","senses":[{"en":"Simply put, a modem is an electronic device that changes a digital computer signal to audio so it can be carried on telephone lines. It also changes an incoming signal back so it can be read on the computer."}]},"collocations":{"phrases":["ADJ. data, facsimile, fax | external, internal | fast","VERB + MODEM connect, plug in | drive","MODEM + NOUN link Data is transmitted via a modem link to the central office.","PREP. via (a/the) ~ You can send the files to us on disk or via modem. •"]},"media":{"uk":"media/ldoce/hwd/bre/2/modem0205.mp3","us":"media/ldoce/hwd/ame/7/modem.mp3"},"oxford":{"phon":"ˈməʊdem","pos":"noun","senses":[{"en":"a device that is used at both ends of a connection between two computers to allow data to be sent over phone lines","cn":"调制解调器","ex":{"en":"Data is transmitted via a modem link to the central office.","cn":"数据通过调制解调器的连接传输到中央办公室。"}}]}},"mob":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暴民;乌合之众","en":"A mob is a large, disorganized, and often violent crowd of people.","ex":{"en":"Bottles and cans were hurled on the terraces by the mob","cn":"暴徒向看台扔瓶子和罐子。"}},{"pos":"N-SING 单数名词","cn":"大众（含贬义）；（尤指）愤怒暴乱的群众","en":"People sometimes use the mob to refer in a disapproving way to the majority of people in a country or place, especially when these people are behaving in a violent or uncontrolled way.","ex":{"en":"If they continue like this there is a danger of the mob taking over","cn":"如果他们继续这样下去，就有可能被暴动的群众控制局面。"}},{"pos":"N-SING 单数名词","cn":"黑社会；犯罪集团","en":"You can refer to the people involved in organized crime as the Mob .","ex":{"en":"...casinos that the Mob had operated","cn":"黑社会经营的赌场"}},{"pos":"VERB 动词","cn":"团团围住;成群围住","en":"If you say that someone is being mobbed by a crowd of people, you mean that the people are trying to talk to them or get near them in an enthusiastic or threatening way.","ex":{"en":"Her car was mobbed by the media","cn":"她的车被媒体团团围住了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several people together in the same place","cn":""},{"en":"a large group of people who have come to a place to do something","cn":""},{"en":"a large, noisy, and perhaps violent crowd","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A mob is a big, rowdy group of people. You might avoid shopping at the mall right before Christmas because you can't stand the mob of shoppers."}]},"collocations":{"phrases":["ADJ. angry, hostile, unruly | lynch","VERB + MOB break up, disperse","MOB + VERB attack sb/sth, set upon sb, surround sb/sth | chant (sth), shout (sth) a mob of chanting fans","MOB + NOUN rule the lawless days of mob rule and anarchy | violence"]},"media":{"uk":"media/ldoce/hwd/bre/1/mob_v0205.mp3","us":"media/ldoce/hwd/ame/6/mob1.mp3"},"examples":[{"en":"The mob was/were preparing to storm the building.","cn":"聚集的群众准备猛攻大楼。"},{"en":"All the usual mob were there.","cn":"所有帮派成员都在那里。"}],"oxford":{"phon":"mɒb","pos":"noun","senses":[{"en":"a large crowd of people, especially one that may become violent or cause trouble","cn":"人群；（尤指）暴民","g":"[countable, singular + singular or plural verb]","ex":{"en":"an angry/unruly mob","cn":"愤怒的／失控的暴民"}},{"en":"a group of people who are similar in some way","cn":"一群；一帮","g":"[countable, usually singular]","lab":"informal","ex":{"en":"All the usual mob were there.","cn":"那帮人都在那里。"}},{"en":"the people involved in organized crime; the Mafia","cn":"犯罪团伙；黑手党","g":"[singular]","lab":"informal"},{"en":"a group of animals","cn":"（动物的）群","g":"[countable]","lab":"Australian English, New Zealand English，，","ex":{"en":"a mob of cattle","cn":"一群牛"}},{"en":"if a crowd of birds or animals mob another bird or animal, they gather round it and attack it","cn":"（一群鸟或动物）围攻，聚众袭击","ex":{"en":"Adult birds come over to mob the predator while the chicks take cover.","cn":"成年鸟过来围攻捕食者，而小鸟则躲藏起来。"},"pos":"verb"},{"en":"if a person is mobbed by a crowd of people, the crowd gathers round them in order to see them and try and get their attention, sometimes in a slightly aggressive way","cn":"（人群）围聚，围住","g":"[usually passive]","ex":{"en":"The star was mobbed by eager fans.","cn":"这位明星被热情的粉丝团团围住了。"},"pos":"verb"}]}},"moratorium":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(行动或活动的)暂停，中止","en":"A moratorium on a particular activity or process is the stopping of it for a fixed period of time, usually as a result of an official agreement.","ex":{"en":"The House voted to impose a one-year moratorium on nuclear testing.","cn":"众议院投票表决将核试验暂停一年。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official stopping of an activity for a period of time 〔","cn":"官方对某项活动的〕暂停"},{"en":"a law or an agreement that gives people more time to pay their debts","cn":"允许延期偿债的法律[协议]"}]},"vocab":{"pos":"n","senses":[{"en":"A moratorium is the suspension of a particular activity––you could have a moratorium on fishing, baking, the use of candles, the wearing of matching socks."}]},"collocations":{"phrases":["ADJ. six-month, etc.","VERB + MORATORIUM impose, place | call for | announce, declare","PREP. ~ on/upon The government has called for a moratorium on weapons testing."]},"media":{"uk":"media/ldoce/hwd/bre/d/moratorium0205.mp3","us":"media/ldoce/hwd/ame/d/moratorium.mp3"},"examples":[{"en":"The convention called for a two-year moratorium on commercial whaling.","cn":"会议呼吁两年内暂停商业捕鲸活动。"},{"en":"a two-year moratorium on interest payments","cn":"两年延后付息"}],"oxford":{"phon":"ˌmɒrəˈtɔːriəm","pos":"noun","senses":[{"en":"a temporary stopping of an activity, especially by official agreement","cn":"暂停，中止（尤指经官方同意的）","ex":{"en":"The convention called for a two-year moratorium on commercial whaling.","cn":"会议呼吁两年内暂停商业捕鲸活动。"}}]}},"mortality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"死亡人数;死亡率","en":"The mortality in a particular place or situation is the number of people who die.","ex":{"en":"...the relationships between mortality and unemployment","cn":"死亡人数和失业人数之间的关系"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the number of deaths during a particular period of time among a particular type or group of people","cn":"死亡率﹔死亡数"},{"en":"the condition of being human and having to die","cn":"必死性﹐生命的有限性"},{"en":"a death","cn":"死亡"}]},"vocab":{"pos":"n","senses":[{"en":"One of the most difficult things for a child is experiencing the death of a beloved pet; it's a hard lesson in mortality . Mortality is the quality of being mortal , or the reality of death."}]},"collocations":{"phrases":["ADJ. high Poor hygiene led to high mortality among children. | adult, child, infant","VERB + MORTALITY reduce measures that should reduce infant mortality","MORTALITY + VERB increase | decrease, fall","MORTALITY + NOUN rate","PREP. ~ among Mortality among immigrant groups was higher than average. | ~ from a lower annual mortality from cancer","PHRASES a change/a decline/an increase in mortality"]},"media":{"uk":"media/ldoce/hwd/bre/9/mortality0205.mp3","us":"media/ldoce/hwd/ame/e/mortality.mp3"},"examples":[{"en":"After her mother's death, she became acutely aware of her own mortality.","cn":"她母亲去世后，她开始强烈意识到自己的生命是有限的。"},{"en":"Mortality from lung cancer is still increasing.","cn":"死于肺癌的人数仍在上升。"}],"oxford":{"phon":"mɔːˈtæləti","pos":"noun","senses":[{"en":"the state of being human and not living forever","cn":"生命的有限","g":"[uncountable]","ex":{"en":"After her mother's death, she became acutely aware of her own mortality.","cn":"她母亲去世后，她开始强烈意识到自己的生命是有限的。"}},{"en":"the number of deaths in a particular situation or period of time","cn":"死亡数量；死亡率","g":"[uncountable]","ex":{"en":"Mortality from lung cancer is still increasing.","cn":"死于肺癌的人数仍在上升。"}},{"en":"a death","cn":"死亡","g":"[countable]","lab":"specialist","ex":{"en":"hospital mortalities (= deaths in hospital)","cn":"医院里的死亡数字"}}]}},"monologue":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长篇大论;滔滔不绝的讲话","en":"If you refer to a long speech by one person during a conversation as a monologue, you mean it prevents other people from talking or expressing their opinions.","ex":{"en":"Morris ignored the question and continued his monologue.","cn":"莫里斯不理会这个问题，继续他的长篇大论。"}},{"pos":"N-VAR 可变名词","cn":"长篇独白;独角戏","en":"A monologue is a long speech which is spoken by one person as an entertainment, or as part of an entertainment such as a play.","ex":{"en":"...a monologue based on the writing of Quentin Crisp.","cn":"根据昆廷·克里斯普的作品改编的独角戏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long speech by one person","cn":"长篇独白"}]},"vocab":{"pos":"n","senses":[{"en":"A monologue is a speech delivered by one person, or a long one-sided conversation that makes you want to pull your hair out from boredom."}]},"collocations":{"phrases":["ADJ. long, rambling | short | comic, dramatic","VERB + MONOLOGUE deliver, do, go into, launch into, recite She delivered her monologue in a deadpan voice. an entertainer who does comic mon","PREP. ~ about She launched into a long monologue about how wonderful the company was. | ~ on He went straight into a rambling monologue on t"]},"media":{"uk":"media/ldoce/hwd/bre/9/monologue_las2_br.mp3","us":"media/ldoce/hwd/ame/a/monologue.mp3"},"examples":[{"en":"He went into a long monologue about life in America.","cn":"他开始滔滔不绝地谈起美国的生活。"},{"en":"a dramatic monologue","cn":"戏剧独白"}],"oxford":{"phon":"ˈmɒnəlɒɡ","pos":"noun","senses":[{"en":"a long speech by one person during a conversation that stops other people from speaking or expressing an opinion","cn":"滔滔不绝的讲话；个人的长篇大论","g":"[countable]","ex":{"en":"He went into a long monologue about life in America.","cn":"他开始滔滔不绝地谈起美国的生活。"}},{"en":"a long speech in a play, film, etc. spoken by one actor, especially when alone","cn":"（戏剧、电影等的）独白","g":"[uncountable, countable]","ex":{"en":"She delivered her monologue in a deadpan voice.","cn":"她故作严肃地说着独白。"}},{"en":"a dramatic story, especially in verse, told or performed by one person","cn":"独角戏","g":"[countable, uncountable]","ex":{"en":"an entertainer who does comic monologues","cn":"表演喜剧独白的演员"}}]}},"modify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"修改;变更;改进","en":"If you modify something, you change it slightly, usually in order to improve it.","ex":{"en":"The club members did agree to modify their recruitment policy","cn":"俱乐部成员的确同意修改吸纳新成员的政策。"}},{"pos":"VERB 动词","cn":"修饰;限定","en":"A word or group of words that modifies another word describes or classifies something, or restricts the meaning of the word.","ex":{"en":"It is a rule of English that adjectives generally precede the noun they modify: we say 'a good cry', not 'a cry good'.","cn":"英语规定形容词通常放在其修饰的名词前：我们说 a good cry，不说 a cry good。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change something so that it can be used in a different way","cn":""},{"en":"to make small changes to something such as a piece of equipment, a set of ideas, or a way of behaving in order to improve it or to make it more suitable for a particular purpose","cn":""},{"en":"to change something completely so that it has a different form and can be used for a different purpose","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To modify is to change or transform, but only slightly. If you miss your free-throws half the time, your coach will probably try to improve your shooting average by modifying your technique."}]},"collocations":{"phrases":["ADV. considerably, drastically, greatly, heavily, profoundly, radically, significantly, substantially The original text has been modified so","VERB + MODIFY have to, need to You may need to modify your plans a little.","PHRASES highly modified, in a modified form These ideas are still used today, though in a slightly modified form. | a modified version using"]},"media":{"uk":"media/ldoce/hwd/bre/b/modify0205.mp3","us":"media/ldoce/hwd/ame/3/modify.mp3"},"examples":[{"en":"In ‘walk slowly’, the adverb ‘slowly’ modifies the verb ‘walk’.","cn":"在 walk slowly 中，副词 slowly 修饰动词 walk。"},{"en":"The software we use has been modified for us.","cn":"我们使用的软件已按我们的需要作过修改。"}],"oxford":{"phon":"ˈmɒdɪfaɪ","pos":"verb","senses":[{"en":"to change something slightly, especially in order to make it more suitable for a particular purpose","cn":"调整；稍作修改；使更适合","ex":{"en":"Patients are taught how to modify their diet.","cn":"病人获得有关如何调节自己饮食的指导。"}},{"en":"to make something less extreme","cn":"缓和；使温和","ex":{"en":"She refused to modify her behaviour.","cn":"她拒绝缓和自己的行为方式。"}},{"en":"a word, such as an adjective or adverb, that modifies another word or group of words describes it or limits its meaning in some way","cn":"修饰","lab":"grammar","ex":{"en":"In ‘walk slowly’, the adverb ‘slowly’ modifies the verb ‘walk’.","cn":"在 walk slowly 中，副词 slowly 修饰动词 walk。"}}]}},"monument":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纪念碑","en":"A monument is a large structure, usually made of stone, which is built to remind people of an event in history or of a famous person."},{"pos":"N-COUNT 可数名词","cn":"历史遗迹;名胜","en":"A monument is something such as a castle or bridge which was built a very long time ago and is regarded as an important part of a country's history.","ex":{"en":"...the ancient monuments of England, Scotland and Wales.","cn":"英格兰、苏格兰和威尔士的名胜古迹"}},{"pos":"N-COUNT 可数名词","cn":"丰碑;典范","en":"If you describe something as a monument to someone's qualities, you mean that it is a very good example of the results or effects of those qualities.","ex":{"en":"By his international achievements he leaves a fitting monument to his beliefs.","cn":"他在国际上的成就为其信念作出了最好的注解。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building, statue , or other large structure that is built to remind people of an important event or famous person","cn":"纪念碑﹐纪念塔﹐纪念馆"},{"en":"a very old building or place that is important historically","cn":"遗迹﹐遗址﹐名胜古迹"},{"en":"to show clearly the result of someone’s qualities, beliefs, or actions","cn":"是某人/某事物的见证﹐是见证某人/某事物的丰碑"}]},"vocab":{"pos":"n","senses":[{"en":"A monument is a statue or other sculpture meant to honor a great person, like the Lincoln Monument or Washington Monument."}]},"collocations":{"phrases":["ADJ. ancient, historic | national, public | great | famous | fitting The new boat is a fitting monument to the crew members who lost their l","VERB + MONUMENT stand as The tower stands as a monument to the invasion of the island. | commission A monument has been commissioned in his ","MONUMENT + VERB be, stand The monument will stand just inside the cathedral. | survive Some of the town's Roman monuments still survive.","PREP. as a ~ | ~ of monuments of the army's past campaigns | ~ to The statue was built as a monument to victims of the war."]},"media":{"uk":"media/ldoce/hwd/bre/f/monument0205.mp3","us":"media/ldoce/hwd/ame/b/monument.mp3"},"examples":[{"en":"These recordings are a monument to his talent as a pianist.","cn":"这些录音是展现他钢琴家才华的不朽之作。"},{"en":"A monument to him was erected in St Paul's Cathedral.","cn":"在圣保罗大教堂为他修了一座纪念碑。"}],"oxford":{"phon":"ˈmɒnjumənt","pos":"noun","senses":[{"en":"a building, column, statue, etc. built to remind people of a famous person or event","cn":"纪念碑（或馆、堂、像等）","ex":{"en":"A monument to him was erected in St Paul's Cathedral.","cn":"在圣保罗大教堂为他修了一座纪念碑。"}},{"en":"a building that has special historical importance","cn":"历史遗迹；有历史价值的建筑","ex":{"en":"an ancient monument","cn":"古迹"}},{"en":"a thing that remains as a good example of somebody’s qualities or of what they did","cn":"丰碑；永久的典范","ex":{"en":"These recordings are a monument to his talent as a pianist.","cn":"这些录音是展现他钢琴家才华的不朽之作。"}}]}},"moor":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(主要生长杂草和石南的)高原贫瘠之地，荒野，旷野","en":"A moor is an area of open and usually high land with poor soil that is covered mainly with grass and heather.","ex":{"en":"Colliford is higher, right up on the moors","cn":"科利福德位置更高，就在荒野之上。"}},{"pos":"VERB 动词","cn":"（使）(船)停泊；系泊","en":"If you moor a boat somewhere, you stop and tie it to the land with a rope or chain so that it cannot move away.","ex":{"en":"She had moored her barge on the right bank of the river","cn":"她把驳船停泊在河右岸。"}},{"pos":"N-COUNT 可数名词","cn":"摩尔人(公元8至15世纪在北非和西班牙建立文明，信奉伊斯兰教)","en":"The Moors were a Muslim people who established a civilization in North Africa and Spain between the 8th and the 15th century A.D."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wild open area of high land, covered with rough grass or low bushes and heather , that is not farmed because the soil is not good enough","cn":"荒原﹐荒芜高地﹔高沼地"},{"en":"to fasten a ship or boat to the land or to the bottom of the sea using ropes or an anchor","cn":"系泊﹐（使）停泊"}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"To moor is to tie up a ship, as in to moor the ocean liner to the docks. Or, if you're reading Victorian literature, a moor could be a mossy meet-up spot."}]},"collocations":{"phrases":["ADJ. barren, bleak, desolate, open, wild, windswept","PREP. across the ~ the wind blowing across the moors | down from the ~ the slopes leading down from the moor | on the ~ We got lost on the m","PHRASES the edge of the moor"]},"media":{"uk":"media/ldoce/hwd/bre/9/moor0205.mp3","us":"media/ldoce/hwd/ame/7/moor1.mp3"},"examples":[{"en":"the Moorish architecture of Córdoba","cn":"科尔多瓦市的摩尔式建筑"},{"en":"They went grouse shooting up on the moors.","cn":"他们去荒野射猎松鸡。"}],"oxford":{"phon":"mɔː(r)","pos":"noun","senses":[{"en":"a high open area of land that is not used for farming, especially an area covered with rough grass and heather","cn":"旷野；荒野；高沼；漠泽","g":"[countable, usually plural]","ex":{"en":"the North York moors","cn":"北约克郡的漠泽"}},{"en":"land that consists of moors","cn":"高沼地","g":"[uncountable]","ex":{"en":"moor and rough grassland","cn":"高沼地和苍莽的草原"}},{"en":"to attach a boat, ship, etc. to a fixed object or to the land with a rope, or anchor it","cn":"（使）停泊；系泊","ex":{"en":"We moored off the north coast of the island.","cn":"我们停泊在岛的北部岸边。"},"pos":"verb"},{"en":"a member of a Muslim people of north-west Africa who ruled part of Spain until the 15th century","cn":"摩尔人（非洲西北部的穆斯林，15 世纪前统治西班牙部分地区）"}]}},"mobilize":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"动员;鼓动;召集；（人们）动员起来","en":"If you mobilize support or mobilize people to do something, you succeed in encouraging people to take action, especially political action. If people mobilize, they prepare to take action.","ex":{"en":"The best hope is that we will mobilize international support and get down to action","cn":"最好的希望是我们能争取到国际上的支持，然后采取行动。"}},{"pos":"VERB 动词","cn":"调动，动用(资源)","en":"If you mobilize resources, you start to use them or make them available for use.","ex":{"en":"If you could mobilize the resources, you could get it done.","cn":"如果你能够调集资源，就可以把这件事做成。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(国家或军队)动员起来;动员(军队)","en":"If a country mobilizes, or mobilizes its armed forces, or if its armed forces mobilize, they are given orders to prepare for a conflict.","ex":{"en":"Sudan even threatened to mobilize in response to the ultimatums","cn":"作为对最后通牒的回应，苏丹甚至威胁说要动员军队。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make plans or arrangements for something that will happen in the future, so that you will be ready when it happens","cn":""},{"en":"to do all the things you need to do to prepare for a special occasion or event","cn":""},{"en":"to do all the things you must do in order to prepare for an important event","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb mobilize to describe preparing something — or someone — to spring into action, or to be put into use. You might mobilize the troops, or even your classmates, into action."}]},"collocations":{"phrases":["ADV. effectively, successfully","PREP. against They successfully mobilized public opinion against him."]},"media":{"uk":"media/ldoce/hwd/bre/8/mobilize0205.mp3","us":"media/ldoce/hwd/ame/7/mobilize.mp3"},"examples":[{"en":"The unions mobilized thousands of workers in a protest against the cuts.","cn":"各级工会组织了数千名工人抗议削减工资。"},{"en":"They were unable to mobilize the resources they needed.","cn":"他们无法调用他们需要的资源。"}],"oxford":{"phon":"ˈməʊbəlaɪz","pos":"verb","senses":[{"en":"to work together in order to achieve a particular aim; to organize a group of people to do this","cn":"组织；鼓动；动员","g":"[transitive, intransitive]","ex":{"en":"The unions mobilized thousands of workers in a protest against the cuts.","cn":"各级工会组织了数千名工人抗议削减工资。"}},{"en":"to find and start to use something that is needed for a particular purpose","cn":"调动；调用","g":"[transitive]","ex":{"en":"They were unable to mobilize the resources they needed.","cn":"他们无法调用他们需要的资源。"}},{"en":"if a country mobilizes its army, or if a country or army mobilizes, it makes itself ready to fight in a war","cn":"（战时）动员","g":"[transitive, intransitive]","ex":{"en":"The troops were ordered to mobilize.","cn":"部队接到了动员令。"}}]}},"moderate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(政治观点或政策)温和的，不激进的","en":"Moderate political opinions or policies are not extreme.","ex":{"en":"He was an easygoing man of very moderate views","cn":"他的观点非常温和，容易相处。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或团体)温和的，稳健的","en":"You use moderate to describe people or groups who have moderate political opinions or policies.","ex":{"en":"...a moderate Democrat.","cn":"温和的民主党人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"中等的;普通的;适度的；适量的","en":"You use moderate to describe something that is neither large nor small in amount or degree.","ex":{"en":"While a moderate amount of stress can be beneficial, too much stress can exhaust you.","cn":"适度的压力是有好处的，但是压力太大会把人压垮。"}},{"pos":"ADJ 形容词","cn":"(变化)不大的，有限的","en":"A moderate change in something is a change that is not great.","ex":{"en":"Most drugs offer either no real improvement or, at best, only moderate improvements.","cn":"大多数药物要么不能使病情真正好转，要么最多只能带来轻微的改善。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)缓和;(使)减轻;(使)减弱;节制","en":"If you moderate something or if it moderates, it becomes less extreme or violent and easier to deal with or accept.","ex":{"en":"They are hoping that once in office he can be persuaded to moderate his views","cn":"他们希望等他一上台，可以说服他观点别那么激进。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having opinions or beliefs, especially about politics, that are not extreme and that most people consider reasonable or sensible","cn":""},{"en":"not including any extreme or important changes, and keeping to ordinary, safe political aims, especially in order to avoid criticism, opposition, or risk","cn":""},{"en":"the area of political opinion that most people agree about, even if they support different political parties","cn":""}]},"vocab":{"pos":"1 adj n v 2 v","senses":[{"en":"A moderate voter is someone who is politically speaking, in the center. In other words, they are not quite left or right, but somewhere in the middle."}]},"collocations":{"phrases":["VERBS be","ADV. very | fairly, quite, relatively a fairly moderate increase in the rate of inflation | surprisingly | politically"]},"media":{"uk":"media/ldoce/hwd/bre/c/moderate_adj0205.mp3","us":"media/ldoce/hwd/ame/b/l3moderate.mp3"},"examples":[{"en":"The team enjoyed only moderate success last season.","cn":"上个赛季，这个队伍只取得了中等成绩。"},{"en":"Even moderate amounts of the drug can be fatal.","cn":"这种药的用量即使不很大也会致命。"}],"oxford":{"phon":"ˈmɒdərət","pos":"adjective","senses":[{"en":"that is neither very good, large, hot, etc. nor very bad, small, cold, etc.","cn":"适度的；中等的","ex":{"en":"students of moderate ability","cn":"能力一般的学生"}},{"en":"having or showing opinions, especially about politics, that are not extreme","cn":"温和的；不激烈的；不偏激的","ex":{"en":"moderate views/policies","cn":"温和的见解／政策"}},{"en":"staying within limits that are considered to be reasonable by most people","cn":"适中的；合理的","ex":{"en":"a moderate drinker","cn":"不过多饮酒的人"}},{"en":"to become or make something become less extreme, severe, etc.","cn":"缓和；使适中","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"By evening the wind had moderated slightly.","cn":"到黄昏时，风稍稍减弱了。"},"pos":"verb"},{"en":"to check that an exam has been marked fairly and in the same way by different people","cn":"审核评分（查看不同阅卷人所打分数是否公平一致）","g":"[transitive, intransitive]","lab":"British English","pos":"verb"},{"en":"to be in charge of a discussion or debate and make sure it is fair","cn":"主持（讨论、辩论等）","g":"[transitive, intransitive]","ex":{"en":"The television debate was moderated by a law professor.","cn":"这场电视辩论由一位法学教授主持。"},"pos":"verb"},{"en":"to be responsible for preventing offensive material from being published on a website; to remove offensive material from a website","cn":"审核（网站内容）；删除（网站冒犯性内容）","g":"[transitive]","ex":{"en":"to moderate an internet forum","cn":"审核网络论坛"},"pos":"verb"},{"en":"a person who has opinions, especially about politics, that are not extreme","cn":"持温和观点者（尤指政见）","pos":"noun"}]}},"mourning":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"哀悼;伤逝","en":"Mourning is behaviour in which you show sadness about a person's death.","ex":{"en":"The period of mourning and bereavement may be long","cn":"丧亲和哀悼的悲伤会持续很久。"}},{"pos":"PHRASE 短语","cn":"服丧;戴孝;哀悼","en":"If you are in mourning, you are dressed or behaving in a particular way because someone you love or respect has died.","ex":{"en":"Yesterday the whole of Greece was in mourning","cn":"昨天希腊全民哀悼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to feel extremely sad because someone that you love has died","cn":""},{"en":"to feel sadness and respect for someone who has died, and to show this by the way you behave publicly, the clothes you wear etc","cn":""},{"en":"to feel very sad because someone has died, and to show this in the way you behave","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Mourning is a time of sadness because of a loss. When you're in mourning after a loved one dies, it is good to lean on your friends who understand why you are so sad."}]},"collocations":{"phrases":["ADJ. deep | national, official","VERB + MOURNING be in, go into He was in deep mourning for his dead wife.","MOURNING + NOUN clothes","PHRASES a day/period of mourning a day of mourning for the victims of the tragedy | a state of mourning 2 clothes","ADJ. full","VERB + MOURNING wear","PREP. in ~ She was still in full mourning six months after her son's death."]},"media":{"uk":"media/ldoce/hwd/bre/4/mourning0205.mp3","us":"media/ldoce/hwd/ame/b/mourning.mp3"},"examples":[{"en":"The government announced a day of national mourning for the victims.","cn":"政府宣布全国为受害者哀悼一日。"},{"en":"She was still in mourning for her husband.","cn":"她仍在为丈夫服丧。"}],"oxford":{"phon":"ˈmɔːnɪŋ","pos":"noun","senses":[{"en":"the feeling of being sad that you have and show because somebody has died","cn":"伤逝；哀悼","ex":{"en":"The government announced a day of national mourning for the victims.","cn":"政府宣布全国为受害者哀悼一日。"}},{"en":"clothes that people wear to show that they are sad at somebody’s death","cn":"丧服","ex":{"en":"The queen was dressed in mourning.","cn":"女王身着丧服。"}}]}},"moderation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"温和;中庸","en":"If you say that someone's behaviour shows moderation, you approve of them because they act in a way that you think is reasonable and not extreme.","ex":{"en":"The United Nations Secretary General called on all parties to show moderation.","cn":"联合国秘书长呼吁各方要表现出克制。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not too much - use this about eating, drinking, and other things that could be unhealthy if you did them too much","cn":""},{"en":"if you eat or drink something in moderation , you do not eat or drink too much of it","cn":""},{"en":"to not allow yourself to become so excited, annoyed etc by an event or situation that you lose a sense of what is reasonable, sensible, or possible","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Eating foods in moderation is a key to maintaining a healthy diet. That means you have a little bit of everything, rather than gorging, say, on steak and ice cream."}]},"collocations":{"phrases":["ADJ. great","VERB + MODERATION call for The government called for greater moderation on the part of the unions. | show","MODERATION + VERB be the key to sth Moderation is the key to good health.","PREP. in ~ Drinking alcohol is all right in moderation. | with ~ Always act with moderation."]},"media":{"uk":"media/ldoce/hwd/bre/7/moderation0205.mp3","us":"media/ldoce/hwd/ame/a/moderation.mp3"},"examples":[{"en":"There was a call for moderation on the part of the trade unions.","cn":"有人呼吁工会保持克制。"},{"en":"Alcohol should only ever be taken in moderation (= in small quantities).","cn":"酒只可少量饮用。"}],"oxford":{"phon":"ˌmɒdəˈreɪʃn","pos":"noun","senses":[{"en":"the quality of being reasonable and not being extreme","cn":"适度；适中；合理","ex":{"en":"There was a call for moderation on the part of the trade unions.","cn":"有人呼吁工会保持克制。"}},{"en":"the process of making sure that the same standards are used by different people in marking exams, etc.","cn":"评分审核制","lab":"British English"},{"en":"the process of checking content that is added to a website and removing any material that is offensive","cn":"（网站内容的）审核","ex":{"en":"Comment moderation makes people think twice before posting.","cn":"留言审核使人在发帖前三思而后行。"}}]}},"mound":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一)堆;(一)垛","en":"A mound of something is a large rounded pile of it.","ex":{"en":"The bulldozers piled up huge mounds of dirt","cn":"推土机堆起一堆一堆的泥土。"}},{"pos":"N-COUNT 可数名词","cn":"(棒球内场中央高出地面的)投球区土墩","en":"In baseball, the mound is the raised area where the pitcher stands when he or she throws the ball."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of things of the same type that are put on top of each other","cn":""},{"en":"a neat pile of things of the same type","cn":""},{"en":"a large messy pile of things","cn":""}]},"collocations":{"phrases":["ADJ. high, large The church stands on a high mound just outside the village. | low, small | grassy","PREP. on a/the ~ a small tree on a grassy mound","PHRASES the foot/top of a mound 2 pile","ADJ. great, huge, large | little, neat, small a neat mound of leaves","PREP. ~ of a great mound of paperwork"]},"media":{"uk":"media/ldoce/hwd/bre/7/mound0205.mp3","us":"media/ldoce/hwd/ame/1/mound.mp3"},"examples":[{"en":"The castle was built on top of a natural grassy mound.","cn":"这座城堡建在一个天然的绿草如茵的小丘上。"},{"en":"I've got a mound of paperwork to do.","cn":"我有一堆文案工作要做。"}],"oxford":{"phon":"maʊnd","pos":"noun","senses":[{"en":"a large pile of earth or stones; a small hill","cn":"土墩；小丘；小山岗","ex":{"en":"a Bronze Age burial mound","cn":"青铜时代的坟冢"}},{"en":"a pile","cn":"一堆","ex":{"en":"a small mound of rice/sand","cn":"一小堆米／沙子"}},{"en":"a large amount of something","cn":"许多；大量","lab":"informal","ex":{"en":"I've got a mound of paperwork to do.","cn":"我有一堆文案工作要做。"}},{"en":"the small raised area where the player who throws the ball (called the pitcher) stands","cn":"投球区土墩"}]}},"montana":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the northwestern US that has many mountains. It is the fourth largest state in the US, but has one of the smallest populations.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/p028-000008436.mp3","us":"media/ldoce/hwd/ame/1/p028-000008436.mp3"},"oxford":{"phon":"mɒnˈtænə","pos":"","senses":[{"en":"a large state in the north-western US, on the Canadian border. The capital city is Helena, and the largest city is Billings. Montana became a state in 1889, and is also called the Treasure State. It produces many minerals, and its mines once supplied half of all US copper . It also produces grain, potatoes, sheep and cattle. Montana's tourist attractions include the Rocky Mountains, Yellowstone National Park, the Glacier National Park and the Little Bighorn Battlefield National Monument.","cn":"蒙大拿（美国西北部与加拿大接界的大州，首府海伦娜，最大城市比灵斯）"}]}},"motorbike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 motorcycle","en":"A motorbike is the same as a motorcycle ."},{"pos":"N-COUNT 可数名词","cn":"轻骑；轻型摩托车","en":"A motorbike is a lighter, less powerful motorcycle."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small fast two-wheeled vehicle with an engine","cn":"摩托车"}]},"media":{"img":["media/ldoce/img/motorbike.jpg"],"uk":"media/ldoce/hwd/bre/1/motorbike0205.mp3","us":"media/ldoce/hwd/ame/e/motorbike.mp3"},"examples":[{"en":"Ben drove off on his motorbike.","cn":"本骑着摩托车走了。"}],"oxford":{"phon":"ˈməʊtəbaɪk","pos":"noun","senses":[{"en":"a road vehicle with two wheels, driven by an engine, with one seat for the driver and often a seat for a passenger behind the driver","cn":"摩托车","lab":"especially British English","ex":{"en":"Ben drove off on his motorbike.","cn":"本骑着摩托车走了。"}},{"en":"a bicycle that has a small engine","cn":"助力自行车；摩托自行车","lab":"North American English"}]}},"mongrel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杂种狗","en":"A mongrel is a dog which is a mixture of different breeds."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dog that is a mix of several different breeds","cn":"杂种狗"}]},"vocab":{"pos":"n","senses":[{"en":"Some people have purebred dogs, but you might have a mongrel — a mutt that is part this, part that, and part the other thing (but to you he's a 100 percent dog and your best friend)."}]},"media":{"uk":"media/ldoce/hwd/bre/f/mongrel0205.mp3","us":"media/ldoce/hwd/ame/f/mongrel.mp3"},"oxford":{"phon":"ˈmʌŋɡrəl","pos":"noun","senses":[{"en":"a dog that is a mixture of different types","cn":"杂种狗"}]}}});
